import { GoogleGenAI, Type } from "@google/genai";
import { SongData, AutoConfigData } from "../types";

export const generateSong = async (params: {
  prompt: string;
  references?: string;
  inspirations?: string;
  language: string;
  genres: string[];
  bpm: number;
  key: string;
  vocalType: string;
  linesPerSection: number;
  poemType: string;
  autoMelody: boolean;
  autoTitle: boolean;
  duration: number;
}): Promise<SongData> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const model = "gemini-3-pro-preview"; 

  const systemInstruction = `You are the K&N AI Music Songwriting Expert.
Your goal is to generate professional, soulful, and structurally sound songs.
Follow these guidelines:
1. Generate professional lyrics with tags: [Intro], [Verse], [Chorus], [Bridge], [Outro].
2. Structure the song for a target duration of ${params.duration} minutes.
3. Use the following references:
   - Style: ${params.references || 'General'}
   - Specific Song Inspirations: ${params.inspirations || 'None'}
4. Create a technical JSON object for Suno AI v3.5.
5. Strictly adhere to the requested poem type and lines per section.
6. If inspirations are provided, analyze their vibe, rhythm, or structure and incorporate similar professional elements.`;

  const userPrompt = `
    TOPIC/STORY: ${params.prompt}
    TARGET DURATION: ${params.duration} Minutes
    MUSICAL REFERENCES: ${params.references || 'N/A'}
    SONG INSPIRATIONS: ${params.inspirations || 'N/A'}
    LANGUAGE: ${params.language}
    GENRES: ${params.genres.join(', ')}
    TEMPO: ${params.bpm} BPM
    KEY: ${params.key}
    VOCAL STYLE: ${params.vocalType}
    POEM STRUCTURE: ${params.poemType} (${params.linesPerSection} lines per section)
    AUTO TITLE: ${params.autoTitle ? 'YES' : 'NO'}
  `;

  const response = await ai.models.generateContent({
    model,
    contents: userPrompt,
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          lyrics: { type: Type.STRING },
          duration_minutes: { type: Type.NUMBER },
          suno_config: {
            type: Type.OBJECT,
            properties: {
              style: { type: Type.STRING },
              tempo: { type: Type.STRING },
              key: { type: Type.STRING },
              vocal_description: { type: Type.STRING },
              mood: { type: Type.STRING },
              instrumentation: { type: Type.STRING }
            }
          },
          melody_suggestion: {
            type: Type.OBJECT,
            properties: {
              sections: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    name: { type: Type.STRING },
                    pattern: { type: Type.STRING },
                    chords: { type: Type.STRING }
                  }
                }
              }
            }
          }
        },
        required: ["title", "lyrics", "suno_config", "duration_minutes"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

export const analyzeAndConfigure = async (prompt: string, allowedGenres: string[]): Promise<AutoConfigData> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const model = "gemini-3-flash-preview";

  const systemInstruction = `Expert music producer. Suggest settings based on story depth.
  MANDATORY: You must select genres ONLY from this list: [${allowedGenres.join(', ')}].
  Return JSON with exactly matched genre names from the list.`;

  const response = await ai.models.generateContent({
    model,
    contents: `Analyze this music topic/mood: "${prompt}". Suggest settings.`,
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          language: { type: Type.STRING, description: "ไทย|อังกฤษ|จีน|อีสาน" },
          genres: { type: Type.ARRAY, items: { type: Type.STRING } },
          bpm: { type: Type.INTEGER },
          key: { type: Type.STRING },
          vocalType: { type: Type.STRING, description: "ชาย|หญิง|เด็กชาย|เด็กหญิง|Duet|Choir" },
          poemType: { type: Type.STRING, description: "กลอน 4|กลอน 8|ฟรีสไตล์" },
          linesPerSection: { type: Type.INTEGER },
          duration: { type: Type.NUMBER, description: "1-5 minutes" },
          reason: { type: Type.STRING }
        },
        required: ["language", "genres", "bpm", "key", "vocalType", "poemType", "linesPerSection", "duration", "reason"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

