  History
} from 'lucide-react';
import { generateSong, analyzeAndConfigure } from './services/geminiService';
import { SunoConfig } from './types';

declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }

  interface Window {
    readonly aistudio: AIStudio;
  }
}

const App: React.FC = () => {
  const [theme, setTheme] = useState<'dark' | 'light'>('dark');
  const [prompt, setPrompt] = useState(
    'บทเพลงรักที่ระเบิดอารมณ์ความเจ็บปวดจากการถูกหลอกไปสัมผัสสรวงสวรรแห่งความรัก ก่อนจะถูกทิ้งให้ร่วงหล่นลงมาเผชิญความจริงที่แสนทรมาน เป็นการตัดพ้อถึงวัฏจักรความรักเดิมๆ ที่วนเวียนมาทำร้ายซ้ำแล้วซ้ำเล่า จนตระหนักได้ว่าตัวเองเป็นเพียง ตัวสำรอง ในชีวิตของใครหลายคน'
  );
  const [references, setReferences] = useState('แนวพี่เสก Loso, Bodyslam, เพลงร็อคยุค 90');
  const [inspirations, setInspirations] = useState('');

  const [bpm, setBpm] = useState(60);
  const [key, setKey] = useState('F#m');
  const [duration, setDuration] = useState(3.5);
  const [vocalType, setVocalType] = useState('ชาย');
  const [selectedGenres, setSelectedGenres] = useState(['Rock', 'Alternative', 'Acoustic']);

  const [linesPerSection, setLinesPerSection] = useState(4);
  const [poemType, setPoemType] = useState('กลอน 4');
  const [language, setLanguage] = useState('ไทย');
  const [autoMelody, setAutoMelody] = useState(true);
  const [autoTitle, setAutoTitle] = useState(true);
  const [songTitle, setSongTitle] = useState('');

  const [isGenerating, setIsGenerating] = useState(false);
  const [isAutoConfiguring, setIsAutoConfiguring] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [successMsg, setSuccessMsg] = useState('');
  const [generatedLyrics, setGeneratedLyrics] = useState(``);
  const [jsonPrompt, setJsonPrompt] = useState<SunoConfig | null>(null);
  const [isApiConnected, setIsApiConnected] = useState(false);

  const genres = [
    'Pop', 'Rock', 'Jazz', 'Hip-hop', 'R&B', 'Country', 'Folk', 'Blues', 'Electronic',
    'Dance', 'House', 'Techno', 'Ambient', 'Classical', 'Reggae', 'Ska', 'Punk',
    'Metal', 'Alternative', 'Indie', 'Acoustic', 'Soul', 'Funk', 'Disco', 'Trap',
    'Lo-fi', 'Chill', 'Ballad'
  ];

  const languageOptions = [
    { value: 'ไทย', label: '🇹🇭 ภาษาไทย' },
    { value: 'อังกฤษ', label: '🇬🇧 English' },
    { value: 'จีน', label: '🇨🇳 中文' },
    { value: 'อีสาน', label: '🎭 ภาษาอีสาน' }
  ];

  useEffect(() => {
    checkApiKey();
    const saved = localStorage.getItem('kn-music-last-session');
    if (saved) {
      try {
        const data = JSON.parse(saved);
        setGeneratedLyrics(data.lyrics || '');
        setJsonPrompt(data.json || null);
        setSongTitle(data.songTitle || '');
        setReferences(data.references || '');
        setInspirations(data.inspirations || '');
        if (data.config) {
          setBpm(data.config.bpm ?? 60);
          setKey(data.config.key ?? 'F#m');
          setDuration(data.config.duration ?? 3.5);
          setVocalType(data.config.vocalType ?? 'ชาย');
          setSelectedGenres(data.config.selectedGenres ?? ['Rock', 'Alternative', 'Acoustic']);
          setLinesPerSection(data.config.linesPerSection ?? 4);
          setPoemType(data.config.poemType ?? 'กลอน 4');
          setLanguage(data.config.language ?? 'ไทย');
          setAutoMelody(data.config.autoMelody ?? true);
          setAutoTitle(data.config.autoTitle ?? true);
        }
      } catch (e) {
        console.error('Failed to load session', e);
      }
    }
  }, []);

  const checkApiKey = async () => {
    try {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      setIsApiConnected(hasKey);
    } catch (e) {
      console.error("Error checking API key:", e);
    }
  };

  const handleConnectApi = async () => {
    try {
      await window.aistudio.openSelectKey();
      setIsApiConnected(true);
      showStatus("API Connected Successfully");
    } catch (e) {
      setError("Failed to open API key selection dialog.");
    }
  };

  const showStatus = (msg: string) => {
    setSuccessMsg(msg);
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const toggleGenre = (genre: string) => {
    setSelectedGenres((prev) =>
      prev.includes(genre) ? prev.filter((g) => g !== genre) : [...prev, genre]
    );
  };

  const handleAutoConfigure = async () => {
    if (!prompt.trim()) return;
    setIsAutoConfiguring(true);
    setError(null);
    try {
      const data = await analyzeAndConfigure(prompt, genres);
      setLanguage(data.language);
      setBpm(data.bpm);
      setKey(data.key);
      setDuration(data.duration);
      setVocalType(data.vocalType);
      setPoemType(data.poemType);
      setLinesPerSection(data.linesPerSection);

      // Fix: Improved matching logic for genres
      if (data.genres && Array.isArray(data.genres)) {
        const matched = data.genres
          .map(g => g.trim())
          .filter(g => genres.some(ag => ag.toLowerCase() === g.toLowerCase()))
          .map(g => genres.find(ag => ag.toLowerCase() === g.toLowerCase())!);

        if (matched.length > 0) {
          setSelectedGenres(matched);
        }
      }

      showStatus(`ตั้งค่าอัตโนมัติแล้ว: ${data.reason}`);
    } catch (e: any) {
      if (e.message?.includes("Requested entity was not found")) {
        setIsApiConnected(false);
        setError("API Key Error: Please re-connect your API key.");
      } else {
        setError('ไม่สามารถตั้งค่าอัตโนมัติได้ กรุณาลองใหม่');
      }
    } finally {
      setIsAutoConfiguring(false);
    }
  };

  const handleGenerate = async () => {
    if (!prompt.trim()) return;
    setIsGenerating(true);
    setError(null);
    try {
      const data = await generateSong({
        prompt,
        references,
        inspirations,
        language,
        genres: selectedGenres,
        bpm,
        key,
        vocalType,
        linesPerSection,
        poemType,
        autoMelody,
        autoTitle,
        duration
      });
      setGeneratedLyrics(data.lyrics);
      setJsonPrompt(data.suno_config);
      if (autoTitle) setSongTitle(data.title);
      showStatus('แต่งเพลงสำเร็จแล้ว!');
    } catch (e: any) {
      if (e.message?.includes("Requested entity was not found")) {
        setIsApiConnected(false);
        setError("API Key expired or not found. Please click 'Connect API'.");
      } else {
        setError('เกิดข้อผิดพลาดในการเชื่อมต่อกับ AI กรุณาลองใหม่อีกครั้ง');
      }
    } finally {
      setIsGenerating(false);
    }
  };

  const handleCopy = async (text: any) => {
    if (!text) return;
    const content = typeof text === 'object' ? JSON.stringify(text, null, 2) : text;
    try {
      await navigator.clipboard.writeText(content);
      showStatus('คัดลอกสำเร็จ!');
    } catch (err) {
      showStatus('ไม่สามารถคัดลอกได้');
    }
  };

  const handleNewProject = () => {
    if (confirm('คุณต้องการสร้างโปรเจกต์ใหม่ใช่ไหม? ข้อมูลปัจจุบันจะหายไป')) {
      setPrompt('');
      setReferences('');
      setInspirations('');
      setGeneratedLyrics('');
      setJsonPrompt(null);
      setSongTitle('');
      showStatus('เริ่มโปรเจกต์ใหม่');
    }
  };

  const handleSave = () => {
    const data = {
      lyrics: generatedLyrics,
      json: jsonPrompt,
      prompt,
      references,
      inspirations,
      songTitle,
      config: { bpm, key, duration, vocalType, selectedGenres, linesPerSection, poemType, language, autoMelody, autoTitle }
    };
    localStorage.setItem('kn-music-last-session', JSON.stringify(data));
    showStatus('บันทึกข้อมูลสำเร็จ');
  };

  const handleExport = (type: 'lyrics' | 'json') => {
    let content = type === 'lyrics' ? generatedLyrics : JSON.stringify(jsonPrompt, null, 2);
    let filename = type === 'lyrics' ? 'lyrics.txt' : 'suno_config.json';
    if (!content) return;
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    link.click();
    URL.revokeObjectURL(url);
    showStatus(`ส่งออกไฟล์ ${filename} แล้ว`);
  };

  return (
    <div className={`min-h-screen transition-colors duration-300 ${theme === 'dark' ? 'bg-[#0a0a0a] text-white' : 'bg-gray-50 text-gray-900'}`}>
      {/* Header */}
      <header className={`sticky top-0 z-50 border-b backdrop-blur-md ${theme === 'dark' ? 'bg-[#111111]/80 border-gray-800' : 'bg-white/80 border-gray-200'}`}>
        <div className="max-w-7xl mx-auto px-6 py-4 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <div className="bg-gradient-to-br from-indigo-500 to-violet-600 p-2.5 rounded-2xl shadow-lg shadow-indigo-500/20">
              <Music className="w-6 h-6 text-white" strokeWidth={2.5} />
            </div>
            <div>
              <h1 className="text-xl md:text-2xl font-bold tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-white to-gray-500">
                K&N AI MUSIC
              </h1>
              <div className="flex items-center gap-2">
                <span className="text-[10px] md:text-xs text-indigo-400 font-semibold uppercase tracking-widest">Songwriting Studio</span>
                <span className={`flex items-center gap-1 text-[10px] font-bold px-1.5 py-0.5 rounded-md ${isApiConnected ? 'bg-green-500/10 text-green-500' : 'bg-red-500/10 text-red-500'}`}>
                  {isApiConnected ? <ShieldCheck size={10} /> : <ShieldAlert size={10} />}
                  {isApiConnected ? 'CONNECTED' : 'DISCONNECTED'}
                </span>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-3">
            {successMsg && (
              <div className="flex items-center gap-2 px-3 py-1.5 rounded-full text-xs font-medium bg-green-500/10 text-green-400 border border-green-500/20 animate-in fade-in zoom-in duration-300">
                <CheckCircle2 size={14} />
                <span>{successMsg}</span>
              </div>
            )}

            <button
              onClick={handleConnectApi}
              className={`flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold border transition-all ${
                isApiConnected 
                  ? 'bg-green-500/10 border-green-500/20 text-green-500 hover:bg-green-500/20' 
                  : 'bg-indigo-600 border-indigo-500 text-white hover:bg-indigo-700 shadow-lg shadow-indigo-500/20'
              }`}
            >
              <Zap size={14} fill={isApiConnected ? "currentColor" : "none"} />
              {isApiConnected ? 'RE-CONNECT API' : 'CONNECT API'}
            </button>

            <button
              onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')}
              className={`p-2.5 rounded-xl border transition-all ${theme === 'dark' ? 'bg-[#1a1a1a] border-gray-700 text-yellow-400' : 'bg-white border-gray-300 text-indigo-600'}`}
            >
              {theme === 'dark' ? <Sun size={18} /> : <Moon size={18} />}
            </button>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto p-4 md:p-6 grid grid-cols-1 lg:grid-cols-2 gap-6">

        {/* Left Side: Inputs */}
        <div className="space-y-6">

          {/* Section: Prompt */}
          <section className={`p-6 rounded-3xl border ${theme === 'dark' ? 'bg-[#111111] border-gray-800' : 'bg-white border-gray-200'}`}>
            <div className="flex justify-between items-center mb-4">
              <label className="text-sm font-bold flex items-center gap-2">
                <Sparkles size={16} className="text-indigo-500" />
                Story, Plot or Topic
              </label>
              <button
                onClick={handleAutoConfigure}
                disabled={isAutoConfiguring || !prompt.trim()}
                className={`px-3 py-1.5 rounded-xl text-xs font-bold flex items-center gap-2 border transition-all ${
                  isAutoConfiguring || !prompt.trim()
                    ? 'opacity-50 cursor-not-allowed border-gray-700'
                    : 'bg-indigo-500/10 border-indigo-500 text-indigo-400 hover:bg-indigo-500/20 shadow-md'
                }`}
              >
                {isAutoConfiguring ? <Loader2 className="animate-spin" size={14} /> : <Wand2 size={14} />}
                AI Settings
              </button>
            </div>
            <textarea
              value={prompt}
              onChange={(e) => setPrompt(e.target.value)}
              className={`w-full h-32 p-5 text-sm rounded-2xl resize-none focus:ring-2 focus:ring-indigo-500 outline-none border transition-all ${
                theme === 'dark' ? 'bg-[#0a0a0a] border-gray-800 text-gray-200' : 'bg-gray-50 border-gray-200 text-gray-800'
              }`}
              placeholder="Describe the story, the pain, the joy, or the concept of your song..."
            />

            <div className="mt-6 grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-4">
                <div>
                  <label className="text-xs font-bold text-gray-500 uppercase mb-2 flex items-center gap-2">
                    <Search size={12} /> Style References
                  </label>
                  <input
                    type="text"
                    value={references}
                    onChange={(e) => setReferences(e.target.value)}
                    className={`w-full p-3 text-sm rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none border transition-all ${
                      theme === 'dark' ? 'bg-[#0a0a0a] border-gray-800 text-gray-300' : 'bg-gray-50 border-gray-200 text-gray-700'
                    }`}
                    placeholder="e.g. Sek Loso, 90s Thai Rock"
                  />
                </div>
                <div>
                  <label className="text-xs font-bold text-gray-500 uppercase mb-2 flex items-center gap-2">
                    <Disc size={12} className="text-indigo-500" /> Musical Inspirations
                  </label>
                  <input
                    type="text"
                    value={inspirations}
                    onChange={(e) => setInspirations(e.target.value)}
                    className={`w-full p-3 text-sm rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none border transition-all ${
                      theme === 'dark' ? 'bg-[#0a0a0a] border-gray-800 text-gray-300' : 'bg-gray-50 border-gray-200 text-gray-700'
                    }`}
                    placeholder="e.g. Bohemian Rhapsody, Blinding Lights"
                  />
                </div>
              </div>
              <div className="space-y-4">
                <div>
                  <label className="text-xs font-bold text-gray-500 uppercase mb-2 flex items-center gap-2">
                    <TypeIcon size={12} /> Song Title
                  </label>
                  <input
                    type="text"
                    value={songTitle}
                    onChange={(e) => setSongTitle(e.target.value)}
                    className={`w-full p-3 text-sm rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none border transition-all ${
                      theme === 'dark' ? 'bg-[#0a0a0a] border-gray-800 text-gray-300' : 'bg-gray-50 border-gray-200 text-gray-700'
                    }`}
                    placeholder={autoTitle ? "Will be auto-generated..." : "Manually name your song"}
                  />
                </div>
                <div>
                  <label className="text-xs font-bold text-gray-500 uppercase mb-2 flex items-center gap-2">
                    <History size={12} /> Poem Type
                  </label>
                  <select
                    value={poemType}
                    onChange={(e) => setPoemType(e.target.value)}
                    className={`w-full p-3 text-sm rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none border transition-all ${
                      theme === 'dark' ? 'bg-[#0a0a0a] border-gray-800 text-indigo-400' : 'bg-gray-50 border-gray-200 text-indigo-600'
                    }`}
                  >
                    {['กลอน 4', 'กลอน 8', 'ฟรีสไตล์', 'English Verse'].map(p => <option key={p} value={p}>{p}</option>)}
                  </select>
                </div>
              </div>
            </div>
          </section>

          {/* AI Features Toggles */}
          <section className={`p-5 rounded-3xl border ${theme === 'dark' ? 'bg-[#111111] border-gray-800' : 'bg-white border-gray-200'}`}>
            <h3 className="text-xs font-bold text-gray-500 uppercase mb-4 flex items-center gap-2">
              <Settings2 size={14} /> AI Studio Features
            </h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <button
                onClick={() => setAutoTitle(!autoTitle)}
                className={`flex items-center justify-between px-4 py-3 rounded-2xl border transition-all ${
                  autoTitle 
                    ? 'bg-indigo-600/10 border-indigo-500/50 text-indigo-400' 
                    : 'bg-transparent border-gray-800 text-gray-500 hover:border-gray-700'
                }`}
              >
                <div className="flex items-center gap-3">
                  <div className={`p-1.5 rounded-lg ${autoTitle ? 'bg-indigo-500 text-white' : 'bg-gray-800 text-gray-500'}`}>
                    <Sparkles size={14} />
                  </div>
                  <span className="text-xs font-bold uppercase tracking-wide text-left">Auto-Generate Title</span>
                </div>
                {autoTitle && <Check size={16} />}
              </button>

              <button
                onClick={() => setAutoMelody(!autoMelody)}
                className={`flex items-center justify-between px-4 py-3 rounded-2xl border transition-all ${
                  autoMelody 
                    ? 'bg-violet-600/10 border-violet-500/50 text-violet-400' 
                    : 'bg-transparent border-gray-800 text-gray-500 hover:border-gray-700'
                }`}
              >
                <div className="flex items-center gap-3">
                  <div className={`p-1.5 rounded-lg ${autoMelody ? 'bg-violet-500 text-white' : 'bg-gray-800 text-gray-500'}`}>
                    <Music size={14} />
                  </div>
                  <span className="text-xs font-bold uppercase tracking-wide text-left">Melody Assistant</span>
                </div>
                {autoMelody && <Check size={16} />}
              </button>
            </div>
          </section>

          {/* Section: Settings Grid */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className={`p-5 rounded-3xl border ${theme === 'dark' ? 'bg-[#111111] border-gray-800' : 'bg-white border-gray-200'}`}>
              <h3 className="text-xs font-bold text-gray-500 uppercase mb-4 flex items-center gap-2">
                <Globe size={14} /> Language
              </h3>
              <div className="grid grid-cols-2 gap-2">
                {languageOptions.map((lang) => (
                  <button
                    key={lang.value}
                    onClick={() => setLanguage(lang.value)}
                    className={`px-3 py-2 rounded-xl text-xs font-medium transition-all ${
                      language === lang.value
                        ? 'bg-indigo-600 text-white'
                        : theme === 'dark' ? 'bg-[#1a1a1a] text-gray-400 hover:bg-[#222]' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                    }`}
                  >
                    {lang.label}
                  </button>
                ))}
              </div>
            </div>

            <div className={`p-5 rounded-3xl border ${theme === 'dark' ? 'bg-[#111111] border-gray-800' : 'bg-white border-gray-200'}`}>
              <h3 className="text-xs font-bold text-gray-500 uppercase mb-4">Vocal Type</h3>
              <select
                value={vocalType}
                onChange={(e) => setVocalType(e.target.value)}
                className={`w-full p-2.5 rounded-xl text-sm font-semibold outline-none border ${
                  theme === 'dark' ? 'bg-[#1a1a1a] border-gray-700 text-indigo-400' : 'bg-gray-50 border-gray-200 text-indigo-600'
                }`}
              >
                {['ชาย', 'หญิง', 'เด็กชาย', 'เด็กหญิง', 'Duet', 'Choir'].map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>

            <div className={`p-5 rounded-3xl border ${theme === 'dark' ? 'bg-[#111111] border-gray-800' : 'bg-white border-gray-200'}`}>
              <div className="flex justify-between items-center mb-4">
                <h3 className="text-xs font-bold text-gray-500 uppercase">Tempo (BPM)</h3>
                <span className="text-xs font-bold text-indigo-500 uppercase">{bpm} BPM</span>
              </div>
              <input
                type="range"
                min="40"
                max="200"
                value={bpm}
                onChange={(e) => setBpm(parseInt(e.target.value))}
                className="w-full accent-indigo-500"
              />
            </div>

            <div className={`p-5 rounded-3xl border ${theme === 'dark' ? 'bg-[#111111] border-gray-800' : 'bg-white border-gray-200'}`}>
              <div className="flex justify-between items-center mb-4">
                <h3 className="text-xs font-bold text-gray-500 uppercase">Duration</h3>
                <span className="text-xs font-bold text-indigo-500 uppercase">
                  {Math.floor(duration)}:{Math.round((duration % 1) * 60).toString().padStart(2, '0')} Mins
                </span>
              </div>
              <div className="flex items-center gap-3">
                <Clock size={16} className="text-gray-500" />
                <input
                  type="range"
                  min="1"
                  max="5"
                  step="0.5"
                  value={duration}
                  onChange={(e) => setDuration(parseFloat(e.target.value))}
                  className="w-full accent-indigo-500"
                />
              </div>
              <div className="flex justify-between mt-1 text-[10px] text-gray-500 font-bold uppercase">
                <span>Short</span>
                <span>Standard</span>
                <span>Extended</span>
              </div>
            </div>

            <div className={`p-5 rounded-3xl border ${theme === 'dark' ? 'bg-[#111111] border-gray-800' : 'bg-white border-gray-200'}`}>
              <h3 className="text-xs font-bold text-gray-500 uppercase mb-4">Key</h3>
              <select
                value={key}
                onChange={(e) => setKey(e.target.value)}
                className={`w-full p-2.5 rounded-xl text-sm font-semibold outline-none border ${
                  theme === 'dark' ? 'bg-[#1a1a1a] border-gray-700 text-indigo-400' : 'bg-gray-50 border-gray-200 text-indigo-600'
                }`}
              >
                {['C', 'Cm', 'C#', 'C#m', 'D', 'Dm', 'Eb', 'E', 'Em', 'F', 'Fm', 'F#', 'F#m', 'G', 'Gm', 'Ab', 'A', 'Am', 'Bb', 'B', 'Bm'].map(k => <option key={k} value={k}>{k}</option>)}
              </select>
            </div>
          </div>

          {/* Genre Chips */}
          <section className={`p-6 rounded-3xl border ${theme === 'dark' ? 'bg-[#111111] border-gray-800' : 'bg-white border-gray-200'}`}>
            <h3 className="text-xs font-bold text-gray-500 uppercase mb-4">Genres</h3>
            <div className="flex flex-wrap gap-2 max-h-32 overflow-y-auto">
              {genres.map(genre => (
                <button
                  key={genre}
                  onClick={() => toggleGenre(genre)}
                  className={`px-3 py-1.5 rounded-full text-[10px] font-bold uppercase tracking-wider transition-all border ${
                    selectedGenres.includes(genre)
                      ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg shadow-indigo-500/20'
                      : theme === 'dark' ? 'bg-[#1a1a1a] border-gray-700 text-gray-500' : 'bg-gray-100 border-gray-200 text-gray-600'
                  }`}
                >
                  {genre}
                </button>
              ))}
            </div>
          </section>

          {/* Generate Button */}
          <button
            onClick={handleGenerate}
            disabled={isGenerating || !prompt.trim() || !isApiConnected}
            className={`w-full py-5 rounded-3xl font-bold text-lg flex items-center justify-center gap-3 transition-all transform hover:scale-[1.01] active:scale-[0.99] shadow-xl ${
              isGenerating || !prompt.trim() || !isApiConnected
                ? 'bg-gray-800 text-gray-500 cursor-not-allowed grayscale'
                : 'bg-gradient-to-r from-indigo-600 to-violet-700 text-white shadow-indigo-500/20'
            }`}
          >
            {isGenerating ? (
              <>
                <Loader2 className="animate-spin" size={24} />
                <span>Crafting {Math.floor(duration)} Min Masterpiece...</span>
              </>
            ) : (
              <>
                <Sparkles size={24} />
                <span>GENERATE SONG</span>
              </>
            )}
          </button>

          {error && (
            <div className="p-4 rounded-2xl bg-red-500/10 border border-red-500/20 text-red-400 text-xs font-bold flex flex-col gap-2">
              <div className="flex items-center gap-3">
                <AlertCircle size={18} />
                <span>{error}</span>
              </div>
              {error.includes("API Key") && (
                <button onClick={handleConnectApi} className="underline text-left">Connect API Now</button>
              )}
            </div>
          )}
        </div>

        {/* Right Side: Output */}
        <div className="space-y-6 flex flex-col h-full">
          {/* Toolbar */}
          <div className="flex flex-wrap gap-2">
            <ToolButton onClick={handleNewProject} icon={<Plus size={16} />} label="New" theme={theme} />
            <ToolButton onClick={handleSave} icon={<Save size={16} />} label="Save" theme={theme} />
            <ToolButton onClick={() => handleCopy(generatedLyrics)} icon={<Clipboard size={16} />} label="Copy Lyrics" theme={theme} disabled={!generatedLyrics} />
            <ToolButton onClick={() => handleExport('lyrics')} icon={<Download size={16} />} label="Export TXT" theme={theme} disabled={!generatedLyrics} />
          </div>

          {/* Lyrics Container */}
          <section className={`flex-1 rounded-3xl border flex flex-col overflow-hidden min-h-[400px] ${theme === 'dark' ? 'bg-[#111111] border-gray-800' : 'bg-white border-gray-200'}`}>
            <div className={`px-6 py-4 border-b flex justify-between items-center ${theme === 'dark' ? 'border-gray-800' : 'border-gray-200'}`}>
              <h3 className="text-sm font-bold flex items-center gap-2 uppercase tracking-widest">
                <FileText size={16} className="text-indigo-500" />
                Recording Script
              </h3>
            </div>

            <div className="flex-1 p-8 overflow-y-auto font-serif text-lg md:text-xl leading-relaxed whitespace-pre-wrap relative">
              {!generatedLyrics && !isGenerating && (
                <div className="h-full flex flex-col items-center justify-center text-gray-500 opacity-50 space-y-4 text-center">
                  <Music size={64} strokeWidth={1} />
                  <p className="text-sm font-medium">Draft your prompt and hit generate to begin</p>
                </div>
              )}
              {isGenerating && (
                <div className="space-y-6">
                  <div className="h-12 w-3/4 rounded-2xl bg-indigo-500/10 animate-pulse" />
                  <div className="h-4 w-1/2 rounded-full bg-indigo-500/5 animate-pulse" />
                  {[...Array(5)].map((_, i) => (
                    <div key={i} className={`h-4 rounded-full ${theme === 'dark' ? 'bg-gray-800' : 'bg-gray-200'} animate-pulse`} style={{ width: `${60 + Math.random() * 40}%` }} />
                  ))}
                </div>
              )}
              {generatedLyrics && (
                <div className="animate-in fade-in slide-in-from-bottom-4 duration-700">
                  {songTitle && (
                    <div className="mb-8 pb-8 border-b border-dashed border-gray-700">
                      <h2 className="text-4xl md:text-5xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-500 to-violet-600 mb-2">
                        {songTitle}
                      </h2>
                      <div className="flex flex-wrap gap-x-4 gap-y-1 text-xs font-bold uppercase tracking-widest text-gray-500">
                        <span className="flex items-center gap-1"><Clock size={10} /> {Math.floor(duration)}:{Math.round((duration % 1) * 60).toString().padStart(2, '0')}</span>
                        <span>Genre: {selectedGenres.join(', ')}</span>
                        <span>Tempo: {bpm} BPM</span>
                        <span>Key: {key}</span>
                        <span>Vocal: {vocalType}</span>
                        {inspirations && <span className="text-indigo-400">Inspiration: {inspirations}</span>}
                      </div>
                    </div>
                  )}
                  <div className={`${theme === 'dark' ? 'text-gray-200' : 'text-gray-800'}`}>
                    {generatedLyrics}
                  </div>
                </div>
              )}
            </div>
          </section>

          {/* Metadata Section */}
          <section className={`h-48 rounded-3xl border flex flex-col overflow-hidden ${theme === 'dark' ? 'bg-[#111111] border-gray-800' : 'bg-white border-gray-200'}`}>
            <div className={`px-6 py-3 border-b flex justify-between items-center ${theme === 'dark' ? 'border-gray-800' : 'border-gray-200'}`}>
              <h3 className="text-[10px] font-bold text-gray-500 uppercase flex items-center gap-2">
                <div className={`w-2 h-2 rounded-full ${jsonPrompt ? 'bg-green-500 shadow-[0_0_8px_green]' : 'bg-gray-700'}`} />
                Production Metadata
              </h3>
              <button onClick={() => handleCopy(jsonPrompt)} disabled={!jsonPrompt} className="text-[10px] font-bold text-indigo-500 disabled:opacity-50">COPY JSON</button>
            </div>
            <div className="flex-1 p-4 overflow-y-auto bg-black/10 font-mono text-xs text-indigo-400">
              {jsonPrompt ? <pre>{JSON.stringify(jsonPrompt, null, 2)}</pre> : <div className="h-full flex items-center justify-center opacity-30 italic">No metadata generated yet</div>}
            </div>
          </section>
        </div>
      </main>

      <footer className={`px-6 py-4 border-t ${theme === 'dark' ? 'bg-[#0a0a0a] border-gray-800' : 'bg-white border-gray-200'}`}>
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-center gap-4 text-[10px] font-bold uppercase tracking-widest text-gray-500">
          <div className="flex items-center gap-6">
            <span className="flex items-center gap-2"><span className="w-1.5 h-1.5 rounded-full bg-green-500"></span> Gemini 3 Pro Enabled</span>
            <span>© 2026 K&N AI MUSIC STUDIO</span>
          </div>
        </div>
      </footer>
    </div>
  );
};

interface ToolButtonProps {
  icon: React.ReactNode;
  label: string;
  onClick: () => void;
  theme: 'dark' | 'light';
  disabled?: boolean;
}

const ToolButton: React.FC<ToolButtonProps> = ({ icon, label, onClick, theme, disabled }) => (
  <button
    onClick={onClick}
    disabled={disabled}
    className={`flex items-center gap-2 px-4 py-2 text-[10px] font-bold uppercase tracking-wider rounded-xl border transition-all ${
      disabled 
        ? 'opacity-40 cursor-not-allowed grayscale' 
        : 'hover:border-indigo-500 hover:shadow-lg active:scale-95'
    } ${theme === 'dark' ? 'bg-[#1a1a1a] border-gray-700 text-gray-400' : 'bg-white border-gray-200 text-gray-600'}`}
  >
    <span className="text-indigo-500">{icon}</span>
    <span>{label}</span>
  </button>
);

export default App;

import React, { useState, useEffect } from 'react';
import {
  Music,
  Save,
  FileText,
  Clipboard,
  Loader2,
  Sparkles,
  CheckCircle2,
  AlertCircle,
  Download,
  Plus,
  Zap,
  Globe,
  Wand2,
  Moon,
  Sun,
  ShieldCheck,
  ShieldAlert,
  Search,
  Settings2,
  Check,
  Type as TypeIcon,
  Clock,
  Disc,
  History
} from 'lucide-react';
import { generateSong, analyzeAndConfigure } from './services/geminiService';
import { SunoConfig } from './types';

declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }

  interface Window {
    // Removed readonly to match environment's existing declaration modifiers
    aistudio: AIStudio;
  }
}

const App: React.FC = () => {
  const [theme, setTheme] = useState<'dark' | 'light'>('dark');
  const [prompt, setPrompt] = useState(
    'บทเพลงรักที่ระเบิดอารมณ์ความเจ็บปวดจากการถูกหลอกไปสัมผัสสรวงสวรรแห่งความรัก ก่อนจะถูกทิ้งให้ร่วงหล่นลงมาเผชิญความจริงที่แสนทรมาน เป็นการตัดพ้อถึงวัฏจักรความรักเดิมๆ ที่วนเวียนมาทำร้ายซ้ำแล้วซ้ำเล่า จนตระหนักได้ว่าตัวเองเป็นเพียง ตัวสำรอง ในชีวิตของใครหลายคน'
  );
  const [references, setReferences] = useState('แนวพี่เสก Loso, Bodyslam, เพลงร็อคยุค 90');
  const [inspirations, setInspirations] = useState('');

  const [bpm, setBpm] = useState(60);
  const [key, setKey] = useState('F#m');
  const [duration, setDuration] = useState(3.5);
  const [vocalType, setVocalType] = useState('ชาย');
  const [selectedGenres, setSelectedGenres] = useState(['Rock', 'Alternative', 'Acoustic']);

  const [linesPerSection, setLinesPerSection] = useState(4);
  const [poemType, setPoemType] = useState('กลอน 4');
  const [language, setLanguage] = useState('ไทย');
  const [autoMelody, setAutoMelody] = useState(true);
  const [autoTitle, setAutoTitle] = useState(true);
  const [songTitle, setSongTitle] = useState('');

  const [isGenerating, setIsGenerating] = useState(false);
  const [isAutoConfiguring, setIsAutoConfiguring] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [successMsg, setSuccessMsg] = useState('');
  const [generatedLyrics, setGeneratedLyrics] = useState(``);
  const [jsonPrompt, setJsonPrompt] = useState<SunoConfig | null>(null);
  const [isApiConnected, setIsApiConnected] = useState(false);

  const genres = [
    'Pop', 'Rock', 'Jazz', 'Hip-hop', 'R&B', 'Country', 'Folk', 'Blues', 'Electronic',
    'Dance', 'House', 'Techno', 'Ambient', 'Classical', 'Reggae', 'Ska', 'Punk',
    'Metal', 'Alternative', 'Indie', 'Acoustic', 'Soul', 'Funk', 'Disco', 'Trap',
    'Lo-fi', 'Chill', 'Ballad'
  ];

  const languageOptions = [
    { value: 'ไทย', label: '🇹🇭 ภาษาไทย' },
    { value: 'อังกฤษ', label: '🇬🇧 English' },
    { value: 'จีน', label: '🇨🇳 中文' },
    { value: 'อีสาน', label: '🎭 ภาษาอีสาน' }
  ];

  useEffect(() => {
    checkApiKey();
    const saved = localStorage.getItem('kn-music-last-session');
    if (saved) {
      try {
        const data = JSON.parse(saved);
        setGeneratedLyrics(data.lyrics || '');
        setJsonPrompt(data.json || null);
        setSongTitle(data.songTitle || '');
        setReferences(data.references || '');
        setInspirations(data.inspirations || '');
        if (data.config) {
          setBpm(data.config.bpm ?? 60);
          setKey(data.config.key ?? 'F#m');
          setDuration(data.config.duration ?? 3.5);
          setVocalType(data.config.vocalType ?? 'ชาย');
          setSelectedGenres(data.config.selectedGenres ?? ['Rock', 'Alternative', 'Acoustic']);
          setLinesPerSection(data.config.linesPerSection ?? 4);
          setPoemType(data.config.poemType ?? 'กลอน 4');
          setLanguage(data.config.language ?? 'ไทย');
          setAutoMelody(data.config.autoMelody ?? true);
          setAutoTitle(data.config.autoTitle ?? true);
        }
      } catch (e) {
        console.error('Failed to load session', e);
      }
    }
  }, []);

  const checkApiKey = async () => {
    try {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      setIsApiConnected(hasKey);
    } catch (e) {
      console.error("Error checking API key:", e);
    }
  };

  const handleConnectApi = async () => {
    try {
      await window.aistudio.openSelectKey();
      setIsApiConnected(true);
      showStatus("API Connected Successfully");
    } catch (e) {
      setError("Failed to open API key selection dialog.");
    }
  };

  const showStatus = (msg: string) => {
    setSuccessMsg(msg);
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const toggleGenre = (genre: string) => {
    setSelectedGenres((prev) =>
      prev.includes(genre) ? prev.filter((g) => g !== genre) : [...prev, genre]
    );
  };

  const handleAutoConfigure = async () => {
    if (!prompt.trim()) return;
    setIsAutoConfiguring(true);
    setError(null);
    try {
      const data = await analyzeAndConfigure(prompt, genres);
      setLanguage(data.language);
      setBpm(data.bpm);
      setKey(data.key);
      setDuration(data.duration);
      setVocalType(data.vocalType);
      setPoemType(data.poemType);
      setLinesPerSection(data.linesPerSection);

      if (data.genres && Array.isArray(data.genres)) {
        const matched = data.genres
          .map(g => g.trim())
          .filter(g => genres.some(ag => ag.toLowerCase() === g.toLowerCase()))
          .map(g => genres.find(ag => ag.toLowerCase() === g.toLowerCase())!);

        if (matched.length > 0) {
          setSelectedGenres(matched);
        }
      }

      showStatus(`ตั้งค่าอัตโนมัติแล้ว: ${data.reason}`);
    } catch (e: any) {
      if (e.message?.includes("Requested entity was not found")) {
        setIsApiConnected(false);
        setError("API Key Error: Please re-connect your API key.");
      } else {
        setError('ไม่สามารถตั้งค่าอัตโนมัติได้ กรุณาลองใหม่');
      }
    } finally {
      setIsAutoConfiguring(false);
    }
  };

  const handleGenerate = async () => {
    if (!prompt.trim()) return;
    setIsGenerating(true);
    setError(null);
    try {
      const data = await generateSong({
        prompt,
        references,
        inspirations,
        language,
        genres: selectedGenres,
        bpm,
        key,
        vocalType,
        linesPerSection,
        poemType,
        autoMelody,
        autoTitle,
        duration
      });
      setGeneratedLyrics(data.lyrics);
      setJsonPrompt(data.suno_config);
      if (autoTitle) setSongTitle(data.title);
      showStatus('แต่งเพลงสำเร็จแล้ว!');
    } catch (e: any) {
      if (e.message?.includes("Requested entity was not found")) {
        setIsApiConnected(false);
        setError("API Key expired or not found. Please click 'Connect API'.");
      } else {
        setError('เกิดข้อผิดพลาดในการเชื่อมต่อกับ AI กรุณาลองใหม่อีกครั้ง');
      }
    } finally {
      setIsGenerating(false);
    }
  };

  const handleCopy = async (text: any) => {
    if (!text) return;
    const content = typeof text === 'object' ? JSON.stringify(text, null, 2) : text;
    try {
      await navigator.clipboard.writeText(content);
      showStatus('คัดลอกสำเร็จ!');
    } catch (err) {
      showStatus('ไม่สามารถคัดลอกได้');
    }
  };

  const handleNewProject = () => {
    if (confirm('คุณต้องการสร้างโปรเจกต์ใหม่ใช่ไหม? ข้อมูลปัจจุบันจะหายไป')) {
      setPrompt('');
      setReferences('');
      setInspirations('');
      setGeneratedLyrics('');
      setJsonPrompt(null);
      setSongTitle('');
      showStatus('เริ่มโปรเจกต์ใหม่');
    }
  };

  const handleSave = () => {
    const data = {
      lyrics: generatedLyrics,
      json: jsonPrompt,
      prompt,
      references,
      inspirations,
      songTitle,
      config: { bpm, key, duration, vocalType, selectedGenres, linesPerSection, poemType, language, autoMelody, autoTitle }
    };
    localStorage.setItem('kn-music-last-session', JSON.stringify(data));
    showStatus('บันทึกข้อมูลสำเร็จ');
  };

  const handleExport = (type: 'lyrics' | 'json') => {
    let content = type === 'lyrics' ? generatedLyrics : JSON.stringify(jsonPrompt, null, 2);
    let filename = type === 'lyrics' ? 'lyrics.txt' : 'suno_config.json';
    if (!content) return;
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    link.click();
    URL.revokeObjectURL(url);
    showStatus(`ส่งออกไฟล์ ${filename} แล้ว`);
  };

  return (
    <div className={`min-h-screen transition-colors duration-300 ${theme === 'dark' ? 'bg-[#0a0a0a] text-white' : 'bg-gray-50 text-gray-900'}`}>
      {/* Header */}
      <header className={`sticky top-0 z-50 border-b backdrop-blur-md ${theme === 'dark' ? 'bg-[#111111]/80 border-gray-800' : 'bg-white/80 border-gray-200'}`}>
        <div className="max-w-7xl mx-auto px-6 py-4 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <div className="bg-gradient-to-br from-indigo-500 to-violet-600 p-2.5 rounded-2xl shadow-lg shadow-indigo-500/20">
              <Music className="w-6 h-6 text-white" strokeWidth={2.5} />
            </div>
            <div>
              <h1 className="text-xl md:text-2xl font-bold tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-white to-gray-500">
                K&N AI MUSIC
              </h1>
              <div className="flex items-center gap-2">
                <span className="text-[10px] md:text-xs text-indigo-400 font-semibold uppercase tracking-widest">Songwriting Studio</span>
                <span className={`flex items-center gap-1 text-[10px] font-bold px-1.5 py-0.5 rounded-md ${isApiConnected ? 'bg-green-500/10 text-green-500' : 'bg-red-500/10 text-red-500'}`}>
                  {isApiConnected ? <ShieldCheck size={10} /> : <ShieldAlert size={10} />}
                  {isApiConnected ? 'CONNECTED' : 'DISCONNECTED'}
                </span>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-3">
            {successMsg && (
              <div className="flex items-center gap-2 px-3 py-1.5 rounded-full text-xs font-medium bg-green-500/10 text-green-400 border border-green-500/20 animate-in fade-in zoom-in duration-300">
                <CheckCircle2 size={14} />
                <span>{successMsg}</span>
              </div>
            )}

            <button
              onClick={handleConnectApi}
              className={`flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold border transition-all ${
                isApiConnected 
                  ? 'bg-green-500/10 border-green-500/20 text-green-500 hover:bg-green-500/20' 
                  : 'bg-indigo-600 border-indigo-500 text-white hover:bg-indigo-700 shadow-lg shadow-indigo-500/20'
              }`}
            >
              <Zap size={14} fill={isApiConnected ? "currentColor" : "none"} />
              {isApiConnected ? 'RE-CONNECT API' : 'CONNECT API'}
            </button>

            <button
              onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')}
              className={`p-2.5 rounded-xl border transition-all ${theme === 'dark' ? 'bg-[#1a1a1a] border-gray-700 text-yellow-400' : 'bg-white border-gray-300 text-indigo-600'}`}
            >
              {theme === 'dark' ? <Sun size={18} /> : <Moon size={18} />}
            </button>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto p-4 md:p-6 grid grid-cols-1 lg:grid-cols-2 gap-6">

        {/* Left Side: Inputs */}
        <div className="space-y-6">

          {/* Section: Prompt */}
          <section className={`p-6 rounded-3xl border ${theme === 'dark' ? 'bg-[#111111] border-gray-800' : 'bg-white border-gray-200'}`}>
            <div className="flex justify-between items-center mb-4">
              <label className="text-sm font-bold flex items-center gap-2">
                <Sparkles size={16} className="text-indigo-500" />
                Story, Plot or Topic
              </label>
              <button
                onClick={handleAutoConfigure}
                disabled={isAutoConfiguring || !prompt.trim()}
                className={`px-3 py-1.5 rounded-xl text-xs font-bold flex items-center gap-2 border transition-all ${
                  isAutoConfiguring || !prompt.trim()
                    ? 'opacity-50 cursor-not-allowed border-gray-700'
                    : 'bg-indigo-500/10 border-indigo-500 text-indigo-400 hover:bg-indigo-500/20 shadow-md'
                }`}
              >
                {isAutoConfiguring ? <Loader2 className="animate-spin" size={14} /> : <Wand2 size={14} />}
                AI Settings
              </button>
            </div>
            <textarea
              value={prompt}
              onChange={(e) => setPrompt(e.target.value)}
              className={`w-full h-32 p-5 text-sm rounded-2xl resize-none focus:ring-2 focus:ring-indigo-500 outline-none border transition-all ${
                theme === 'dark' ? 'bg-[#0a0a0a] border-gray-800 text-gray-200' : 'bg-gray-50 border-gray-200 text-gray-800'
              }`}
              placeholder="Describe the story, the pain, the joy, or the concept of your song..."
            />

            <div className="mt-6 grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-4">
                <div>
                  <label className="text-xs font-bold text-gray-500 uppercase mb-2 flex items-center gap-2">
                    <Search size={12} /> Style References
                  </label>
                  <input
                    type="text"
                    value={references}
                    onChange={(e) => setReferences(e.target.value)}
                    className={`w-full p-3 text-sm rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none border transition-all ${
                      theme === 'dark' ? 'bg-[#0a0a0a] border-gray-800 text-gray-300' : 'bg-gray-50 border-gray-200 text-gray-700'
                    }`}
                    placeholder="e.g. Sek Loso, 90s Thai Rock"
                  />
                </div>
                <div>
                  <label className="text-xs font-bold text-gray-500 uppercase mb-2 flex items-center gap-2">
                    <Disc size={12} className="text-indigo-500" /> Musical Inspirations
