            <input type="range" min="1" max="5" step="0.5" value={duration} onChange={(e) => setDuration(parseFloat(e.target.value))} className="w-full accent-indigo-500" />
          </div>
        </SectionCard>
        <SectionCard theme={theme} className="!p-5">
          <h3 className="text-xs font-bold text-gray-500 uppercase mb-4">Key</h3>
          <select
            value={keyName}
            onChange={(e) => setKeyName(e.target.value)}
            className={`w-full p-2.5 rounded-xl text-sm font-semibold outline-none border ${
              theme === 'dark' ? 'bg-[#1a1a1a] border-gray-700 text-indigo-400' : 'bg-gray-50 border-gray-200 text-indigo-600'
            }`}
          >
            {['C', 'Cm', 'C#', 'C#m', 'D', 'Dm', 'Eb', 'E', 'Em', 'F', 'Fm', 'F#', 'F#m', 'G', 'Gm', 'Ab', 'A', 'Am', 'Bb', 'B', 'Bm'].map(k => <option key={k} value={k}>{k}</option>)}
          </select>
        </SectionCard>
      </div>

      {/* Genres */}
      <SectionCard theme={theme}>
        <h3 className="text-xs font-bold text-gray-500 uppercase mb-4">Genres</h3>
        <div className="flex flex-wrap gap-2 max-h-32 overflow-y-auto">
          {genres.map(genre => (
            <button
              key={genre}
              onClick={() => toggleGenre(genre)}
              className={`px-3 py-1.5 rounded-full text-[10px] font-bold uppercase tracking-wider transition-all border ${
                selectedGenres.includes(genre)
                  ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg shadow-indigo-500/20'
                  : theme === 'dark' ? 'bg-[#1a1a1a] border-gray-700 text-gray-500' : 'bg-gray-100 border-gray-200 text-gray-600'
              }`}
            >
              {genre}
            </button>
          ))}
        </div>
      </SectionCard>

      {/* Main Action */}
      <button
        onClick={handleGenerate}
        disabled={isGenerating || !prompt.trim() || !isApiConnected}
        className={`w-full py-5 rounded-3xl font-bold text-lg flex items-center justify-center gap-3 transition-all transform hover:scale-[1.01] active:scale-[0.99] shadow-xl ${
          isGenerating || !prompt.trim() || !isApiConnected
            ? 'bg-gray-800 text-gray-500 cursor-not-allowed grayscale'
            : 'bg-gradient-to-r from-indigo-600 to-violet-700 text-white shadow-indigo-500/20'
        }`}
      >
        {isGenerating ? <><Loader2 className="animate-spin" size={24} /><span>Crafting with {modelOptions.find(m => m.value === selectedModel)?.label}...</span></> : <><Sparkles size={24} /><span>GENERATE SONG</span></>}
      </button>

      {error && (
        <div className="p-4 rounded-2xl bg-red-500/10 border border-red-500/20 text-red-400 text-xs font-bold flex flex-col gap-2">
          <div className="flex items-center gap-3"><AlertCircle size={18} /><span>{error}</span></div>
          {error.includes("API Key") && <button onClick={handleConnectApi} className="underline text-left">Connect API Now</button>}
        </div>
      )}
    </div>
  );
};

