import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import Editor from './components/Editor';
import Footer from './components/Footer';
import { generateSong, analyzeAndConfigure, generateCoverImage } from './services/geminiService';
import { SunoConfig } from './types';

// Fix: Augment global AIStudio interface and use it in Window declaration with 'readonly' modifier 
// to match system-provided types and avoid "identical modifiers" or "subsequent property declaration" errors.
declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }

  interface Window {
    readonly aistudio: AIStudio;
  }
}

const App: React.FC = () => {
  // Appearance
  const [theme, setTheme] = useState<'dark' | 'light'>('dark');
  const [successMsg, setSuccessMsg] = useState('');
  const [error, setError] = useState<string | null>(null);

  // Core Data
  const [prompt, setPrompt] = useState('บทเพลงรักที่ระเบิดอารมณ์ความเจ็บปวด...');
  const [references, setReferences] = useState('แนวพี่เสก Loso, Bodyslam, เพลงร็อคยุค 90');
  const [inspirations, setInspirations] = useState('');
  const [songTitle, setSongTitle] = useState('');
  const [generatedLyrics, setGeneratedLyrics] = useState(``);
  const [jsonPrompt, setJsonPrompt] = useState<SunoConfig | null>(null);

  // Model Selection
  // Fix: Updated model names to follow @google/genai guidelines.
  const modelOptions = [
    { value: 'gemini-3-pro-preview', label: 'Gemini 3 Pro', description: 'Best for complex songwriting and deep lyrics.' },
    { value: 'gemini-3-flash-preview', label: 'Gemini 3 Flash', description: 'Faster performance, excellent for quick drafts.' },
    { value: 'gemini-flash-latest', label: 'Gemini Flash', description: 'Standard reliable model for text generation.' },
    { value: 'gemini-flash-lite-latest', label: 'Gemini Flash Lite', description: 'Lightweight model, efficient for simple tasks.' }
  ];
  const [selectedModel, setSelectedModel] = useState('gemini-3-pro-preview');

  // Configuration
  const [bpm, setBpm] = useState(60);
  const [keyName, setKeyName] = useState('F#m');
  const [duration, setDuration] = useState(3.5);
  const [vocalType, setVocalType] = useState('ชาย');
  const [selectedGenres, setSelectedGenres] = useState(['Rock', 'Alternative', 'Acoustic']);
  const [poemType, setPoemType] = useState('กลอน 4');
  const [language, setLanguage] = useState('ไทย');
  const [autoTitle, setAutoTitle] = useState(true);
  const [autoMelody, setAutoMelody] = useState(true);

  // Assets
  const [coverImage, setCoverImage] = useState<string | null>(null);
  const [imageStyle, setImageStyle] = useState('Cinematic');
  const [imageAspectRatio, setImageAspectRatio] = useState<"1:1" | "16:9" | "9:16">("1:1");

  // Status
  const [isGenerating, setIsGenerating] = useState(false);
  const [isAutoConfiguring, setIsAutoConfiguring] = useState(false);
  const [isGeneratingImage, setIsGeneratingImage] = useState(false);
  const [isApiConnected, setIsApiConnected] = useState(false);

  // Constants
  const genres = ['Pop', 'Rock', 'Jazz', 'Hip-hop', 'R&B', 'Country', 'Folk', 'Blues', 'Electronic', 'Dance', 'House', 'Techno', 'Ambient', 'Classical', 'Reggae', 'Ska', 'Punk', 'Metal', 'Alternative', 'Indie', 'Acoustic', 'Soul', 'Funk', 'Disco', 'Trap', 'Lo-fi', 'Chill', 'Ballad'];
  const imageStyles = ['Cinematic', 'Digital Art', 'Oil Painting', 'Synthwave', 'Anime', 'Photorealistic', 'Neon Punk', 'Minimalist', 'Vintage Photo'];
  const languageOptions = [{ value: 'ไทย', label: '🇹🇭 ภาษาไทย' }, { value: 'อังกฤษ', label: '🇬🇧 English' }, { value: 'จีน', label: '🇨🇳 中文' }, { value: 'อีสาน', label: '🎭 ภาษาอีสาน' }];

  useEffect(() => {
    checkApiKey();
    const saved = localStorage.getItem('kn-music-last-session');
    if (saved) {
      try {
        const data = JSON.parse(saved);
        setGeneratedLyrics(data.lyrics || '');
        setJsonPrompt(data.json || null);
        setSongTitle(data.songTitle || '');
        setReferences(data.references || '');
        setInspirations(data.inspirations || '');
        setCoverImage(data.coverImage || null);
        if (data.selectedModel) setSelectedModel(data.selectedModel);
        if (data.config) {
          setBpm(data.config.bpm ?? 60);
          setKeyName(data.config.keyName ?? 'F#m');
          setDuration(data.config.duration ?? 3.5);
          setVocalType(data.config.vocalType ?? 'ชาย');
          setSelectedGenres(data.config.selectedGenres ?? ['Rock', 'Alternative', 'Acoustic']);
          setPoemType(data.config.poemType ?? 'กลอน 4');
          setLanguage(data.config.language ?? 'ไทย');
          setAutoTitle(data.config.autoTitle ?? true);
          setAutoMelody(data.config.autoMelody ?? true);
        }
      } catch (e) {}
    }
  }, []);

  const checkApiKey = async () => {
    try {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      setIsApiConnected(hasKey);
    } catch (e) {}
  };

  const handleConnectApi = async () => {
    try {
      await window.aistudio.openSelectKey();
      // To mitigate race conditions, assume selection was successful.
      setIsApiConnected(true);
      showStatus("API Connected Successfully");
    } catch (e) {
      setError("Failed to open API selection.");
    }
  };

  const showStatus = (msg: string) => {
    setSuccessMsg(msg);
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const toggleGenre = (genre: string) => {
    setSelectedGenres((prev) => prev.includes(genre) ? prev.filter((g) => g !== genre) : [...prev, genre]);
  };

  const handleAutoConfigure = async () => {
    if (!prompt.trim()) return;
    setIsAutoConfiguring(true);
    setError(null);
    try {
      // Use flash model for quick analysis regardless of main selection to save tokens if desired, 
      // but here we use selectedModel for consistency if user wants to specifically use one.
      const data = await analyzeAndConfigure(prompt, genres, selectedModel);
      setLanguage(data.language);
      setBpm(data.bpm);
      setKeyName(data.key);
      setDuration(data.duration);
      setVocalType(data.vocalType);
      setPoemType(data.poemType);
      if (data.genres && Array.isArray(data.genres)) {
        const matched = data.genres.filter(g => genres.includes(g));
        if (matched.length > 0) setSelectedGenres(matched);
      }
      showStatus(`Auto-configured: ${data.reason}`);
    } catch (e: any) {
      setError('Auto-config failed. Please retry.');
    } finally {
      setIsAutoConfiguring(false);
    }
  };

  const handleGenerate = async () => {
    if (!prompt.trim()) return;
    setIsGenerating(true);
    setError(null);
    try {
      const data = await generateSong({ 
        prompt, references, inspirations, language, genres: selectedGenres, bpm, key: keyName, 
        vocalType, linesPerSection: 4, poemType, autoMelody, autoTitle, duration, 
        model: selectedModel 
      });
      setGeneratedLyrics(data.lyrics);
      setJsonPrompt(data.suno_config);
      if (autoTitle) setSongTitle(data.title);
      showStatus('Masterpiece crafted!');
    } catch (e: any) {
      // If requested entity not found, prompt to re-connect the API key.
      if (e.message?.includes("Requested entity was not found.")) {
        setIsApiConnected(false);
        setError("API Session expired. Please re-connect.");
        await handleConnectApi();
      } else {
        setError('Generation failed. Please check API connection.');
      }
    } finally {
      setIsGenerating(false);
    }
  };

  const handleGenerateImage = async () => {
    if (!prompt.trim()) return;
    setIsGeneratingImage(true);
    setError(null);
    try {
      const imgUrl = await generateCoverImage({ prompt: songTitle || prompt.substring(0, 50), aspectRatio: imageAspectRatio, style: imageStyle });
      setCoverImage(imgUrl);
      showStatus('Cover art ready!');
    } catch (e: any) {
      if (e.message?.includes("Requested entity was not found.")) {
        setIsApiConnected(false);
        await handleConnectApi();
      } else {
        setError('Image generation failed.');
      }
    } finally {
      setIsGeneratingImage(false);
    }
  };

  const handleCopy = async (text: any) => {
    if (!text) return;
    const content = typeof text === 'object' ? JSON.stringify(text, null, 2) : text;
    try {
      await navigator.clipboard.writeText(content);
      showStatus('Copied!');
    } catch (err) {}
  };

  const handleNewProject = () => {
    if (confirm('Create new project? Current work will be lost.')) {
      setPrompt('');
      setReferences('');
      setInspirations('');
      setGeneratedLyrics('');
      setJsonPrompt(null);
      setSongTitle('');
      setCoverImage(null);
      showStatus('New project started');
    }
  };

  const handleSave = () => {
    const data = { 
      lyrics: generatedLyrics, 
      json: jsonPrompt, 
      prompt, 
      references, 
      inspirations, 
      songTitle, 
      coverImage, 
      selectedModel,
      config: { bpm, keyName, duration, vocalType, selectedGenres, poemType, language, autoTitle, autoMelody } 
    };
    localStorage.setItem('kn-music-last-session', JSON.stringify(data));
    showStatus('Project saved offline');
  };

  const handleExport = (type: 'lyrics' | 'json' | 'image') => {
    if (type === 'image' && coverImage) {
      const link = document.createElement('a');
      link.href = coverImage;
      link.download = `cover-${songTitle || 'song'}.png`;
      link.click();
      return;
    }
    const content = type === 'lyrics' ? generatedLyrics : JSON.stringify(jsonPrompt, null, 2);
    const filename = type === 'lyrics' ? 'lyrics.txt' : 'suno_config.json';
    if (!content) return;
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url; link.download = filename; link.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className={`min-h-screen transition-colors duration-300 ${theme === 'dark' ? 'bg-[#0a0a0a] text-white' : 'bg-gray-50 text-gray-900'}`}>
      <Header theme={theme} setTheme={setTheme} isApiConnected={isApiConnected} onConnectApi={handleConnectApi} successMsg={successMsg} />

      <main className="max-w-7xl mx-auto p-4 md:p-6 grid grid-cols-1 lg:grid-cols-2 gap-6">
        <Sidebar 
          theme={theme} prompt={prompt} setPrompt={setPrompt} references={references} setReferences={setReferences} 
          inspirations={inspirations} setInspirations={setInspirations} songTitle={songTitle} setSongTitle={setSongTitle} 
          bpm={bpm} setBpm={setBpm} keyName={keyName} setKeyName={setKeyName} duration={duration} setDuration={setDuration} 
          vocalType={vocalType} setVocalType={setVocalType} poemType={poemType} setPoemType={setPoemType} 
          language={language} setLanguage={setLanguage} autoTitle={autoTitle} setAutoTitle={setAutoTitle} 
          autoMelody={autoMelody} setAutoMelody={setAutoMelody} selectedGenres={selectedGenres} toggleGenre={toggleGenre} 
          genres={genres} imageAspectRatio={imageAspectRatio} setImageAspectRatio={setImageAspectRatio} 
          imageStyle={imageStyle} setImageStyle={setImageStyle} imageStyles={imageStyles} languageOptions={languageOptions} 
          isAutoConfiguring={isAutoConfiguring} isGenerating={isGenerating} isGeneratingImage={isGeneratingImage} 
          isApiConnected={isApiConnected} handleAutoConfigure={handleAutoConfigure} handleGenerate={handleGenerate} 
          handleGenerateImage={handleGenerateImage} handleConnectApi={handleConnectApi} error={error}
          selectedModel={selectedModel} setSelectedModel={setSelectedModel} modelOptions={modelOptions}
        />

        <Editor 
          theme={theme} generatedLyrics={generatedLyrics} songTitle={songTitle} duration={duration} 
          selectedGenres={selectedGenres} bpm={bpm} keyName={keyName} inspirations={inspirations} 
          isGenerating={isGenerating} coverImage={coverImage} imageAspectRatio={imageAspectRatio} 
          jsonPrompt={jsonPrompt} handleNewProject={handleNewProject} handleSave={handleSave} 
          handleCopy={handleCopy} handleExport={handleExport}
        />
      </main>

      <Footer theme={theme} />
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { SongData, AutoConfigData, ImageGenerationParams } from "../types";

export const generateSong = async (params: {
  prompt: string;
  references?: string;
  inspirations?: string;
  language: string;
  genres: string[];
  bpm: number;
  key: string;
  vocalType: string;
  linesPerSection: number;
  poemType: string;
  autoMelody: boolean;
  autoTitle: boolean;
  duration: number;
  model: string;
}): Promise<SongData> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `You are the K&N AI Music Songwriting Expert.
Your goal is to generate professional, soulful, and structurally sound songs optimized for Suno AI v3.5.

CRITICAL GUIDELINES FOR MUSICALITY:
1. MUSICAL FLOW: Do NOT make it sound like a dry school recital. Even if a "Poem Type" is selected, prioritize contemporary "Thai Pop/Rock/Modern" phrasing. 
2. PHRASING: Use "Kam-Suay" (beautiful, emotive Thai words). Break lines where a singer would naturally breathe.
3. RHYTHM: If "กลอน 8" or "กลอน 4" is selected, treat it as a rhythmic pulse, not a rigid syllable count. Add slight variations in line length to create a dynamic melody.
4. EMOTIONAL TAGS: Use tags like [Intro], [Verse], [Chorus], [Bridge], [Outro].
5. DURATION: Structure the song to fit roughly ${params.duration} minutes.
6. REFERENCES: Incorporate the vibe of: ${params.references || 'General Modern Style'}.
7. INSPIRATIONS: Analyze the rhythmic structure of ${params.inspirations || 'None'} and use a similar professional flow.`;

  const userPrompt = `
    TOPIC: ${params.prompt}
    LYRICAL STYLE: Contemporary song based on "${params.poemType}" rhythm.
    TARGET DURATION: ${params.duration} Minutes
    MUSICAL REFERENCES: ${params.references || 'N/A'}
    SONG INSPIRATIONS: ${params.inspirations || 'N/A'}
    LANGUAGE: ${params.language}
    GENRES: ${params.genres.join(', ')}
    TEMPO: ${params.bpm} BPM
    KEY: ${params.key}
    VOCAL STYLE: ${params.vocalType}
    AUTO TITLE: ${params.autoTitle ? 'YES' : 'NO'}

    TASK: Generate lyrics that feel like a real hit song. Avoid the "recital" feel. Make it flow naturally with the music.
  `;

  const response = await ai.models.generateContent({
    model: params.model,
    contents: userPrompt,
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          lyrics: { type: Type.STRING },
          duration_minutes: { type: Type.NUMBER },
          suno_config: {
            type: Type.OBJECT,
            properties: {
              style: { type: Type.STRING },
              tempo: { type: Type.STRING },
              key: { type: Type.STRING },
              vocal_description: { type: Type.STRING },
              mood: { type: Type.STRING },
              instrumentation: { type: Type.STRING }
            }
          },
          melody_suggestion: {
            type: Type.OBJECT,
            properties: {
              sections: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    name: { type: Type.STRING },
                    pattern: { type: Type.STRING },
                    chords: { type: Type.STRING }
                  }
                }
              }
            }
          }
        },
        required: ["title", "lyrics", "suno_config", "duration_minutes"]
      }
    }
  });

  const text = response.text?.trim();
  return JSON.parse(text || '{}');
};

export const analyzeAndConfigure = async (prompt: string, allowedGenres: string[], model: string): Promise<AutoConfigData> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `Expert music producer. Suggest settings based on story depth.
  MANDATORY: You must select genres ONLY from this list: [${allowedGenres.join(', ')}].
  Return JSON with exactly matched genre names from the list. Suggest a "Poem Type" that fits the mood (e.g., Free Style for Rap/Rock, Poem 8 for Ballads).`;

  const response = await ai.models.generateContent({
    model,
    contents: `Analyze this music topic/mood: "${prompt}". Suggest settings.`,
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          language: { type: Type.STRING, description: "ไทย|อังกฤษ|จีน|อีสาน" },
          genres: { type: Type.ARRAY, items: { type: Type.STRING } },
          bpm: { type: Type.INTEGER },
          key: { type: Type.STRING },
          vocalType: { type: Type.STRING, description: "ชาย|หญิง|เด็กชาย|เด็กหญิง|Duet|Choir" },
          poemType: { type: Type.STRING, description: "กลอน 4|กลอน 8|ฟรีสไตล์" },
          linesPerSection: { type: Type.INTEGER },
          duration: { type: Type.NUMBER, description: "1-5 minutes" },
          reason: { type: Type.STRING }
        },
        required: ["language", "genres", "bpm", "key", "vocalType", "poemType", "linesPerSection", "duration", "reason"]
      }
    }
  });

  const text = response.text?.trim();
  return JSON.parse(text || '{}');
};

export const generateCoverImage = async (params: ImageGenerationParams): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const model = 'gemini-2.5-flash-image';

  const fullPrompt = `A high-quality music album cover. Title/Theme: "${params.prompt}". Style: ${params.style}. Professional composition, artistic, evocative.`;

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        { text: fullPrompt }
      ]
    },
    config: {
      imageConfig: {
        aspectRatio: params.aspectRatio
      }
    }
  });

  for (const part of response.candidates[0].content.parts) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }

  throw new Error('No image was generated by the model.');
};

import React, { useState, useEffect, useRef } from 'react';
import { Sparkles, Mic, MicOff, Loader2, Wand2, Search, Disc, Type as TypeIcon, History } from 'lucide-react';
import { SectionCard } from '../SharedUI';

interface StorySectionProps {
  theme: 'dark' | 'light';
  prompt: string;
  setPrompt: (v: string) => void;
  references: string;
  setReferences: (v: string) => void;
  inspirations: string;
  setInspirations: (v: string) => void;
  songTitle: string;
  setSongTitle: (v: string) => void;
  poemType: string;
  setPoemType: (v: string) => void;
  language: string;
  autoTitle: boolean;
  isAutoConfiguring: boolean;
  handleAutoConfigure: () => void;
}

export const StorySection: React.FC<StorySectionProps> = (props) => {
  const { theme, prompt, setPrompt, references, setReferences, inspirations, setInspirations, songTitle, setSongTitle, poemType, setPoemType, language, autoTitle, isAutoConfiguring, handleAutoConfigure } = props;
  const [isListening, setIsListening] = useState(false);
  const recognitionRef = useRef<any>(null);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.continuous = true;
      recognitionRef.current.interimResults = true;
      const langMap: Record<string, string> = { 'ไทย': 'th-TH', 'อังกฤษ': 'en-US', 'จีน': 'zh-CN', 'อีสาน': 'th-TH' };
      recognitionRef.current.lang = langMap[language] || 'th-TH';
      recognitionRef.current.onresult = (event: any) => {
        let finalTranscript = '';
        for (let i = event.resultIndex; i < event.results.length; ++i) {
          if (event.results[i].isFinal) finalTranscript += event.results[i][0].transcript;
        }
        if (finalTranscript) setPrompt(prompt + (prompt ? ' ' : '') + finalTranscript);
      };
      recognitionRef.current.onerror = () => setIsListening(false);
      recognitionRef.current.onend = () => setIsListening(false);
    }
    return () => recognitionRef.current?.stop();
  }, [language, prompt, setPrompt]);

  const toggleListening = () => {
    if (isListening) { recognitionRef.current?.stop(); setIsListening(false); }
    else { try { recognitionRef.current?.start(); setIsListening(true); } catch (e) { console.error(e); } }
  };

  return (
    <SectionCard theme={theme}>
      <div className="flex justify-between items-center mb-4">
        <label className="text-sm font-bold flex items-center gap-2">
          <Sparkles size={16} className="text-indigo-500" /> Story, Plot or Topic
        </label>
        <div className="flex gap-2">
          <button onClick={toggleListening} className={`p-1.5 rounded-lg transition-all border ${isListening ? 'bg-red-500/20 border-red-500 text-red-500 animate-pulse' : theme === 'dark' ? 'bg-gray-800 border-gray-700 text-gray-400 hover:text-white' : 'bg-gray-100 border-gray-200 text-gray-600 hover:text-indigo-600'}`}>
            {isListening ? <Mic size={16} /> : <MicOff size={16} />}
          </button>
          <button onClick={handleAutoConfigure} disabled={isAutoConfiguring || !prompt.trim()} className={`px-3 py-1.5 rounded-xl text-xs font-bold flex items-center gap-2 border transition-all ${isAutoConfiguring || !prompt.trim() ? 'opacity-50 cursor-not-allowed border-gray-700' : 'bg-indigo-500/10 border-indigo-500 text-indigo-400 hover:bg-indigo-500/20 shadow-md'}`}>
            {isAutoConfiguring ? <Loader2 className="animate-spin" size={14} /> : <Wand2 size={14} />} AI Settings
          </button>
        </div>
      </div>
      <div className="relative">
        <textarea value={prompt} onChange={(e) => setPrompt(e.target.value)} className={`w-full h-32 p-5 text-sm rounded-2xl resize-none focus:ring-2 focus:ring-indigo-500 outline-none border transition-all ${theme === 'dark' ? 'bg-[#0a0a0a] border-gray-800 text-gray-200' : 'bg-gray-50 border-gray-200 text-gray-800'}`} placeholder={isListening ? "Listening..." : "Describe your idea..."} />
        {isListening && <div className="absolute bottom-4 right-4 flex items-center gap-2 text-[10px] text-red-400 font-bold uppercase tracking-widest animate-pulse"><span className="w-1.5 h-1.5 rounded-full bg-red-500"></span> Recording</div>}
      </div>
      <div className="mt-6 grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="space-y-4">
          <div><label className="text-xs font-bold text-gray-500 uppercase mb-2 flex items-center gap-2"><Search size={12} /> Style Refs</label>
          <input type="text" value={references} onChange={(e) => setReferences(e.target.value)} className={`w-full p-3 text-sm rounded-xl border ${theme === 'dark' ? 'bg-[#0a0a0a] border-gray-800 text-gray-300' : 'bg-gray-50 border-gray-200 text-gray-700'}`} placeholder="e.g. 90s Thai Rock" /></div>
          <div><label className="text-xs font-bold text-gray-500 uppercase mb-2 flex items-center gap-2"><Disc size={12} className="text-indigo-500" /> Musical Inspirations</label>
          <input type="text" value={inspirations} onChange={(e) => setInspirations(e.target.value)} className={`w-full p-3 text-sm rounded-xl border ${theme === 'dark' ? 'bg-[#0a0a0a] border-gray-800 text-gray-300' : 'bg-gray-50 border-gray-200 text-gray-700'}`} placeholder="e.g. Bohemian Rhapsody" /></div>
        </div>
        <div className="space-y-4">
          <div><label className="text-xs font-bold text-gray-500 uppercase mb-2 flex items-center gap-2"><TypeIcon size={12} /> Song Title</label>
          <input type="text" value={songTitle} onChange={(e) => setSongTitle(e.target.value)} className={`w-full p-3 text-sm rounded-xl border ${theme === 'dark' ? 'bg-[#0a0a0a] border-gray-800 text-gray-300' : 'bg-gray-50 border-gray-200 text-gray-700'}`} placeholder={autoTitle ? "Auto-generated..." : "Song name"} /></div>
          <div><label className="text-xs font-bold text-gray-500 uppercase mb-2 flex items-center gap-2"><History size={12} /> Lyrical Rhythm</label>
          <select value={poemType} onChange={(e) => setPoemType(e.target.value)} className={`w-full p-3 text-sm rounded-xl border ${theme === 'dark' ? 'bg-[#0a0a0a] border-gray-800 text-indigo-400' : 'bg-gray-50 border-gray-200 text-indigo-600'}`}>
            <option value="กลอน 4">Classic Flow (4 syllables)</option>
            <option value="กลอน 8">Classic Flow (8 syllables)</option>
            <option value="ฟรีสไตล์">Modern Free Flow</option>
            <option value="English Verse">Western Verse</option>
          </select></div>
        </div>
      </div>
    </SectionCard>
  );
};

import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import Editor from './components/Editor';
import Footer from './components/Footer';
import { generateSong, analyzeAndConfigure, generateCoverImage } from './services/geminiService';
import { SunoConfig } from './types';

// Augment global AIStudio interface and use it in Window declaration.
// Removed 'readonly' modifier from aistudio to match system-provided types and avoid "identical modifiers" error.
declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }

  interface Window {
    aistudio: AIStudio;
  }
}

const App: React.FC = () => {
  // Appearance
  const [theme, setTheme] = useState<'dark' | 'light'>('dark');
  const [successMsg, setSuccessMsg] = useState('');
  const [error, setError] = useState<string | null>(null);

  // Core Data
  const [prompt, setPrompt] = useState('บทเพลงรักที่ระเบิดอารมณ์ความเจ็บปวด...');
  const [references, setReferences] = useState('แนวพี่เสก Loso, Bodyslam, เพลงร็อคยุค 90');
  const [inspirations, setInspirations] = useState('');
  const [songTitle, setSongTitle] = useState('');
  const [generatedLyrics, setGeneratedLyrics] = useState(``);
  const [jsonPrompt, setJsonPrompt] = useState<SunoConfig | null>(null);

  // Model Selection
  // Updated model names to follow @google/genai guidelines.
  const modelOptions = [
    { value: 'gemini-3-pro-preview', label: 'Gemini 3 Pro', description: 'Best for complex songwriting and deep lyrics.' },
    { value: 'gemini-3-flash-preview', label: 'Gemini 3 Flash', description: 'Faster performance, excellent for quick drafts.' },
    { value: 'gemini-flash-latest', label: 'Gemini Flash', description: 'Standard reliable model for text generation.' },
    { value: 'gemini-flash-lite-latest', label: 'Gemini Flash Lite', description: 'Lightweight model, efficient for simple tasks.' }
  ];
  const [selectedModel, setSelectedModel] = useState('gemini-3-pro-preview');

  // Configuration
  const [bpm, setBpm] = useState(60);
  const [keyName, setKeyName] = useState('F#m');
  const [duration, setDuration] = useState(3.5);
  const [vocalType, setVocalType] = useState('ชาย');
  const [selectedGenres, setSelectedGenres] = useState(['Rock', 'Alternative', 'Acoustic']);
  const [poemType, setPoemType] = useState('กลอน 4');
  const [language, setLanguage] = useState('ไทย');
  const [autoTitle, setAutoTitle] = useState(true);
  const [autoMelody, setAutoMelody] = useState(true);

  // Assets
  const [coverImage, setCoverImage] = useState<string | null>(null);
  const [imageStyle, setImageStyle] = useState('Cinematic');
  const [imageAspectRatio, setImageAspectRatio] = useState<"1:1" | "16:9" | "9:16">("1:1");

  // Status
  const [isGenerating, setIsGenerating] = useState(false);
  const [isAutoConfiguring, setIsAutoConfiguring] = useState(false);
  const [isGeneratingImage, setIsGeneratingImage] = useState(false);
  const [isApiConnected, setIsApiConnected] = useState(false);

  // Constants
  const genres = ['Pop', 'Rock', 'Jazz', 'Hip-hop', 'R&B', 'Country', 'Folk', 'Blues', 'Electronic', 'Dance', 'House', 'Techno', 'Ambient', 'Classical', 'Reggae', 'Ska', 'Punk', 'Metal', 'Alternative', 'Indie', 'Acoustic', 'Soul', 'Funk', 'Disco', 'Trap', 'Lo-fi', 'Chill', 'Ballad'];
  const imageStyles = ['Cinematic', 'Digital Art', 'Oil Painting', 'Synthwave', 'Anime', 'Photorealistic', 'Neon Punk', 'Minimalist', 'Vintage Photo'];
  const languageOptions = [{ value: 'ไทย', label: '🇹🇭 ภาษาไทย' }, { value: 'อังกฤษ', label: '🇬🇧 English' }, { value: 'จีน', label: '🇨🇳 中文' }, { value: 'อีสาน', label: '🎭 ภาษาอีสาน' }];

  useEffect(() => {
    checkApiKey();
    const saved = localStorage.getItem('kn-music-last-session');
    if (saved) {
      try {
        const data = JSON.parse(saved);
        setGeneratedLyrics(data.lyrics || '');
        setJsonPrompt(data.json || null);
        setSongTitle(data.songTitle || '');
        setReferences(data.references || '');
        setInspirations(data.inspirations || '');
        setCoverImage(data.coverImage || null);
        if (data.selectedModel) setSelectedModel(data.selectedModel);
        if (data.config) {
          setBpm(data.config.bpm ?? 60);
          setKeyName(data.config.keyName ?? 'F#m');
          setDuration(data.config.duration ?? 3.5);
          setVocalType(data.config.vocalType ?? 'ชาย');
          setSelectedGenres(data.config.selectedGenres ?? ['Rock', 'Alternative', 'Acoustic']);
          setPoemType(data.config.poemType ?? 'กลอน 4');
          setLanguage(data.config.language ?? 'ไทย');
          setAutoTitle(data.config.autoTitle ?? true);
          setAutoMelody(data.config.autoMelody ?? true);
        }
      } catch (e) {}
    }
  }, []);

  const checkApiKey = async () => {
    try {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      setIsApiConnected(hasKey);
    } catch (e) {}
  };

  const handleConnectApi = async () => {
    try {
      await window.aistudio.openSelectKey();
      // To mitigate race conditions, assume selection was successful.
      setIsApiConnected(true);
      showStatus("API Connected Successfully");
    } catch (e) {
      setError("Failed to open API selection.");
    }
  };

  const showStatus = (msg: string) => {
    setSuccessMsg(msg);
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const toggleGenre = (genre: string) => {
    setSelectedGenres((prev) => prev.includes(genre) ? prev.filter((g) => g !== genre) : [...prev, genre]);
  };

  const handleAutoConfigure = async () => {
    if (!prompt.trim()) return;
    setIsAutoConfiguring(true);
    setError(null);
    try {
      // Use flash model for quick analysis regardless of main selection to save tokens if desired, 
      // but here we use selectedModel for consistency if user wants to specifically use one.
      const data = await analyzeAndConfigure(prompt, genres, selectedModel);
      setLanguage(data.language);
      setBpm(data.bpm);
      setKeyName(data.key);
      setDuration(data.duration);
      setVocalType(data.vocalType);
      setPoemType(data.poemType);
      if (data.genres && Array.isArray(data.genres)) {
        const matched = data.genres.filter(g => genres.includes(g));
        if (matched.length > 0) setSelectedGenres(matched);
      }
      showStatus(`Auto-configured: ${data.reason}`);
    } catch (e: any) {
      setError('Auto-config failed. Please retry.');
    } finally {
      setIsAutoConfiguring(false);
    }
  };

  const handleGenerate = async () => {
    if (!prompt.trim()) return;
    setIsGenerating(true);
    setError(null);
    try {
      const data = await generateSong({ 
        prompt, references, inspirations, language, genres: selectedGenres, bpm, key: keyName, 
        vocalType, linesPerSection: 4, poemType, autoMelody, autoTitle, duration, 
        model: selectedModel 
      });
      setGeneratedLyrics(data.lyrics);
      setJsonPrompt(data.suno_config);
      if (autoTitle) setSongTitle(data.title);
      showStatus('Masterpiece crafted!');
    } catch (e: any) {
      // If requested entity not found, prompt to re-connect the API key.
      if (e.message?.includes("Requested entity was not found.")) {
        setIsApiConnected(false);
        setError("API Session expired. Please re-connect.");
        await handleConnectApi();
      } else {
        setError('Generation failed. Please check API connection.');
      }
    } finally {
      setIsGenerating(false);
    }
  };

  const handleGenerateImage = async () => {
    if (!prompt.trim()) return;
    setIsGeneratingImage(true);
    setError(null);
    try {
      const imgUrl = await generateCoverImage({ prompt: songTitle || prompt.substring(0, 50), aspectRatio: imageAspectRatio, style: imageStyle });
      setCoverImage(imgUrl);
      showStatus('Cover art ready!');
    } catch (e: any) {
      if (e.message?.includes("Requested entity was not found.")) {
        setIsApiConnected(false);
        await handleConnectApi();
      } else {
        setError('Image generation failed.');
      }
    } finally {
      setIsGeneratingImage(false);
    }
  };

  const handleCopy = async (text: any) => {
    if (!text) return;
    const content = typeof text === 'object' ? JSON.stringify(text, null, 2) : text;
    try {
      await navigator.clipboard.writeText(content);
      showStatus('Copied!');
    } catch (err) {}
  };

  const handleNewProject = () => {
    if (confirm('Create new project? Current work will be lost.')) {
      setPrompt('');
      setReferences('');
