import { GoogleGenAI, Type } from "@google/genai";
import { SongData, AutoConfigData, ImageGenerationParams } from "../types";

// List of supported keys to ensure AI selects a valid option
const VALID_KEYS = ['C', 'Cm', 'C#', 'C#m', 'D', 'Dm', 'Eb', 'E', 'Em', 'F', 'Fm', 'F#', 'F#m', 'G', 'Gm', 'Ab', 'A', 'Am', 'Bb', 'B', 'Bm'];
const VALID_LANGUAGES = ['ไทย', 'อังกฤษ', 'จีน', 'ญี่ปุ่น', 'เกาหลี', 'อีสาน'];

export const generateSong = async (params: {
  prompt: string;
  references?: string;
  inspirations?: string;
  language: string;
  genres: string[];
  bpm: number;
  key: string;
  vocalType: string;
  linesPerSection: number;
  poemType: string;
  autoMelody: boolean;
  autoTitle: boolean;
  duration: number;
  model: string;
}): Promise<SongData> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `You are the K&N AI Music Songwriting Expert.
Your goal is to generate professional, soulful, and structurally sound songs optimized for Suno AI.

CLEAN FORMATTING RULES:
1. STRUCTURE: Use ONLY: [Intro], [Verse 1], [Verse 2], [Pre-Chorus], [Chorus], [Bridge], [Outro].
2. NO NOISE: Do NOT include instrument descriptions like (Sad piano) in lyrics.
3. PHRASING: Modern Thai Pop/Rock style. Natural phrasing (Kam-Suay).
4. DURATION: Target length is ${params.duration} minutes.`;

  const userPrompt = `TOPIC: ${params.prompt}\nSTYLE: ${params.poemType}\nKEY: ${params.key}\nTEMPO: ${params.bpm} BPM\nDURATION: ${params.duration} mins`;

  const response = await ai.models.generateContent({
    model: params.model,
    contents: userPrompt,
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          lyrics: { type: Type.STRING },
          duration_minutes: { type: Type.NUMBER },
          suno_config: {
            type: Type.OBJECT,
            properties: {
              style: { type: Type.STRING },
              tempo: { type: Type.STRING },
              key: { type: Type.STRING },
              vocal_description: { type: Type.STRING },
              mood: { type: Type.STRING },
              instrumentation: { type: Type.STRING }
            }
          }
        },
        required: ["title", "lyrics", "suno_config", "duration_minutes"]
      }
    }
  });

  const text = response.text?.trim();
  return JSON.parse(text || '{}');
};

export const analyzeAndConfigure = async (prompt: string, allowedGenres: string[], model: string): Promise<AutoConfigData> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `คุณคือ Music Producer มืออาชีพที่เชี่ยวชาญการใช้ Suno AI
หน้าที่ของคุณคือวิเคราะห์ "หัวข้อเพลง" และกำหนดค่าทางเทคนิคที่เหมาะสมที่สุด

กฎเหล็ก:
1. LANGUAGE: ต้องวิเคราะห์จากเนื้อหาและเลือกจากรายการนี้เท่านั้น: [${VALID_LANGUAGES.join(', ')}]
2. KEY: ต้องเลือกจากรายการนี้เท่านั้น: [${VALID_KEYS.join(', ')}]
3. DURATION: ต้องเป็นตัวเลขหน่วย "นาที" (เช่น 3.5) ห้ามเป็นวินาที
4. BPM: ต้องเป็นตัวเลขจำนวนเต็ม (เช่น 120)
5. REASON: ต้องอธิบายเหตุผลสั้นๆ เป็น "ภาษาไทย" เท่านั้น (เช่น "เลือกแนวร็อคเพื่อให้เข้ากับเนื้อหาที่ดุดัน")
6. GENRES: เลือกเฉพาะแนวเพลงที่เกี่ยวข้องจากรายการที่กำหนด`;

  const response = await ai.models.generateContent({
    model,
    contents: `ช่วยวิเคราะห์และตั้งค่าสำหรับหัวข้อเพลงนี้: "${prompt}"`,
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          language: { type: Type.STRING, description: "Must be exactly one of: " + VALID_LANGUAGES.join(', ') },
          genres: { type: Type.ARRAY, items: { type: Type.STRING } },
          bpm: { type: Type.INTEGER },
          key: { type: Type.STRING },
          vocalType: { type: Type.STRING },
          poemType: { type: Type.STRING },
          linesPerSection: { type: Type.INTEGER },
          duration: { type: Type.NUMBER },
          reason: { type: Type.STRING }
        },
        required: ["language", "genres", "bpm", "key", "vocalType", "poemType", "linesPerSection", "duration", "reason"]
      }
    }
  });

  const text = response.text?.trim();
  try {
    return JSON.parse(text || '{}');
  } catch (e) {
    console.error("Failed to parse AI response:", text);
    throw new Error("AI ส่งข้อมูลในรูปแบบที่ผิดพลาด");
  }
};

export const generateCoverImage = async (params: ImageGenerationParams): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const model = 'gemini-2.5-flash-image';
  const response = await ai.models.generateContent({
    model,
    contents: { parts: [{ text: `Album cover for: ${params.prompt}. Style: ${params.style}.` }] },
    config: { imageConfig: { aspectRatio: params.aspectRatio } }
  });
  for (const part of response.candidates[0].content.parts) {
    if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
  }
  throw new Error('Image generation failed.');
};

import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import Editor from './components/Editor';
import Footer from './components/Footer';
import { generateSong, analyzeAndConfigure, generateCoverImage } from './services/geminiService';
import { SunoConfig } from './types';

// Augment global AIStudio interface and use it in Window declaration.
declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }

  interface Window {
    // Making aistudio optional to match potential pre-existing declarations in the environment
    aistudio?: AIStudio;
  }
}

const App: React.FC = () => {
  // Appearance
  const [theme, setTheme] = useState<'dark' | 'light'>('dark');
  const [successMsg, setSuccessMsg] = useState('');
  const [error, setError] = useState<string | null>(null);

  // Core Data
  const [prompt, setPrompt] = useState('บทเพลงรักที่ระเบิดอารมณ์ความเจ็บปวด...');
  const [references, setReferences] = useState('แนวพี่เสก Loso, Bodyslam, เพลงร็อคยุค 90');
  const [inspirations, setInspirations] = useState('');
  const [songTitle, setSongTitle] = useState('');
  const [generatedLyrics, setGeneratedLyrics] = useState(``);
  const [jsonPrompt, setJsonPrompt] = useState<SunoConfig | null>(null);

  // Model Selection
  const modelOptions = [
    { value: 'gemini-3-pro-preview', label: 'Gemini 3 Pro', description: 'ดีที่สุดสำหรับการแต่งเพลงที่ซับซ้อนและเนื้อหาเชิงลึก' },
    { value: 'gemini-3-flash-preview', label: 'Gemini 3 Flash', description: 'ทำงานรวดเร็ว แม่นยำ เหมาะสำหรับการร่างเพลงด่วน' },
    { value: 'gemini-flash-lite-latest', label: 'Gemini Flash Lite', description: 'โมเดลขนาดเล็ก ประหยัดพลังงาน สำหรับงานทั่วไป' }
  ];
  const [selectedModel, setSelectedModel] = useState('gemini-3-pro-preview');

  // Configuration
  const [bpm, setBpm] = useState(60);
  const [keyName, setKeyName] = useState('F#m');
  const [duration, setDuration] = useState(3.5);
  const [vocalType, setVocalType] = useState('ชาย');
  const [selectedGenres, setSelectedGenres] = useState(['Rock', 'Alternative', 'Acoustic']);
  const [poemType, setPoemType] = useState('กลอน 4');
  const [language, setLanguage] = useState('ไทย');
  const [autoTitle, setAutoTitle] = useState(true);
  const [autoMelody, setAutoMelody] = useState(true);

  // Assets
  const [coverImage, setCoverImage] = useState<string | null>(null);
  const [imageStyle, setImageStyle] = useState('Cinematic');
  const [imageAspectRatio, setImageAspectRatio] = useState<"1:1" | "16:9" | "9:16">("1:1");

  // Status
  const [isGenerating, setIsGenerating] = useState(false);
  const [isAutoConfiguring, setIsAutoConfiguring] = useState(false);
  const [isGeneratingImage, setIsGeneratingImage] = useState(false);
  const [isApiConnected, setIsApiConnected] = useState(false);

  // Constants
  const genres = ['Pop', 'Rock', 'Jazz', 'Hip-hop', 'R&B', 'Country', 'Folk', 'Blues', 'Electronic', 'Dance', 'House', 'Techno', 'Ambient', 'Classical', 'Reggae', 'Ska', 'Punk', 'Metal', 'Alternative', 'Indie', 'Acoustic', 'Soul', 'Funk', 'Disco', 'Trap', 'Lo-fi', 'Chill', 'Ballad'];
  const VALID_KEYS = ['C', 'Cm', 'C#', 'C#m', 'D', 'Dm', 'Eb', 'E', 'Em', 'F', 'Fm', 'F#', 'F#m', 'G', 'Gm', 'Ab', 'A', 'Am', 'Bb', 'B', 'Bm'];
  const imageStyles = ['Cinematic', 'Digital Art', 'Oil Painting', 'Synthwave', 'Anime', 'Photorealistic', 'Neon Punk', 'Minimalist', 'Vintage Photo'];

  // Updated language options
  const languageOptions = [
    { value: 'ไทย', label: '🇹🇭 ภาษาไทย' },
    { value: 'อังกฤษ', label: '🇬🇧 English' },
    { value: 'จีน', label: '🇨🇳 中文' },
    { value: 'ญี่ปุ่น', label: '🇯🇵 日本語' },
    { value: 'เกาหลี', label: '🇰🇷 한국어' },
    { value: 'อีสาน', label: '🎭 ภาษาอีสาน' }
  ];

  useEffect(() => {
    checkApiKey();
    const saved = localStorage.getItem('kn-music-last-session');
    if (saved) {
      try {
        const data = JSON.parse(saved);
        setGeneratedLyrics(data.lyrics || '');
        setJsonPrompt(data.json || null);
        setSongTitle(data.songTitle || '');
        setReferences(data.references || '');
        setInspirations(data.inspirations || '');
        setCoverImage(data.coverImage || null);
        if (data.selectedModel) setSelectedModel(data.selectedModel);
        if (data.config) {
          setBpm(data.config.bpm ?? 60);
          setKeyName(data.config.keyName ?? 'F#m');
          setDuration(data.config.duration ?? 3.5);
          setVocalType(data.config.vocalType ?? 'ชาย');
          setSelectedGenres(data.config.selectedGenres ?? ['Rock', 'Alternative', 'Acoustic']);
          setPoemType(data.config.poemType ?? 'กลอน 4');
          setLanguage(data.config.language ?? 'ไทย');
          setAutoTitle(data.config.autoTitle ?? true);
          setAutoMelody(data.config.autoMelody ?? true);
        }
      } catch (e) {}
    }
  }, []);

  const checkApiKey = async () => {
    try {
      const hasKey = await window.aistudio?.hasSelectedApiKey();
      setIsApiConnected(!!hasKey);
    } catch (e) {}
  };

  const handleConnectApi = async () => {
    try {
      if (window.aistudio?.openSelectKey) {
        await window.aistudio.openSelectKey();
        setIsApiConnected(true);
        showStatus("เชื่อมต่อ API สำเร็จ");
      }
    } catch (e) {
      setError("ไม่สามารถเปิดหน้าต่างเลือก API ได้");
    }
  };

  const showStatus = (msg: string) => {
    setSuccessMsg(msg);
    setTimeout(() => setSuccessMsg(''), 4000);
  };

  const toggleGenre = (genre: string) => {
    setSelectedGenres((prev) => prev.includes(genre) ? prev.filter((g) => g !== genre) : [...prev, genre]);
  };

  const handleAutoConfigure = async () => {
    if (!prompt.trim()) return;
    setIsAutoConfiguring(true);
    setError(null);
    try {
      const data = await analyzeAndConfigure(prompt, genres, selectedModel);

      // Update values with strict validation
      if (data.language) {
        const matchedLang = languageOptions.find(opt => opt.value === data.language || opt.label.includes(data.language));
        if (matchedLang) {
          setLanguage(matchedLang.value);
        }
      }

      if (data.bpm) setBpm(data.bpm);
      if (data.vocalType) setVocalType(data.vocalType);
      if (data.poemType) setPoemType(data.poemType);

      if (data.key && VALID_KEYS.includes(data.key)) {
        setKeyName(data.key);
      } else {
        const matchedKey = VALID_KEYS.find(k => data.key.startsWith(k));
        if (matchedKey) setKeyName(matchedKey);
      }

      let calculatedDuration = data.duration;
      if (calculatedDuration > 10) calculatedDuration = calculatedDuration / 60;
      setDuration(Math.min(Math.max(calculatedDuration, 1), 5));

      if (data.genres && Array.isArray(data.genres)) {
        const matched = data.genres.filter(g => genres.includes(g));
        if (matched.length > 0) setSelectedGenres(matched);
      }

      showStatus(`AI ตั้งค่าให้เรียบร้อยแล้ว: ${data.reason}`);
    } catch (e: any) {
      console.error("Auto config error:", e);
      setError('การตั้งค่าอัตโนมัติล้มเหลว กรุณาลองใหม่อีกครั้ง');
    } finally {
      setIsAutoConfiguring(false);
    }
  };

  const handleGenerate = async () => {
    if (!prompt.trim()) return;
    setIsGenerating(true);
    setError(null);
    try {
      const data = await generateSong({ 
        prompt, references, inspirations, language, genres: selectedGenres, bpm, key: keyName, 
        vocalType, linesPerSection: 4, poemType, autoMelody, autoTitle, duration, 
        model: selectedModel 
      });
      setGeneratedLyrics(data.lyrics);
      setJsonPrompt(data.suno_config);
      if (autoTitle) setSongTitle(data.title);
      showStatus('สร้างบทเพลงสำเร็จแล้ว!');
    } catch (e: any) {
      if (e.message?.includes("Requested entity was not found.")) {
        setIsApiConnected(false);
        setError("เซสชัน API หมดอายุ กรุณาเชื่อมต่อใหม่อีกครั้ง");
        await handleConnectApi();
      } else {
        setError('การสร้างเพลงล้มเหลว กรุณาตรวจสอบ API หรือลองใหม่อีกครั้ง');
      }
    } finally {
      setIsGenerating(false);
    }
  };

  const handleGenerateImage = async () => {
    if (!prompt.trim()) return;
    setIsGeneratingImage(true);
    setError(null);
    try {
      const imgUrl = await generateCoverImage({ prompt: songTitle || prompt.substring(0, 50), aspectRatio: imageAspectRatio, style: imageStyle });
      setCoverImage(imgUrl);
      showStatus('สร้างภาพหน้าปกเรียบร้อย!');
    } catch (e: any) {
      if (e.message?.includes("Requested entity was not found.")) {
        setIsApiConnected(false);
        await handleConnectApi();
      } else {
        setError('การสร้างภาพหน้าปกล้มเหลว');
      }
    } finally {
      setIsGeneratingImage(false);
    }
  };

  const handleCopy = async (text: any) => {
    if (!text) return;
    const content = typeof text === 'object' ? JSON.stringify(text, null, 2) : text;
    try {
      await navigator.clipboard.writeText(content);
      showStatus('คัดลอกลงคลิปบอร์ดแล้ว!');
    } catch (err) {}
  };

  const handleNewProject = () => {
    if (confirm('คุณแน่ใจหรือไม่ว่าต้องการเริ่มโปรเจกต์ใหม่? ข้อมูลปัจจุบันจะสูญหาย')) {
      setPrompt('');
      setReferences('');
      setInspirations('');
      setSongTitle('');
      setGeneratedLyrics('');
      setJsonPrompt(null);
      setCoverImage(null);
      showStatus('เริ่มโปรเจกต์ใหม่แล้ว');
    }
  };

  const handleSave = () => {
    const data = { 
      lyrics: generatedLyrics, 
      json: jsonPrompt, 
      prompt, 
      references, 
      inspirations, 
      songTitle, 
      coverImage, 
      selectedModel,
      config: { bpm, keyName, duration, vocalType, selectedGenres, poemType, language, autoTitle, autoMelody } 
    };
    localStorage.setItem('kn-music-last-session', JSON.stringify(data));
    showStatus('บันทึกโปรเจกต์เรียบร้อยแล้ว');
  };

  const handleExport = (type: 'lyrics' | 'json' | 'image') => {
    if (type === 'image' && coverImage) {
      const link = document.createElement('a');
      link.href = coverImage;
      link.download = `cover-${songTitle || 'song'}.png`;
      link.click();
      return;
    }
    const content = type === 'lyrics' ? generatedLyrics : JSON.stringify(jsonPrompt, null, 2);
    const filename = type === 'lyrics' ? 'lyrics.txt' : 'suno_config.json';
    if (!content) return;
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url; link.download = filename; link.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className={`min-h-screen transition-colors duration-300 ${theme === 'dark' ? 'bg-[#0a0a0a] text-white' : 'bg-gray-50 text-gray-900'}`}>
      <Header theme={theme} setTheme={setTheme} isApiConnected={isApiConnected} onConnectApi={handleConnectApi} successMsg={successMsg} />
      <main className="max-w-7xl mx-auto p-4 md:p-6 grid grid-cols-1 lg:grid-cols-2 gap-6">
        <Sidebar 
          theme={theme} prompt={prompt} setPrompt={setPrompt} references={references} setReferences={setReferences} 
          inspirations={inspirations} setInspirations={setInspirations} songTitle={songTitle} setSongTitle={setSongTitle} 
          bpm={bpm} setBpm={setBpm} keyName={keyName} setKeyName={setKeyName} duration={duration} setDuration={setDuration} 
          vocalType={vocalType} setVocalType={setVocalType} poemType={poemType} setPoemType={setPoemType} 
          language={language} setLanguage={setLanguage} autoTitle={autoTitle} setAutoTitle={setAutoTitle} 
          autoMelody={autoMelody} setAutoMelody={setAutoMelody} selectedGenres={selectedGenres} toggleGenre={toggleGenre} 
          genres={genres} imageAspectRatio={imageAspectRatio} setImageAspectRatio={setImageAspectRatio} 
          imageStyle={imageStyle} setImageStyle={setImageStyle} imageStyles={imageStyles} languageOptions={languageOptions} 
          isAutoConfiguring={isAutoConfiguring} isGenerating={isGenerating} isGeneratingImage={isGeneratingImage} 
          isApiConnected={isApiConnected} handleAutoConfigure={handleAutoConfigure} handleGenerate={handleGenerate} 
          handleGenerateImage={handleGenerateImage} handleConnectApi={handleConnectApi} error={error}
          selectedModel={selectedModel} setSelectedModel={setSelectedModel} modelOptions={modelOptions}
        />
        <Editor 
          theme={theme} generatedLyrics={generatedLyrics} songTitle={songTitle} duration={duration} 
          selectedGenres={selectedGenres} bpm={bpm} keyName={keyName} inspirations={inspirations} 
          isGenerating={isGenerating} coverImage={coverImage} imageAspectRatio={imageAspectRatio} 
          jsonPrompt={jsonPrompt} handleNewProject={handleNewProject} handleSave={handleSave} 
          handleCopy={handleCopy} handleExport={handleExport}
        />
      </main>
      <Footer theme={theme} />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import Editor from './components/Editor';
import Footer from './components/Footer';
import { generateSong, analyzeAndConfigure, generateCoverImage } from './services/geminiService';
import { SunoConfig } from './types';

// Augment global AIStudio interface and use it in Window declaration.
declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }

  interface Window {
    // Making aistudio optional to match potential pre-existing declarations in the environment
    aistudio?: AIStudio;
  }
}

const App: React.FC = () => {
  // Appearance
  const [theme, setTheme] = useState<'dark' | 'light'>('dark');
  const [successMsg, setSuccessMsg] = useState('');
  const [error, setError] = useState<string | null>(null);

  // Core Data
  const [prompt, setPrompt] = useState('บทเพลงรักที่ระเบิดอารมณ์ความเจ็บปวด...');
  const [references, setReferences] = useState('แนวพี่เสก Loso, Bodyslam, เพลงร็อคยุค 90');
  const [inspirations, setInspirations] = useState('');
  const [songTitle, setSongTitle] = useState('');
  const [generatedLyrics, setGeneratedLyrics] = useState(``);
  const [jsonPrompt, setJsonPrompt] = useState<SunoConfig | null>(null);

  // Model Selection
  const modelOptions = [
    { value: 'gemini-3-pro-preview', label: 'Gemini 3 Pro', description: 'ดีที่สุดสำหรับการแต่งเพลงที่ซับซ้อนและเนื้อหาเชิงลึก' },
    { value: 'gemini-3-flash-preview', label: 'Gemini 3 Flash', description: 'ทำงานรวดเร็ว แม่นยำ เหมาะสำหรับการร่างเพลงด่วน' },
    { value: 'gemini-flash-lite-latest', label: 'Gemini Flash Lite', description: 'โมเดลขนาดเล็ก ประหยัดพลังงาน สำหรับงานทั่วไป' }
  ];
  const [selectedModel, setSelectedModel] = useState('gemini-3-pro-preview');

  // Configuration
  const [bpm, setBpm] = useState(60);
  const [keyName, setKeyName] = useState('F#m');
  const [duration, setDuration] = useState(3.5);
  const [vocalType, setVocalType] = useState('ชาย');
  const [selectedGenres, setSelectedGenres] = useState(['Rock', 'Alternative', 'Acoustic']);
  const [poemType, setPoemType] = useState('กลอน 4');
  const [language, setLanguage] = useState('ไทย');
  const [autoTitle, setAutoTitle] = useState(true);
  const [autoMelody, setAutoMelody] = useState(true);

  // Assets
  const [coverImage, setCoverImage] = useState<string | null>(null);
  const [imageStyle, setImageStyle] = useState('Cinematic');
  const [imageAspectRatio, setImageAspectRatio] = useState<"1:1" | "16:9" | "9:16">("1:1");

  // Status
  const [isGenerating, setIsGenerating] = useState(false);
  const [isAutoConfiguring, setIsAutoConfiguring] = useState(false);
  const [isGeneratingImage, setIsGeneratingImage] = useState(false);
  const [isApiConnected, setIsApiConnected] = useState(false);

  // Constants
  const genres = ['Pop', 'Rock', 'Jazz', 'Hip-hop', 'R&B', 'Country', 'Folk', 'Blues', 'Electronic', 'Dance', 'House', 'Techno', 'Ambient', 'Classical', 'Reggae', 'Ska', 'Punk', 'Metal', 'Alternative', 'Indie', 'Acoustic', 'Soul', 'Funk', 'Disco', 'Trap', 'Lo-fi', 'Chill', 'Ballad'];
  const VALID_KEYS = ['C', 'Cm', 'C#', 'C#m', 'D', 'Dm', 'Eb', 'E', 'Em', 'F', 'Fm', 'F#', 'F#m', 'G', 'Gm', 'Ab', 'A', 'Am', 'Bb', 'B', 'Bm'];
  const imageStyles = ['Cinematic', 'Digital Art', 'Oil Painting', 'Synthwave', 'Anime', 'Photorealistic', 'Neon Punk', 'Minimalist', 'Vintage Photo'];

  // Updated language options
  const languageOptions = [
    { value: 'ไทย', label: '🇹🇭 ภาษาไทย' },
    { value: 'อังกฤษ', label: '🇬🇧 English' },
    { value: 'จีน', label: '🇨🇳 中文' },
    { value: 'ญี่ปุ่น', label: '🇯🇵 日本語' },
    { value: 'เกาหลี', label: '🇰🇷 한국어' },
    { value: 'อีสาน', label: '🎭 ภาษาอีสาน' }
  ];

  useEffect(() => {
    checkApiKey();
    const saved = localStorage.getItem('kn-music-last-session');
    if (saved) {
      try {
        const data = JSON.parse(saved);
        setGeneratedLyrics(data.lyrics || '');
        setJsonPrompt(data.json || null);
        setSongTitle(data.songTitle || '');
        setReferences(data.references || '');
        setInspirations(data.inspirations || '');
        setCoverImage(data.coverImage || null);
        if (data.selectedModel) setSelectedModel(data.selectedModel);
        if (data.config) {
          setBpm(data.config.bpm ?? 60);
          setKeyName(data.config.keyName ?? 'F#m');
          setDuration(data.config.duration ?? 3.5);
          setVocalType(data.config.vocalType ?? 'ชาย');
          setSelectedGenres(data.config.selectedGenres ?? ['Rock', 'Alternative', 'Acoustic']);
          setPoemType(data.config.poemType ?? 'กลอน 4');
          setLanguage(data.config.language ?? 'ไทย');
          setAutoTitle(data.config.autoTitle ?? true);
          setAutoMelody(data.config.autoMelody ?? true);
        }
      } catch (e) {}
    }
  }, []);

  const checkApiKey = async () => {
    try {
      const hasKey = await window.aistudio?.hasSelectedApiKey();
      setIsApiConnected(!!hasKey);
    } catch (e) {}
  };

  const handleConnectApi = async () => {
    try {
      if (window.aistudio?.openSelectKey) {
        await window.aistudio.openSelectKey();
        setIsApiConnected(true);
        showStatus("เชื่อมต่อ API สำเร็จ");
      }
    } catch (e) {
      setError("ไม่สามารถเปิดหน้าต่างเลือก API ได้");
    }
  };

  const showStatus = (msg: string) => {
    setSuccessMsg(msg);
    setTimeout(() => setSuccessMsg(''), 4000);
  };

  const toggleGenre = (genre: string) => {
    setSelectedGenres((prev) => prev.includes(genre) ? prev.filter((g) => g !== genre) : [...prev, genre]);
  };

  const handleAutoConfigure = async () => {
    if (!prompt.trim()) return;
    setIsAutoConfiguring(true);
    setError(null);
    try {
      const data = await analyzeAndConfigure(prompt, genres, selectedModel);

      // Update values with strict validation
      if (data.language) {
        const matchedLang = languageOptions.find(opt => opt.value === data.language || opt.label.includes(data.language));
        if (matchedLang) {
          setLanguage(matchedLang.value);
        }
      }

      if (data.bpm) setBpm(data.bpm);
      if (data.vocalType) setVocalType(data.vocalType);
      if (data.poemType) setPoemType(data.poemType);

      if (data.key && VALID_KEYS.includes(data.key)) {
        setKeyName(data.key);
      } else {
        const matchedKey = VALID_KEYS.find(k => data.key.startsWith(k));
        if (matchedKey) setKeyName(matchedKey);
      }

      let calculatedDuration = data.duration;
      if (calculatedDuration > 10) calculatedDuration = calculatedDuration / 60;
      setDuration(Math.min(Math.max(calculatedDuration, 1), 5));

      if (data.genres && Array.isArray(data.genres)) {
        const matched = data.genres.filter(g => genres.includes(g));
        if (matched.length > 0) setSelectedGenres(matched);
      }

      showStatus(`AI ตั้งค่าให้เรียบร้อยแล้ว: ${data.reason}`);
    } catch (e: any) {
      console.error("Auto config error:", e);
      setError('การตั้งค่าอัตโนมัติล้มเหลว กรุณาลองใหม่อีกครั้ง');
    } finally {
      setIsAutoConfiguring(false);
    }
  };

  const handleGenerate = async () => {
    if (!prompt.trim()) return;
    setIsGenerating(true);
    setError(null);
    try {
      const data = await generateSong({ 
        prompt, references, inspirations, language, genres: selectedGenres, bpm, key: keyName, 
        vocalType, linesPerSection: 4, poemType, autoMelody, autoTitle, duration, 
        model: selectedModel 
      });
      setGeneratedLyrics(data.lyrics);
      setJsonPrompt(data.suno_config);
      if (autoTitle) setSongTitle(data.title);
      showStatus('สร้างบทเพลงสำเร็จแล้ว!');
    } catch (e: any) {
      if (e.message?.includes("Requested entity was not found.")) {
        setIsApiConnected(false);
        setError("เซสชัน API หมดอายุ กรุณาเชื่อมต่อใหม่อีกครั้ง");
        await handleConnectApi();
      } else {
        setError('การสร้างเพลงล้มเหลว กรุณาตรวจสอบ API หรือลองใหม่อีกครั้ง');
      }
    } finally {
      setIsGenerating(false);
    }
  };

  const handleGenerateImage = async () => {
    if (!prompt.trim()) return;
    setIsGeneratingImage(true);
    setError(null);
    try {
      const imgUrl = await generateCoverImage({ prompt: songTitle || prompt.substring(0, 50), aspectRatio: imageAspectRatio, style: imageStyle });
      setCoverImage(imgUrl);
      showStatus('สร้างภาพหน้าปกเรียบร้อย!');
    } catch (e: any) {
      if (e.message?.includes("Requested entity was not found.")) {
        setIsApiConnected(false);
        await handleConnectApi();
      } else {
        setError('การสร้างภาพหน้าปกล้มเหลว');
      }
    } finally {
      setIsGeneratingImage(false);
    }
  };

  const handleCopy = async (text: any) => {
    if (!text) return;
    const content = typeof text === 'object' ? JSON.stringify(text, null, 2) : text;
    try {
      await navigator.clipboard.writeText(content);
      showStatus('คัดลอกลงคลิปบอร์ดแล้ว!');
    } catch (err) {}
  };

  const handleNewProject = () => {
    if (confirm('คุณแน่ใจหรือไม่ว่าต้องการเริ่มโปรเจกต์ใหม่? ข้อมูลปัจจุบันจะสูญหาย')) {
      setPrompt('');
      setReferences('');
      setInspirations('');
      setSongTitle('');
      setGeneratedLyrics('');
      setJsonPrompt(null);
      setCoverImage(null);
      showStatus('เริ่มโปรเจกต์ใหม่แล้ว');
    }
  };

  const handleSave = () => {
    const data = { 
      lyrics: generatedLyrics, 
      json: jsonPrompt, 
      prompt, 
      references, 
      inspirations, 
      songTitle, 
      coverImage, 
      selectedModel,
      config: { bpm, keyName, duration, vocalType, selectedGenres, poemType, language, autoTitle, autoMelody } 
    };
    localStorage.setItem('kn-music-last-session', JSON.stringify(data));
    showStatus('บันทึกโปรเจกต์เรียบร้อยแล้ว');
  };

  const handleExport = (type: 'lyrics' | 'json' | 'image') => {
    if (type === 'image' && coverImage) {
      const link = document.createElement('a');
      link.href = coverImage;
      link.download = `cover-${songTitle || 'song'}.png`;
      link.click();
      return;
    }
    const content = type === 'lyrics' ? generatedLyrics : JSON.stringify(jsonPrompt, null, 2);
    const filename = type === 'lyrics' ? 'lyrics.txt' : 'suno_config.json';
    if (!content) return;
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url; link.download = filename; link.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className={`min-h-screen transition-colors duration-300 ${theme === 'dark' ? 'bg-[#0a0a0a] text-white' : 'bg-gray-50 text-gray-900'}`}>
      <Header theme={theme} setTheme={setTheme} isApiConnected={isApiConnected} onConnectApi={handleConnectApi} successMsg={successMsg} />
      <main className="max-w-7xl mx-auto p-4 md:p-6 grid grid-cols-1 lg:grid-cols-2 gap-6">
        <Sidebar 
          theme={theme} prompt={prompt} setPrompt={setPrompt} references={references} setReferences={setReferences} 
          inspirations={inspirations} setInspirations={setInspirations} songTitle={songTitle} setSongTitle={setSongTitle} 
          bpm={bpm} setBpm={setBpm} keyName={keyName} setKeyName={setKeyName} duration={duration} setDuration={setDuration} 
          vocalType={vocalType} setVocalType={setVocalType} poemType={poemType} setPoemType={setPoemType} 
          language={language} setLanguage={setLanguage} autoTitle={autoTitle} setAutoTitle={setAutoTitle} 
          autoMelody={autoMelody} setAutoMelody={setAutoMelody} selectedGenres={selectedGenres} toggleGenre={toggleGenre} 
          genres={genres} imageAspectRatio={imageAspectRatio} setImageAspectRatio={setImageAspectRatio} 
          imageStyle={imageStyle} setImageStyle={setImageStyle} imageStyles={imageStyles} languageOptions={languageOptions} 
          isAutoConfiguring={isAutoConfiguring} isGenerating={isGenerating} isGeneratingImage={isGeneratingImage} 
          isApiConnected={isApiConnected} handleAutoConfigure={handleAutoConfigure} handleGenerate={handleGenerate} 
          handleGenerateImage={handleGenerateImage} handleConnectApi={handleConnectApi} error={error}
          selectedModel={selectedModel} setSelectedModel={setSelectedModel} modelOptions={modelOptions}
        />
        <Editor 
          theme={theme} generatedLyrics={generatedLyrics} setGeneratedLyrics={setGeneratedLyrics} songTitle={songTitle} duration={duration} 
          selectedGenres={selectedGenres} bpm={bpm} keyName={keyName} inspirations={inspirations} 
          isGenerating={isGenerating} coverImage={coverImage} imageAspectRatio={imageAspectRatio} 
          jsonPrompt={jsonPrompt} handleNewProject={handleNewProject} handleSave={handleSave} 
          handleCopy={handleCopy} handleExport={handleExport}
        />
      </main>
      <Footer theme={theme} />
    </div>
  );
};

export default App;

import React, { useRef, useEffect } from 'react';
import { FileText, Music, Clock, Download, Plus, Save, Clipboard, ImageIcon } from 'lucide-react';
import { ToolButton } from './SharedUI';

interface EditorProps {
  theme: 'dark' | 'light';
  generatedLyrics: string;
  setGeneratedLyrics: (v: string) => void;
  songTitle: string;
  duration: number;
  selectedGenres: string[];
  bpm: number;
  keyName: string;
  inspirations: string;
  isGenerating: boolean;
  coverImage: string | null;
  imageAspectRatio: "1:1" | "16:9" | "9:16";
  jsonPrompt: any;
  handleNewProject: () => void;
  handleSave: () => void;
  handleCopy: (v: any) => void;
  handleExport: (t: 'lyrics' | 'json' | 'image') => void;
}

const Editor: React.FC<EditorProps> = (props) => {
  const { theme, generatedLyrics, setGeneratedLyrics, songTitle, duration, selectedGenres, bpm, keyName, inspirations, isGenerating, coverImage, imageAspectRatio, jsonPrompt, handleNewProject, handleSave, handleCopy, handleExport } = props;

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const backdropRef = useRef<HTMLDivElement>(null);

  // Sync scroll positions between textarea and backdrop
  const handleScroll = () => {
    if (textareaRef.current && backdropRef.current) {
      backdropRef.current.scrollTop = textareaRef.current.scrollTop;
      backdropRef.current.scrollLeft = textareaRef.current.scrollLeft;
    }
  };

  // Process text to add highlighting
  const renderHighlightedText = (text: string) => {
    if (!text) return null;

    return text.split('\n').map((line, i) => {
      // Structure tags regex: [Intro], [Chorus], [Verse 1], etc.
      const tagMatch = line.match(/^(\[.*\])$/);

      if (tagMatch) {
        return (
          <div key={i} className="min-h-[1.5em] font-bold">
            <span className="text-indigo-500 bg-indigo-500/10 px-1.5 py-0.5 rounded-md inline-block my-1 border border-indigo-500/20">
              {line}
            </span>
          </div>
        );
      }

      return (
        <div key={i} className="min-h-[1.5em]">
          {line || ' '}
        </div>
      );
    });
  };

  useEffect(() => {
    handleScroll();
  }, [generatedLyrics]);

  return (
    <div className="space-y-6 flex flex-col h-full">
      {/* Toolbar */}
      <div className="flex flex-wrap gap-2">
        <ToolButton onClick={handleNewProject} icon={<Plus size={16} />} label="ใหม่" theme={theme} />
        <ToolButton onClick={handleSave} icon={<Save size={16} />} label="บันทึก" theme={theme} />
        <ToolButton onClick={() => handleCopy(generatedLyrics)} icon={<Clipboard size={16} />} label="คัดลอกเนื้อเพลง" theme={theme} disabled={!generatedLyrics} />
        <ToolButton onClick={() => handleExport('lyrics')} icon={<Download size={16} />} label="ส่งออก TXT" theme={theme} disabled={!generatedLyrics} />
        <ToolButton onClick={() => handleExport('image')} icon={<ImageIcon size={16} />} label="โหลดหน้าปก" theme={theme} disabled={!coverImage} />
      </div>

      {/* Script Section */}
      <section className={`flex-1 rounded-3xl border flex flex-col overflow-hidden min-h-[500px] ${theme === 'dark' ? 'bg-[#111111] border-gray-800' : 'bg-white border-gray-200'}`}>
        <div className={`px-6 py-4 border-b flex justify-between items-center ${theme === 'dark' ? 'border-gray-800' : 'border-gray-200'}`}>
          <h3 className="text-sm font-bold flex items-center gap-2 uppercase tracking-widest">
            <FileText size={16} className="text-indigo-500" />
            Lyrics Studio & Syntax Highlighter
          </h3>
        </div>

        <div className="flex-1 relative overflow-hidden flex flex-col">
          {!generatedLyrics && !isGenerating && (
            <div className="absolute inset-0 flex flex-col items-center justify-center text-gray-500 opacity-50 space-y-4 text-center z-0">
              <Music size={64} strokeWidth={1} />
              <p className="text-sm font-medium">ระบุไอเดียของคุณด้านซ้าย แล้วกดปุ่มสร้างเพลงเพื่อเริ่มงาน</p>
            </div>
          )}

          {isGenerating && (
            <div className="p-8 space-y-6">
              <div className="h-12 w-3/4 rounded-2xl bg-indigo-500/10 animate-pulse" />
