              {/* Editable Lyrics Area */}
              <div className="flex-1 relative group px-8 pb-8">
                {/* Backdrop with highlighting */}
                <div 
                  ref={backdropRef}
                  aria-hidden="true"
                  className={`absolute inset-x-8 inset-y-0 p-0 pointer-events-none whitespace-pre-wrap break-words font-serif text-lg md:text-xl leading-relaxed overflow-hidden ${theme === 'dark' ? 'text-gray-200' : 'text-gray-800'}`}
                  style={{ 
                    color: 'transparent',
                    WebkitTextFillColor: 'transparent',
                  }}
                >
                  {renderHighlightedText(generatedLyrics)}
