                {/* Actual Editor Textarea */}
                <textarea
                  ref={textareaRef}
                  value={generatedLyrics}
                  onChange={(e) => setGeneratedLyrics(e.target.value)}
                  onScroll={handleScroll}
                  spellCheck={false}
                  className={`relative w-full h-full bg-transparent border-none outline-none resize-none font-serif text-lg md:text-xl leading-relaxed break-words whitespace-pre-wrap z-10 p-0 ${theme === 'dark' ? 'text-gray-300' : 'text-gray-800'}`}
                  style={{ 
                    caretColor: theme === 'dark' ? '#6366f1' : '#4f46e5'
                  }}
                  placeholder="เริ่มพิมพ์เนื้อเพลงที่นี่..."
