      {/* Metadata Section */}
      <section className={`h-48 rounded-3xl border flex flex-col overflow-hidden ${theme === 'dark' ? 'bg-[#111111] border-gray-800' : 'bg-white border-gray-200'}`}>
        <div className={`px-6 py-3 border-b flex justify-between items-center ${theme === 'dark' ? 'border-gray-800' : 'border-gray-200'}`}>
          <h3 className="text-[10px] font-bold text-gray-500 uppercase flex items-center gap-2">
            <div className={`w-2 h-2 rounded-full ${jsonPrompt ? 'bg-green-500 shadow-[0_0_8px_green]' : 'bg-gray-700'}`} />
            Suno AI Production Metadata (JSON)
          </h3>
          <button onClick={() => handleCopy(jsonPrompt)} disabled={!jsonPrompt} className="text-[10px] font-bold text-indigo-500 disabled:opacity-50">คัดลอก JSON</button>
