  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const backdropRef = useRef<HTMLDivElement>(null);

  const handleScroll = () => {
    if (textareaRef.current && backdropRef.current) {
      backdropRef.current.scrollTop = textareaRef.current.scrollTop;
    }
  };

  const renderHighlightedText = (text: string) => {
    if (!text) return null;

    return text.split('\n').map((line, i) => {
      // Improved regex: find anything inside brackets [Structure]
      const hasTag = line.match(/\[([^\]]+)\]/g);

      if (hasTag) {
        // If the line contains a tag, we style the whole line or just the tag parts
        // For simplicity and aesthetic, if it's a structural line, we highlight it
        let highlightedLine = line;

        return (
          <div key={i} className="min-h-[1.6em] relative">
            <span className="text-indigo-500 bg-indigo-500/10 px-1.5 py-0.5 rounded-md inline-block my-0.5 border border-indigo-500/20 font-bold text-sm uppercase tracking-wider">
              {line}
            </span>
          </div>
        );
      }

      return (
        <div key={i} className="min-h-[1.6em] py-0.5">
          {line || ' '}
        </div>
      );
    });
  };

  // Keep scroll in sync whenever lyrics update
