    handleScroll();
  }, [generatedLyrics]);

  return (
    <div className="space-y-6 flex flex-col h-full">
      <div className="flex flex-wrap gap-2">
        <ToolButton onClick={handleNewProject} icon={<Plus size={16} />} label="ใหม่" theme={theme} />
        <ToolButton onClick={handleSave} icon={<Save size={16} />} label="บันทึก" theme={theme} />
        <ToolButton onClick={() => handleCopy(generatedLyrics)} icon={<Clipboard size={16} />} label="คัดลอก" theme={theme} disabled={!generatedLyrics} />
        <ToolButton onClick={() => handleExport('lyrics')} icon={<Download size={16} />} label="ส่งออก TXT" theme={theme} disabled={!generatedLyrics} />
        <ToolButton onClick={() => handleExport('image')} icon={<ImageIcon size={16} />} label="โหลดปก" theme={theme} disabled={!coverImage} />
      </div>

      <section className={`flex-1 rounded-3xl border flex flex-col overflow-hidden min-h-[500px] shadow-2xl ${theme === 'dark' ? 'bg-[#0d0d0d] border-gray-800' : 'bg-white border-gray-200'}`}>
        <div className={`px-6 py-4 border-b flex justify-between items-center ${theme === 'dark' ? 'border-gray-800' : 'border-gray-200'}`}>
          <h3 className="text-xs font-bold flex items-center gap-2 uppercase tracking-widest text-gray-400">
            <FileText size={14} className="text-indigo-500" />
            Lyric Studio & Highlighting
          </h3>
        </div>

        <div className="flex-1 relative overflow-hidden flex flex-col">
          {!generatedLyrics && !isGenerating && (
            <div className="absolute inset-0 flex flex-col items-center justify-center text-gray-500 opacity-30 space-y-4 text-center z-0">
              <Music size={64} strokeWidth={1} />
              <p className="text-sm font-medium">ระบุไอเดียด้านซ้ายเพื่อเริ่มสร้างบทเพลง</p>
            </div>
          )}

          {isGenerating && (
            <div className="p-10 space-y-6">
              <div className="h-10 w-2/3 rounded-2xl bg-indigo-500/10 animate-pulse" />
              {[...Array(6)].map((_, i) => (
                <div key={i} className={`h-4 rounded-full ${theme === 'dark' ? 'bg-gray-800' : 'bg-gray-200'} animate-pulse`} style={{ width: `${70 + Math.random() * 30}%` }} />
              ))}
            </div>
          )}

          {generatedLyrics && (
