export default Editor;

import { GoogleGenAI, Type } from "@google/genai";
import { SongData, AutoConfigData, ImageGenerationParams } from "../types";

const VALID_KEYS = ['C', 'Cm', 'C#', 'C#m', 'D', 'Dm', 'Eb', 'E', 'Em', 'F', 'Fm', 'F#', 'F#m', 'G', 'Gm', 'Ab', 'A', 'Am', 'Bb', 'B', 'Bm'];
const VALID_LANGUAGES = ['ไทย', 'อังกฤษ', 'จีน', 'ญี่ปุ่น', 'เกาหลี', 'อีสาน'];

export const generateSong = async (params: {
  prompt: string;
  references?: string;
  inspirations?: string;
  language: string;
  genres: string[];
  bpm: number;
  key: string;
  vocalType: string;
  linesPerSection: number;
  poemType: string;
  autoMelody: boolean;
  autoTitle: boolean;
  duration: number;
  model: string;
}): Promise<SongData> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `You are a World-Class Music Producer and Songwriter. 
Your goal is to create a COMPLETED, FULL-LENGTH SONG ARRANGEMENT in ${params.language}.

STRICT ARRANGEMENT RULES:
1. FULL STRUCTURE: You MUST include [Intro], [Verse 1], [Verse 2], [Pre-Chorus], [Chorus], [Post-Chorus], [Guitar Solo / Instrumental], [Bridge], [Final Chorus], and [Outro].
2. INDIVIDUAL LINES: Every tag (e.g., [Chorus]) must be on its own line.
3. DETAILED CUES: You can add musical cues within the tags like [Guitar Solo: Emotional and High Gain] or [Intro: Piano Melodic].
4. LYRIC DEPTH: Lyrics must be deep, poetic, and match the specified genre.
5. LENGTH: The song should be long enough for a ${params.duration} minute performance.
6. NO TRUNCATION: Do not stop early. Provide the full emotional journey of the song.`;

  const userPrompt = `
  TOPIC: ${params.prompt}
  STYLE REFERENCES: ${params.references || 'None'}
  INSPIRATIONS: ${params.inspirations || 'None'}
  GENRES: ${params.genres.join(', ')}
  KEY: ${params.key}
  TEMPO: ${params.bpm} BPM
  POEM STYLE: ${params.poemType}
  VOCAL: ${params.vocalType}
  TARGET DURATION: ${params.duration} Minutes
  `;

  const response = await ai.models.generateContent({
    model: params.model,
    contents: userPrompt,
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          lyrics: { type: Type.STRING, description: "Full song lyrics with complete structural tags" },
          duration_minutes: { type: Type.NUMBER },
          suno_config: {
            type: Type.OBJECT,
            properties: {
              style: { type: Type.STRING },
              tempo: { type: Type.STRING },
              key: { type: Type.STRING },
              vocal_description: { type: Type.STRING },
              mood: { type: Type.STRING },
              instrumentation: { type: Type.STRING }
            }
          }
        },
        required: ["title", "lyrics", "suno_config", "duration_minutes"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

