    <div className="space-y-6 flex flex-col h-full">
      <div className="flex flex-wrap gap-2">
        <ToolButton onClick={handleNewProject} icon={<Plus size={16} />} label="ใหม่" theme={theme} />
        <ToolButton onClick={handleSave} icon={<Save size={16} />} label="บันทึก" theme={theme} />
        <ToolButton onClick={() => handleCopy(generatedLyrics)} icon={<Clipboard size={16} />} label="คัดลอก" theme={theme} disabled={!generatedLyrics} />
        <ToolButton onClick={() => handleExport('lyrics')} icon={<Download size={16} />} label="ส่งออก TXT" theme={theme} disabled={!generatedLyrics} />
        <ToolButton onClick={() => handleExport('image')} icon={<ImageIcon size={16} />} label="โหลดปก" theme={theme} disabled={!coverImage} />
      </div>

      <section className={`flex-1 rounded-[2.5rem] border flex flex-col overflow-hidden min-h-[600px] shadow-2xl transition-all duration-500 ${theme === 'dark' ? 'bg-[#080808] border-gray-800/50 shadow-indigo-500/5' : 'bg-white border-gray-200 shadow-xl'}`}>
        <div className={`px-8 py-5 border-b flex justify-between items-center ${theme === 'dark' ? 'border-gray-800/50 bg-[#0c0c0c]' : 'border-gray-100 bg-gray-50/50'}`}>
          <h3 className="text-[10px] font-black flex items-center gap-3 uppercase tracking-[0.25em] text-gray-500">
            <div className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse" />
            Studio Lyric Editor v2.5
          </h3>
          <div className="flex gap-2">
            <div className="w-2 h-2 rounded-full bg-red-500/20" />
            <div className="w-2 h-2 rounded-full bg-yellow-500/20" />
            <div className="w-2 h-2 rounded-full bg-green-500/20" />
          </div>
        </div>

        <div className="flex-1 relative overflow-hidden flex flex-col">
          {!generatedLyrics && !isGenerating && (
            <div className="absolute inset-0 flex flex-col items-center justify-center text-gray-500 opacity-20 space-y-6 text-center z-0">
              <Music size={80} strokeWidth={0.5} className="text-indigo-500" />
              <div className="space-y-2">
                <p className="text-lg font-bold uppercase tracking-widest">Ready to Compose</p>
                <p className="text-xs">ระบุเรื่องราวที่ต้องการ แล้วปล่อยให้ AI จัดการ</p>
              </div>
            </div>
          )}

          {isGenerating && (
            <div className="p-12 space-y-8">
              <div className="space-y-3">
                <div className="h-12 w-1/2 rounded-2xl bg-indigo-500/10 animate-pulse" />
                <div className="h-4 w-1/4 rounded-full bg-indigo-500/5 animate-pulse" />
