                        <div className="absolute -inset-1 bg-gradient-to-r from-indigo-500 to-purple-600 rounded-3xl blur opacity-25 group-hover:opacity-50 transition duration-1000"></div>
                        <img 
                          src={coverImage} 
                          alt="Cover" 
                          className={`relative rounded-2xl shadow-2xl object-cover border border-white/10 ${imageAspectRatio === '9:16' ? 'w-32 aspect-[9/16]' : 'w-44 aspect-square'}`} 
                        />
                      </div>
