import { GoogleGenAI, Type } from "@google/genai";
import { SongData, AutoConfigData, ImageGenerationParams } from "../types";

const VALID_KEYS = ['C', 'Cm', 'C#', 'C#m', 'D', 'Dm', 'Eb', 'E', 'Em', 'F', 'Fm', 'F#', 'F#m', 'G', 'Gm', 'Ab', 'A', 'Am', 'Bb', 'B', 'Bm'];
const VALID_LANGUAGES = ['ไทย', 'อังกฤษ', 'จีน', 'ญี่ปุ่น', 'เกาหลี', 'อีสาน'];

export const generateSong = async (params: {
  prompt: string;
  references?: string;
  inspirations?: string;
  language: string;
  genres: string[];
  bpm: number;
  key: string;
  vocalType: string;
  linesPerSection: number;
  poemType: string;
  autoMelody: boolean;
  autoTitle: boolean;
  duration: number;
  model: string;
}): Promise<SongData> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // คำนวณจำนวนท่อนที่ควรมีตามความยาวเพลง (ประมาณการ)
  const estimatedSections = params.duration >= 4 ? "8-10 sections" : "5-7 sections";

  const systemInstruction = `You are a Master Songwriter and Music Arranger.
Your task is to write a COMPLETE SONG in ${params.language} that fits exactly a ${params.duration} minute duration.

COMPOSITION GUIDELINES FOR ${params.duration} MINUTES:
1. QUANTITY: Based on ${params.duration} mins, you must provide approximately ${estimatedSections}.
2. MANDATORY TAGS: Every song MUST have:
   - [Intro]: Describe the opening mood and instruments.
   - [Verse 1 & 2]: Deep storytelling.
   - [Pre-Chorus]: Build up tension.
   - [Chorus]: The main hook (repeat if necessary for longer songs).
   - [Instrumental Solo]: Specify the instrument (e.g., [Guitar Solo], [Saxophone Solo]) and the vibe.
   - [Bridge]: A shift in melody or emotion.
   - [Final Chorus]: High energy conclusion.
   - [Outro]: Fading out or a final dramatic line.
3. FORMAT: Put each tag on its OWN LINE.
4. CONTENT: Do not truncate. Write full lyrics. If the duration is long, expand the verses and bridge.
5. MUSICAL CUES: Include cues inside brackets, e.g., [Guitar Solo: Fast and Aggressive] or [Chorus: Power Ballad Style].`;

  const userPrompt = `
  Write a full song about: ${params.prompt}
  Musical Style: ${params.genres.join(', ')}
  Reference Style: ${params.references || 'None'}
  BPM: ${params.bpm} | Key: ${params.key}
  Duration Target: ${params.duration} Minutes
  Poem Style: ${params.poemType}
  Vocalist: ${params.vocalType}
  `;

  const response = await ai.models.generateContent({
    model: params.model,
    contents: userPrompt,
    config: {
      systemInstruction,
      thinkingConfig: { thinkingBudget: 4000 }, // ให้ AI ใช้เวลาคิดวิเคราะห์โครงสร้างก่อนตอบ
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          lyrics: { type: Type.STRING },
          duration_minutes: { type: Type.NUMBER },
          suno_config: {
            type: Type.OBJECT,
            properties: {
              style: { type: Type.STRING },
              tempo: { type: Type.STRING },
              key: { type: Type.STRING },
              vocal_description: { type: Type.STRING },
              mood: { type: Type.STRING },
              instrumentation: { type: Type.STRING }
            }
          }
        },
        required: ["title", "lyrics", "suno_config", "duration_minutes"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

export const analyzeAndConfigure = async (prompt: string, allowedGenres: string[], model: string): Promise<AutoConfigData> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await ai.models.generateContent({
    model,
    contents: `วิเคราะห์ไอเดียเพลง: "${prompt}" และแนะนำค่าที่เหมาะสมที่สุด`,
    config: {
      systemInstruction: "คุณคือ Producer มืออาชีพ แนะนำภาษา, แนวเพลง, BPM, Key และความยาวเพลง (1-5 นาที) ที่เหมาะกับเนื้อหาที่สุด",
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          language: { type: Type.STRING },
          genres: { type: Type.ARRAY, items: { type: Type.STRING } },
          bpm: { type: Type.INTEGER },
          key: { type: Type.STRING },
          vocalType: { type: Type.STRING },
          poemType: { type: Type.STRING },
          linesPerSection: { type: Type.INTEGER },
          duration: { type: Type.NUMBER },
          reason: { type: Type.STRING }
        },
        required: ["language", "genres", "bpm", "key", "vocalType", "poemType", "linesPerSection", "duration", "reason"]
      }
    }
  });
  return JSON.parse(response.text || '{}');
};

export const generateCoverImage = async (params: ImageGenerationParams): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: { parts: [{ text: `High-quality album cover for a song titled "${params.prompt}". Style: ${params.style}. Professional art.` }] },
    config: { imageConfig: { aspectRatio: params.aspectRatio } }
  });
  const part = response.candidates[0].content.parts.find(p => p.inlineData);
  if (part?.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
  throw new Error('Image failed');
};

