                  <div className="absolute inset-0 bg-indigo-500 rounded-full blur-2xl opacity-20 animate-pulse" />
                  {/* Added missing Loader2 component */}
                  <Loader2 size={48} className="text-indigo-500 animate-spin relative" />
                </div>
                <div className="space-y-2">
                  <h4 className="text-xl font-bold tracking-tight text-white">กำลังประพันธ์บทเพลง...</h4>
                  <p className="text-sm text-gray-400">AI กำลังวิเคราะห์โครงสร้างสำหรับเวลา {duration} นาที</p>
                </div>
                <div className="w-full bg-gray-800 rounded-full h-1.5 overflow-hidden">
                  <div className="bg-indigo-500 h-full w-1/2 animate-[shimmer_2s_infinite]" style={{ backgroundSize: '200% 100%', backgroundImage: 'linear-gradient(90deg, transparent, rgba(255,255,255,0.2), transparent)' }} />
                </div>
              </div>
            </div>
          )}

          <div className="flex-1 flex flex-col overflow-hidden">
            <div className="px-12 pt-12 pb-6 flex-shrink-0">
              {songTitle && (
                <div className="flex flex-col md:flex-row gap-10 mb-8 items-start">
                  {coverImage && (
                    <div className="flex-shrink-0 relative group">
                      <div className="absolute -inset-1 bg-gradient-to-r from-indigo-500 to-purple-600 rounded-[2rem] blur opacity-20 group-hover:opacity-40 transition duration-1000"></div>
                      <img 
                        src={coverImage} 
                        alt="Cover" 
                        className={`relative rounded-3xl shadow-2xl object-cover border border-white/5 ${imageAspectRatio === '9:16' ? 'w-32 aspect-[9/16]' : 'w-48 aspect-square'}`} 
                      />
                    </div>
                  )}
                  <div className="flex-1 pt-3">
                    <h2 className="text-6xl font-black bg-clip-text text-transparent bg-gradient-to-br from-white via-indigo-100 to-indigo-400 mb-5 leading-[1] tracking-tighter">
                      {songTitle}
                    </h2>
                    <div className="flex flex-wrap gap-x-5 gap-y-3">
                      <span className="bg-indigo-500/10 text-indigo-400 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border border-indigo-500/20">{selectedGenres.join(' • ')}</span>
                      <span className="bg-white/5 text-gray-400 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border border-white/5">{bpm} BPM • {keyName}</span>
                    </div>
                  </div>
                </div>
              )}
            </div>

            <div className="flex-1 relative px-12 pb-12 overflow-hidden">
              <div 
                ref={backdropRef}
                className={`absolute inset-x-12 inset-y-0 p-0 pointer-events-none whitespace-pre-wrap break-words font-serif text-2xl leading-[1.8] overflow-y-auto overflow-x-hidden ${theme === 'dark' ? 'text-gray-200' : 'text-gray-800'}`}
                style={{ color: 'transparent', WebkitTextFillColor: 'transparent' }}
              >
                {renderHighlightedText(generatedLyrics)}
              </div>

              <textarea
                ref={textareaRef}
                value={generatedLyrics}
                onChange={(e) => setGeneratedLyrics(e.target.value)}
                onScroll={handleScroll}
                spellCheck={false}
                className={`relative w-full h-full bg-transparent border-none outline-none resize-none font-serif text-2xl leading-[1.8] break-words whitespace-pre-wrap z-10 p-0 ${theme === 'dark' ? 'text-gray-400 focus:text-gray-100' : 'text-gray-600 focus:text-gray-900'} transition-colors duration-300`}
                style={{ caretColor: '#6366f1' }}
                placeholder="Compose your lyrics here..."
              />
            </div>
          </div>
        </div>
      </section>

      <section className={`h-36 rounded-[2.5rem] border flex flex-col overflow-hidden shadow-2xl ${theme === 'dark' ? 'bg-[#080808] border-gray-800/40' : 'bg-gray-50 border-gray-100'}`}>
        <div className={`px-8 py-3 border-b flex justify-between items-center ${theme === 'dark' ? 'border-gray-800/40 bg-[#0c0c0c]' : 'border-gray-100 bg-gray-100/50'}`}>
          <span className="text-[10px] font-black text-gray-500 uppercase tracking-[0.4em] flex items-center gap-2">
            <div className="w-1.5 h-1.5 rounded-full bg-indigo-500" />
            Meta JSON Data
          </span>
          <button onClick={() => handleCopy(jsonPrompt)} className="text-[10px] font-black text-indigo-500 hover:text-indigo-400 tracking-widest transition-colors">COPY</button>
        </div>
        <div className="flex-1 p-5 overflow-y-auto font-mono text-[11px] text-indigo-400/60 leading-relaxed custom-scrollbar">
          {jsonPrompt ? <pre>{JSON.stringify(jsonPrompt, null, 2)}</pre> : <div className="h-full flex items-center justify-center opacity-20 italic font-sans text-xs tracking-widest">Awaiting generation...</div>}
        </div>
      </section>
    </div>
  );
};

export default Editor;

import React, { useState, useEffect, useCallback } from 'react';
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import Editor from './components/Editor';
import Footer from './components/Footer';
import { generateSong, analyzeAndConfigure, generateCoverImage } from './services/geminiService';
import { SunoConfig } from './types';

// Constants moved outside to prevent re-creation on render
const GENRES_LIST = ['Pop', 'Rock', 'Jazz', 'Hip-hop', 'R&B', 'Country', 'Folk', 'Blues', 'Electronic', 'Dance', 'House', 'Techno', 'Ambient', 'Classical', 'Reggae', 'Ska', 'Punk', 'Metal', 'Alternative', 'Indie', 'Acoustic', 'Soul', 'Funk', 'Disco', 'Trap', 'Lo-fi', 'Chill', 'Ballad'];
const VALID_KEYS = ['C', 'Cm', 'C#', 'C#m', 'D', 'Dm', 'Eb', 'E', 'Em', 'F', 'Fm', 'F#', 'F#m', 'G', 'Gm', 'Ab', 'A', 'Am', 'Bb', 'B', 'Bm'];
const IMAGE_STYLES = ['Cinematic', 'Digital Art', 'Oil Painting', 'Synthwave', 'Anime', 'Photorealistic', 'Neon Punk', 'Minimalist', 'Vintage Photo'];
const LANGUAGE_OPTIONS = [
  { value: 'ไทย', label: '🇹🇭 ภาษาไทย' },
  { value: 'อังกฤษ', label: '🇬🇧 English' },
  { value: 'จีน', label: '🇨🇳 中文' },
  { value: 'ญี่ปุ่น', label: '🇯🇵 日本語' },
  { value: 'เกาหลี', label: '🇰🇷 한국어' },
  { value: 'อีสาน', label: '🎭 ภาษาอีสาน' }
];
const MODEL_OPTIONS = [
  { value: 'gemini-3-pro-preview', label: 'Gemini 3 Pro', description: 'ดีที่สุดสำหรับการแต่งเพลงที่ซับซ้อนและเนื้อหาเชิงลึก' },
  { value: 'gemini-3-flash-preview', label: 'Gemini 3 Flash', description: 'ทำงานรวดเร็ว แม่นยำ เหมาะสำหรับการร่างเพลงด่วน' },
  { value: 'gemini-flash-lite-latest', label: 'Gemini Flash Lite', description: 'โมเดลขนาดเล็ก ประหยัดพลังงาน สำหรับงานทั่วไป' }
];

declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }
  interface Window {
    aistudio?: AIStudio;
  }
}

const App: React.FC = () => {
  const [theme, setTheme] = useState<'dark' | 'light'>('dark');
  const [successMsg, setSuccessMsg] = useState('');
  const [error, setError] = useState<string | null>(null);

  const [prompt, setPrompt] = useState('บทเพลงรักที่ระเบิดอารมณ์ความเจ็บปวด...');
  const [references, setReferences] = useState('แนวพี่เสก Loso, Bodyslam, เพลงร็อคยุค 90');
  const [inspirations, setInspirations] = useState('');
  const [songTitle, setSongTitle] = useState('');
  const [generatedLyrics, setGeneratedLyrics] = useState(``);
  const [jsonPrompt, setJsonPrompt] = useState<SunoConfig | null>(null);
  const [selectedModel, setSelectedModel] = useState('gemini-3-pro-preview');

  const [bpm, setBpm] = useState(60);
  const [keyName, setKeyName] = useState('F#m');
  const [duration, setDuration] = useState(3.5);
  const [vocalType, setVocalType] = useState('ชาย');
  const [selectedGenres, setSelectedGenres] = useState<string[]>(['Rock', 'Alternative', 'Acoustic']);
  const [poemType, setPoemType] = useState('กลอน 4');
  const [language, setLanguage] = useState('ไทย');
  const [autoTitle, setAutoTitle] = useState(true);
  const [autoMelody, setAutoMelody] = useState(true);

  const [coverImage, setCoverImage] = useState<string | null>(null);
  const [imageStyle, setImageStyle] = useState('Cinematic');
  const [imageAspectRatio, setImageAspectRatio] = useState<"1:1" | "16:9" | "9:16">("1:1");

  const [isGenerating, setIsGenerating] = useState(false);
  const [isAutoConfiguring, setIsAutoConfiguring] = useState(false);
  const [isGeneratingImage, setIsGeneratingImage] = useState(false);
  const [isApiConnected, setIsApiConnected] = useState(false);

  useEffect(() => {
    checkApiKey();
    const saved = localStorage.getItem('kn-music-last-session');
    if (saved) {
      try {
        const data = JSON.parse(saved);
        setGeneratedLyrics(data.lyrics || '');
        setJsonPrompt(data.json || null);
        setSongTitle(data.songTitle || '');
        setReferences(data.references || '');
        setInspirations(data.inspirations || '');
        setCoverImage(data.coverImage || null);
        if (data.selectedModel) setSelectedModel(data.selectedModel);
        if (data.config) {
          setBpm(data.config.bpm ?? 60);
          setKeyName(data.config.keyName ?? 'F#m');
          setDuration(data.config.duration ?? 3.5);
          setVocalType(data.config.vocalType ?? 'ชาย');
          setSelectedGenres(data.config.selectedGenres ?? ['Rock', 'Alternative', 'Acoustic']);
          setPoemType(data.config.poemType ?? 'กลอน 4');
          setLanguage(data.config.language ?? 'ไทย');
          setAutoTitle(data.config.autoTitle ?? true);
          setAutoMelody(data.config.autoMelody ?? true);
        }
      } catch (e) {}
    }
  }, []);

  const checkApiKey = async () => {
    try {
      const hasKey = await window.aistudio?.hasSelectedApiKey();
      setIsApiConnected(!!hasKey);
    } catch (e) {}
  };

  const handleConnectApi = async () => {
    try {
      if (window.aistudio?.openSelectKey) {
        await window.aistudio.openSelectKey();
        setIsApiConnected(true);
        showStatus("เชื่อมต่อ API สำเร็จ");
      }
    } catch (e) {
      setError("ไม่สามารถเปิดหน้าต่างเลือก API ได้");
    }
  };

  const showStatus = (msg: string) => {
    setSuccessMsg(msg);
    setTimeout(() => setSuccessMsg(''), 4000);
  };

  const toggleGenre = useCallback((genre: string) => {
    setSelectedGenres((prev) => 
      prev.includes(genre) ? prev.filter((g) => g !== genre) : [...prev, genre]
    );
  }, []);

  const handleAutoConfigure = async () => {
    if (!prompt.trim()) return;
    setIsAutoConfiguring(true);
    setError(null);
    try {
      const data = await analyzeAndConfigure(prompt, GENRES_LIST, selectedModel);

      if (data.language) {
        const matchedLang = LANGUAGE_OPTIONS.find(opt => 
          opt.value === data.language || 
          opt.label.toLowerCase().includes(data.language.toLowerCase())
        );
        if (matchedLang) setLanguage(matchedLang.value);
      }

      if (data.bpm) setBpm(data.bpm);
      if (data.vocalType) setVocalType(data.vocalType);
      if (data.poemType) setPoemType(data.poemType);

      if (data.key && VALID_KEYS.includes(data.key)) {
        setKeyName(data.key);
      } else if (data.key) {
        const matchedKey = VALID_KEYS.find(k => data.key.startsWith(k));
        if (matchedKey) setKeyName(matchedKey);
      }

      let calculatedDuration = data.duration;
      if (calculatedDuration > 10) calculatedDuration = calculatedDuration / 60;
      setDuration(Math.min(Math.max(calculatedDuration, 1), 5));

      if (data.genres && Array.isArray(data.genres)) {
        const matched = data.genres.map(g => {
          const found = GENRES_LIST.find(systemGenre => 
            g.toLowerCase().includes(systemGenre.toLowerCase()) || 
            systemGenre.toLowerCase().includes(g.toLowerCase())
          );
          return found;
        }).filter((g): g is string => !!g);

        if (matched.length > 0) setSelectedGenres(Array.from(new Set(matched)));
      }

      showStatus(`AI ตั้งค่าให้เรียบร้อยแล้ว: ${data.reason}`);
    } catch (e: any) {
      console.error("Auto config error:", e);
      setError('การตั้งค่าอัตโนมัติล้มเหลว กรุณาลองใหม่อีกครั้ง');
    } finally {
      setIsAutoConfiguring(false);
    }
  };

  const handleGenerate = async () => {
    if (!prompt.trim()) return;
    setIsGenerating(true);
    setError(null);
    try {
      const data = await generateSong({ 
        prompt, references, inspirations, language, genres: selectedGenres, bpm, key: keyName, 
        vocalType, linesPerSection: 4, poemType, autoMelody, autoTitle, duration, 
        model: selectedModel 
      });
      setGeneratedLyrics(data.lyrics);
      setJsonPrompt(data.suno_config);
      if (autoTitle) setSongTitle(data.title);
      showStatus('สร้างบทเพลงสำเร็จแล้ว!');
    } catch (e: any) {
      if (e.message?.includes("Requested entity was not found.")) {
        setIsApiConnected(false);
        setError("เซสชัน API หมดอายุ กรุณาเชื่อมต่อใหม่อีกครั้ง");
        await handleConnectApi();
      } else {
        setError('การสร้างเพลงล้มเหลว กรุณาตรวจสอบ API หรือลองใหม่อีกครั้ง');
      }
    } finally {
      setIsGenerating(false);
    }
  };

  const handleGenerateImage = async () => {
    if (!prompt.trim()) return;
    setIsGeneratingImage(true);
    setError(null);
    try {
      const imgUrl = await generateCoverImage({ prompt: songTitle || prompt.substring(0, 50), aspectRatio: imageAspectRatio, style: imageStyle });
      setCoverImage(imgUrl);
      showStatus('สร้างภาพหน้าปกเรียบร้อย!');
    } catch (e: any) {
      if (e.message?.includes("Requested entity was not found.")) {
        setIsApiConnected(false);
        await handleConnectApi();
      } else {
        setError('การสร้างภาพหน้าปกล้มเหลว');
      }
    } finally {
      setIsGeneratingImage(false);
    }
  };

  const handleCopy = async (text: any) => {
    if (!text) return;
    const content = typeof text === 'object' ? JSON.stringify(text, null, 2) : text;
    try {
      await navigator.clipboard.writeText(content);
      showStatus('คัดลอกลงคลิปบอร์ดแล้ว!');
    } catch (err) {}
  };

  const handleResetAll = () => {
    if (confirm('ต้องการรีเซ็ตการตั้งค่าและเนื้อหาทั้งหมดใช่หรือไม่?')) {
      setPrompt('');
      setReferences('');
      setInspirations('');
      setSongTitle('');
      setGeneratedLyrics('');
      setJsonPrompt(null);
      setCoverImage(null);
      setBpm(60);
      setKeyName('F#m');
      setDuration(3.5);
      setVocalType('ชาย');
      setSelectedGenres(['Rock', 'Alternative', 'Acoustic']);
      setPoemType('กลอน 4');
      setLanguage('ไทย');
      showStatus('รีเซ็ตข้อมูลทั้งหมดแล้ว');
    }
  };

  const handleNewProject = () => {
    if (confirm('คุณแน่ใจหรือไม่ว่าต้องการเริ่มโปรเจกต์ใหม่? ข้อมูลเนื้อร้องปัจจุบันจะสูญหาย')) {
      setPrompt('');
      setReferences('');
      setInspirations('');
      setSongTitle('');
      setGeneratedLyrics('');
      setJsonPrompt(null);
      setCoverImage(null);
      showStatus('เริ่มโปรเจกต์ใหม่แล้ว');
    }
  };

  const handleSave = () => {
    const data = { 
      lyrics: generatedLyrics, 
      json: jsonPrompt, 
      prompt, 
      references, 
      inspirations, 
      songTitle, 
      coverImage, 
      selectedModel,
      config: { bpm, keyName, duration, vocalType, selectedGenres, poemType, language, autoTitle, autoMelody } 
    };
    localStorage.setItem('kn-music-last-session', JSON.stringify(data));
    showStatus('บันทึกโปรเจกต์เรียบร้อยแล้ว');
  };

  const handleExport = (type: 'lyrics' | 'json' | 'image') => {
    if (type === 'image' && coverImage) {
      const link = document.createElement('a');
      link.href = coverImage;
      link.download = `cover-${songTitle || 'song'}.png`;
      link.click();
      return;
    }
    const content = type === 'lyrics' ? generatedLyrics : JSON.stringify(jsonPrompt, null, 2);
    const filename = type === 'lyrics' ? 'lyrics.txt' : 'suno_config.json';
    if (!content) return;
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url; link.download = filename; link.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className={`min-h-screen transition-colors duration-300 ${theme === 'dark' ? 'bg-[#0a0a0a] text-white' : 'bg-gray-50 text-gray-900'}`}>
      <Header theme={theme} setTheme={setTheme} isApiConnected={isApiConnected} onConnectApi={handleConnectApi} successMsg={successMsg} />
      <main className="max-w-7xl mx-auto p-4 md:p-6 grid grid-cols-1 lg:grid-cols-2 gap-6">
        <Sidebar 
          theme={theme} prompt={prompt} setPrompt={setPrompt} references={references} setReferences={setReferences} 
          inspirations={inspirations} setInspirations={setInspirations} songTitle={songTitle} setSongTitle={setSongTitle} 
          bpm={bpm} setBpm={setBpm} keyName={keyName} setKeyName={setKeyName} duration={duration} setDuration={setDuration} 
          vocalType={vocalType} setVocalType={setVocalType} poemType={poemType} setPoemType={setPoemType} 
          language={language} setLanguage={setLanguage} autoTitle={autoTitle} setAutoTitle={setAutoTitle} 
          autoMelody={autoMelody} setAutoMelody={setAutoMelody} selectedGenres={selectedGenres} toggleGenre={toggleGenre} 
          genres={GENRES_LIST} imageAspectRatio={imageAspectRatio} setImageAspectRatio={setImageAspectRatio} 
          imageStyle={imageStyle} setImageStyle={setImageStyle} imageStyles={IMAGE_STYLES} languageOptions={LANGUAGE_OPTIONS} 
          isAutoConfiguring={isAutoConfiguring} isGenerating={isGenerating} isGeneratingImage={isGeneratingImage} 
          isApiConnected={isApiConnected} handleAutoConfigure={handleAutoConfigure} handleGenerate={handleGenerate} 
          handleGenerateImage={handleGenerateImage} handleConnectApi={handleConnectApi} error={error}
          selectedModel={selectedModel} setSelectedModel={setSelectedModel} modelOptions={MODEL_OPTIONS}
          handleResetAll={handleResetAll}
        />
        <Editor 
          theme={theme} generatedLyrics={generatedLyrics} setGeneratedLyrics={setGeneratedLyrics} songTitle={songTitle} duration={duration} 
          selectedGenres={selectedGenres} bpm={bpm} keyName={keyName} inspirations={inspirations} 
          isGenerating={isGenerating} coverImage={coverImage} imageAspectRatio={imageAspectRatio} 
          jsonPrompt={jsonPrompt} handleNewProject={handleNewProject} handleSave={handleSave} 
          handleCopy={handleCopy} handleExport={handleExport}
        />
      </main>
      <Footer theme={theme} />
    </div>
  );
};

export default App;

import React from 'react';
import { Loader2, Sparkles, AlertCircle } from 'lucide-react';
import { ModelSelector } from './sidebar/ModelSelector';
import { StorySection } from './sidebar/StorySection';
import { AIFeatureToggles } from './sidebar/AIFeatureToggles';
import { CoverStudio } from './sidebar/CoverStudio';
import { TechnicalSettings } from './sidebar/TechnicalSettings';
import { GenrePicker } from './sidebar/GenrePicker';

interface SidebarProps {
  theme: 'dark' | 'light';
  prompt: string;
  setPrompt: (v: string) => void;
  references: string;
  setReferences: (v: string) => void;
  inspirations: string;
  setInspirations: (v: string) => void;
  songTitle: string;
  setSongTitle: (v: string) => void;
  bpm: number;
  setBpm: (v: number) => void;
  keyName: string;
  setKeyName: (v: string) => void;
  duration: number;
  setDuration: (v: number) => void;
  vocalType: string;
  setVocalType: (v: string) => void;
  poemType: string;
  setPoemType: (v: string) => void;
  language: string;
  setLanguage: (v: string) => void;
  autoTitle: boolean;
  setAutoTitle: (v: boolean) => void;
  autoMelody: boolean;
  setAutoMelody: (v: boolean) => void;
  selectedGenres: string[];
  toggleGenre: (g: string) => void;
  genres: string[];
  imageAspectRatio: "1:1" | "16:9" | "9:16";
  setImageAspectRatio: (r: "1:1" | "16:9" | "9:16") => void;
  imageStyle: string;
  setImageStyle: (s: string) => void;
  imageStyles: string[];
  languageOptions: { value: string; label: string }[];
  isAutoConfiguring: boolean;
  isGenerating: boolean;
  isGeneratingImage: boolean;
  isApiConnected: boolean;
  handleAutoConfigure: () => void;
  handleGenerate: () => void;
  handleGenerateImage: () => void;
  handleConnectApi: () => void;
  error: string | null;
  selectedModel: string;
  setSelectedModel: (m: string) => void;
  modelOptions: { value: string; label: string; description: string }[];
  handleResetAll: () => void;
}

const Sidebar: React.FC<SidebarProps> = (props) => {
  const { isGenerating, prompt, isApiConnected, handleGenerate, handleConnectApi, error, modelOptions, selectedModel } = props;

  return (
    <div className="space-y-6">
      <ModelSelector {...props} />
      <StorySection {...props} />
      <AIFeatureToggles {...props} />
      <CoverStudio {...props} />
      <TechnicalSettings {...props} />
      <GenrePicker {...props} />

      <button
        onClick={handleGenerate}
        disabled={isGenerating || !prompt.trim() || !isApiConnected}
        className={`w-full py-5 rounded-3xl font-bold text-lg flex items-center justify-center gap-3 transition-all transform hover:scale-[1.01] active:scale-[0.99] shadow-xl ${
          isGenerating || !prompt.trim() || !isApiConnected
            ? 'bg-gray-800 text-gray-500 cursor-not-allowed grayscale'
            : 'bg-gradient-to-r from-indigo-600 to-violet-700 text-white shadow-indigo-500/20'
        }`}
      >
        {isGenerating ? (
          <><Loader2 className="animate-spin" size={24} /><span>กำลังสร้างเพลงด้วย {modelOptions.find(m => m.value === selectedModel)?.label}...</span></>
        ) : (
          <><Sparkles size={24} /><span>สร้างเพลงตอนนี้</span></>
        )}
      </button>

      {error && (
        <div className="p-4 rounded-2xl bg-red-500/10 border border-red-500/20 text-red-400 text-xs font-bold flex flex-col gap-2">
          <div className="flex items-center gap-3"><AlertCircle size={18} /><span>{error}</span></div>
          {error.includes("API") && <button onClick={handleConnectApi} className="underline text-left">เชื่อมต่อ API ทันที</button>}
        </div>
      )}
    </div>
  );
};

export default Sidebar;

import React, { useState, useEffect, useRef } from 'react';
import { Sparkles, Mic, MicOff, Loader2, Wand2, Search, Disc, Type as TypeIcon, History, Trash2, RotateCcw } from 'lucide-react';
import { SectionCard } from '../SharedUI';

interface StorySectionProps {
  theme: 'dark' | 'light';
  prompt: string;
  setPrompt: (v: string) => void;
  references: string;
  setReferences: (v: string) => void;
  inspirations: string;
  setInspirations: (v: string) => void;
  songTitle: string;
  setSongTitle: (v: string) => void;
  poemType: string;
  setPoemType: (v: string) => void;
  language: string;
  autoTitle: boolean;
  isAutoConfiguring: boolean;
  handleAutoConfigure: () => void;
  handleResetAll: () => void;
}

export const StorySection: React.FC<StorySectionProps> = (props) => {
  const { theme, prompt, setPrompt, references, setReferences, inspirations, setInspirations, songTitle, setSongTitle, poemType, setPoemType, language, autoTitle, isAutoConfiguring, handleAutoConfigure, handleResetAll } = props;
  const [isListening, setIsListening] = useState(false);
  const recognitionRef = useRef<any>(null);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.continuous = true;
      recognitionRef.current.interimResults = true;

      const langMap: Record<string, string> = { 
        'ไทย': 'th-TH', 
        'อังกฤษ': 'en-US', 
        'จีน': 'zh-CN', 
        'ญี่ปุ่น': 'ja-JP',
        'เกาหลี': 'ko-KR',
        'อีสาน': 'th-TH' 
      };

      recognitionRef.current.lang = langMap[language] || 'th-TH';
      recognitionRef.current.onresult = (event: any) => {
        let finalTranscript = '';
        for (let i = event.resultIndex; i < event.results.length; ++i) {
          if (event.results[i].isFinal) finalTranscript += event.results[i][0].transcript;
        }
        if (finalTranscript) setPrompt(prompt + (prompt ? ' ' : '') + finalTranscript);
      };
      recognitionRef.current.onerror = () => setIsListening(false);
      recognitionRef.current.onend = () => setIsListening(false);
    }
    return () => recognitionRef.current?.stop();
  }, [language, prompt, setPrompt]);

  const toggleListening = () => {
    if (isListening) { recognitionRef.current?.stop(); setIsListening(false); }
    else { try { recognitionRef.current?.start(); setIsListening(true); } catch (e) { console.error(e); } }
  };

  const clearPrompt = () => {
    if (prompt && confirm('ต้องการล้างเนื้อหาในช่องนี้ใช่หรือไม่?')) {
      setPrompt('');
    }
  };

  return (
    <SectionCard theme={theme}>
      <div className="flex justify-between items-center mb-4">
        <label className="text-sm font-bold flex items-center gap-2">
          <Sparkles size={16} className="text-indigo-500" /> เรื่องราว, พล็อต หรือหัวข้อเพลง
        </label>
        <div className="flex gap-2">
          {/* ปุ่มล้างเนื้อหา */}
          <button 
            onClick={clearPrompt} 
            title="ล้างเนื้อหา"
            className={`p-1.5 rounded-lg transition-all border ${theme === 'dark' ? 'bg-gray-800 border-gray-700 text-gray-400 hover:text-red-400' : 'bg-gray-100 border-gray-200 text-gray-600 hover:text-red-500'}`}
          >
            <Trash2 size={16} />
          </button>

          {/* ปุ่มรีเซ็ตทั้งหมด */}
          <button 
            onClick={handleResetAll} 
            title="รีเซ็ตค่าทั้งหมด"
            className={`p-1.5 rounded-lg transition-all border ${theme === 'dark' ? 'bg-gray-800 border-gray-700 text-gray-400 hover:text-indigo-400' : 'bg-gray-100 border-gray-200 text-gray-600 hover:text-indigo-600'}`}
          >
            <RotateCcw size={16} />
          </button>

          <button onClick={toggleListening} className={`p-1.5 rounded-lg transition-all border ${isListening ? 'bg-red-500/20 border-red-500 text-red-500 animate-pulse' : theme === 'dark' ? 'bg-gray-800 border-gray-700 text-gray-400 hover:text-white' : 'bg-gray-100 border-gray-200 text-gray-600 hover:text-indigo-600'}`}>
            {isListening ? <Mic size={16} /> : <MicOff size={16} />}
          </button>

          <button onClick={handleAutoConfigure} disabled={isAutoConfiguring || !prompt.trim()} className={`px-3 py-1.5 rounded-xl text-xs font-bold flex items-center gap-2 border transition-all ${isAutoConfiguring || !prompt.trim() ? 'opacity-50 cursor-not-allowed border-gray-700' : 'bg-indigo-500/10 border-indigo-500 text-indigo-400 hover:bg-indigo-500/20 shadow-md'}`}>
            {isAutoConfiguring ? <Loader2 className="animate-spin" size={14} /> : <Wand2 size={14} />} ตั้งค่า AI อัตโนมัติ
          </button>
        </div>
      </div>
      <div className="relative">
        <textarea value={prompt} onChange={(e) => setPrompt(e.target.value)} className={`w-full h-32 p-5 text-sm rounded-2xl resize-none focus:ring-2 focus:ring-indigo-500 outline-none border transition-all ${theme === 'dark' ? 'bg-[#0a0a0a] border-gray-800 text-gray-200' : 'bg-gray-50 border-gray-200 text-gray-800'}`} placeholder={isListening ? "กำลังฟัง..." : "บรรยายไอเดียของคุณที่นี่..."} />
        {isListening && <div className="absolute bottom-4 right-4 flex items-center gap-2 text-[10px] text-red-400 font-bold uppercase tracking-widest animate-pulse"><span className="w-1.5 h-1.5 rounded-full bg-red-500"></span> กำลังบันทึกเสียง</div>}
      </div>
      <div className="mt-6 grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="space-y-4">
          <div><label className="text-xs font-bold text-gray-500 uppercase mb-2 flex items-center gap-2"><Search size={12} /> สไตล์อ้างอิง</label>
          <input type="text" value={references} onChange={(e) => setReferences(e.target.value)} className={`w-full p-3 text-sm rounded-xl border ${theme === 'dark' ? 'bg-[#0a0a0a] border-gray-800 text-gray-300' : 'bg-gray-50 border-gray-200 text-gray-700'}`} placeholder="เช่น ร็อคไทยยุค 90" /></div>
          <div><label className="text-xs font-bold text-gray-500 uppercase mb-2 flex items-center gap-2"><Disc size={12} className="text-indigo-500" /> แรงบันดาลใจ</label>
          <input type="text" value={inspirations} onChange={(e) => setInspirations(e.target.value)} className={`w-full p-3 text-sm rounded-xl border ${theme === 'dark' ? 'bg-[#0a0a0a] border-gray-800 text-gray-300' : 'bg-gray-50 border-gray-200 text-gray-700'}`} placeholder="เช่น เพลงของบอดี้สแลม" /></div>
        </div>
        <div className="space-y-4">
          <div><label className="text-xs font-bold text-gray-500 uppercase mb-2 flex items-center gap-2"><TypeIcon size={12} /> ชื่อเพลง</label>
          <input type="text" value={songTitle} onChange={(e) => setSongTitle(e.target.value)} className={`w-full p-3 text-sm rounded-xl border ${theme === 'dark' ? 'bg-[#0a0a0a] border-gray-800 text-gray-300' : 'bg-gray-50 border-gray-200 text-gray-700'}`} placeholder={autoTitle ? "AI จะตั้งให้โดยอัตโนมัติ..." : "ใส่ชื่อเพลงที่ต้องการ"} /></div>
          <div><label className="text-xs font-bold text-gray-500 uppercase mb-2 flex items-center gap-2"><History size={12} /> จังหวะเนื้อร้อง</label>
          <select value={poemType} onChange={(e) => setPoemType(e.target.value)} className={`w-full p-3 text-sm rounded-xl border ${theme === 'dark' ? 'bg-[#0a0a0a] border-gray-800 text-indigo-400' : 'bg-gray-50 border-gray-200 text-indigo-600'}`}>
            <option value="กลอน 4">กลอน 4 (มาตรฐาน)</option>
            <option value="กลอน 8">กลอน 8 (สุนทรภู่)</option>
            <option value="ฟรีสไตล์">ฟรีสไตล์ (สมัยใหม่)</option>
            <option value="English Verse">สไตล์สากล (English)</option>
          </select></div>
        </div>
      </div>
    </SectionCard>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import Editor from './components/Editor';
import Footer from './components/Footer';
import { generateSong, analyzeAndConfigure, generateCoverImage } from './services/geminiService';
import { SunoConfig } from './types';

// Constants moved outside to prevent re-creation on render
const GENRES_LIST = ['Pop', 'Rock', 'Jazz', 'Hip-hop', 'R&B', 'Country', 'Folk', 'Blues', 'Electronic', 'Dance', 'House', 'Techno', 'Ambient', 'Classical', 'Reggae', 'Ska', 'Punk', 'Metal', 'Alternative', 'Indie', 'Acoustic', 'Soul', 'Funk', 'Disco', 'Trap', 'Lo-fi', 'Chill', 'Ballad'];
const VALID_KEYS = ['C', 'Cm', 'C#', 'C#m', 'D', 'Dm', 'Eb', 'E', 'Em', 'F', 'Fm', 'F#', 'F#m', 'G', 'Gm', 'Ab', 'A', 'Am', 'Bb', 'B', 'Bm'];
const IMAGE_STYLES = ['Cinematic', 'Digital Art', 'Oil Painting', 'Synthwave', 'Anime', 'Photorealistic', 'Neon Punk', 'Minimalist', 'Vintage Photo'];
const LANGUAGE_OPTIONS = [
  { value: 'ไทย', label: '🇹🇭 ภาษาไทย' },
  { value: 'อังกฤษ', label: '🇬🇧 English' },
  { value: 'จีน', label: '🇨🇳 中文' },
  { value: 'ญี่ปุ่น', label: '🇯🇵 日本語' },
  { value: 'เกาหลี', label: '🇰🇷 한국어' },
  { value: 'อีสาน', label: '🎭 ภาษาอีสาน' }
];
const MODEL_OPTIONS = [
  { value: 'gemini-3-pro-preview', label: 'Gemini 3 Pro', description: 'ดีที่สุดสำหรับการแต่งเพลงที่ซับซ้อนและเนื้อหาเชิงลึก' },
  { value: 'gemini-3-flash-preview', label: 'Gemini 3 Flash', description: 'ทำงานรวดเร็ว แม่นยำ เหมาะสำหรับการร่างเพลงด่วน' },
  { value: 'gemini-flash-lite-latest', label: 'Gemini Flash Lite', description: 'โมเดลขนาดเล็ก ประหยัดพลังงาน สำหรับงานทั่วไป' }
];

declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }
  interface Window {
    aistudio?: AIStudio;
  }
}

const App: React.FC = () => {
  const [theme, setTheme] = useState<'dark' | 'light'>('dark');
  const [successMsg, setSuccessMsg] = useState('');
  const [error, setError] = useState<string | null>(null);

  const [prompt, setPrompt] = useState('บทเพลงรักที่ระเบิดอารมณ์ความเจ็บปวด...');
  const [references, setReferences] = useState('แนวพี่เสก Loso, Bodyslam, เพลงร็อคยุค 90');
  const [inspirations, setInspirations] = useState('');
  const [songTitle, setSongTitle] = useState('');
  const [generatedLyrics, setGeneratedLyrics] = useState(``);
  const [jsonPrompt, setJsonPrompt] = useState<SunoConfig | null>(null);
  const [selectedModel, setSelectedModel] = useState('gemini-3-pro-preview');

  const [bpm, setBpm] = useState(60);
  const [keyName, setKeyName] = useState('F#m');
  const [duration, setDuration] = useState(3.5);
  const [vocalType, setVocalType] = useState('ชาย');
  const [selectedGenres, setSelectedGenres] = useState<string[]>(['Rock', 'Alternative', 'Acoustic']);
  const [poemType, setPoemType] = useState('กลอน 4');
  const [language, setLanguage] = useState('ไทย');
  const [autoTitle, setAutoTitle] = useState(true);
  const [autoMelody, setAutoMelody] = useState(true);

  const [coverImage, setCoverImage] = useState<string | null>(null);
  const [imageStyle, setImageStyle] = useState('Cinematic');
  const [imageAspectRatio, setImageAspectRatio] = useState<"1:1" | "16:9" | "9:16">("1:1");

  const [isGenerating, setIsGenerating] = useState(false);
  const [isAutoConfiguring, setIsAutoConfiguring] = useState(false);
  const [isGeneratingImage, setIsGeneratingImage] = useState(false);
  const [isApiConnected, setIsApiConnected] = useState(false);

  useEffect(() => {
    checkApiKey();
    const saved = localStorage.getItem('kn-music-last-session');
    if (saved) {
      try {
        const data = JSON.parse(saved);
        setGeneratedLyrics(data.lyrics || '');
        setJsonPrompt(data.json || null);
        setSongTitle(data.songTitle || '');
        setReferences(data.references || '');
        setInspirations(data.inspirations || '');
        setCoverImage(data.coverImage || null);
        if (data.selectedModel) setSelectedModel(data.selectedModel);
        if (data.config) {
          setBpm(data.config.bpm ?? 60);
          setKeyName(data.config.keyName ?? 'F#m');
          setDuration(data.config.duration ?? 3.5);
          setVocalType(data.config.vocalType ?? 'ชาย');
          setSelectedGenres(data.config.selectedGenres ?? ['Rock', 'Alternative', 'Acoustic']);
          setPoemType(data.config.poemType ?? 'กลอน 4');
          setLanguage(data.config.language ?? 'ไทย');
          setAutoTitle(data.config.autoTitle ?? true);
          setAutoMelody(data.config.autoMelody ?? true);
        }
      } catch (e) {}
    }
  }, []);

  const checkApiKey = async () => {
    try {
      const hasKey = await window.aistudio?.hasSelectedApiKey();
      setIsApiConnected(!!hasKey);
    } catch (e) {}
  };

  const handleConnectApi = async () => {
    try {
      if (window.aistudio?.openSelectKey) {
        await window.aistudio.openSelectKey();
        setIsApiConnected(true);
        showStatus("เชื่อมต่อ API สำเร็จ");
      }
    } catch (e) {
      setError("ไม่สามารถเปิดหน้าต่างเลือก API ได้");
    }
  };

  const showStatus = (msg: string) => {
    setSuccessMsg(msg);
    setTimeout(() => setSuccessMsg(''), 4000);
  };

  const toggleGenre = useCallback((genre: string) => {
    setSelectedGenres((prev) => 
      prev.includes(genre) ? prev.filter((g) => g !== genre) : [...prev, genre]
    );
  }, []);

  const handleAutoConfigure = async () => {
    if (!prompt.trim()) return;
    setIsAutoConfiguring(true);
    setError(null);
    try {
      const data = await analyzeAndConfigure(prompt, GENRES_LIST, selectedModel);

      if (data.language) {
        const matchedLang = LANGUAGE_OPTIONS.find(opt => 
          opt.value === data.language || 
          opt.label.toLowerCase().includes(data.language.toLowerCase())
        );
        if (matchedLang) setLanguage(matchedLang.value);
      }

      if (data.bpm) setBpm(data.bpm);
      if (data.vocalType) setVocalType(data.vocalType);
      if (data.poemType) setPoemType(data.poemType);

      if (data.key && VALID_KEYS.includes(data.key)) {
        setKeyName(data.key);
      } else if (data.key) {
        const matchedKey = VALID_KEYS.find(k => data.key.startsWith(k));
        if (matchedKey) setKeyName(matchedKey);
      }

      let calculatedDuration = data.duration;
      if (calculatedDuration > 10) calculatedDuration = calculatedDuration / 60;
      setDuration(Math.min(Math.max(calculatedDuration, 1), 5));

      if (data.genres && Array.isArray(data.genres)) {
        const matched = data.genres.map(g => {
          const found = GENRES_LIST.find(systemGenre => 
            g.toLowerCase().includes(systemGenre.toLowerCase()) || 
            systemGenre.toLowerCase().includes(g.toLowerCase())
          );
          return found;
        }).filter((g): g is string => !!g);

        if (matched.length > 0) setSelectedGenres(Array.from(new Set(matched)));
      }

      showStatus(`AI ตั้งค่าให้เรียบร้อยแล้ว: ${data.reason}`);
    } catch (e: any) {
      console.error("Auto config error:", e);
      setError('การตั้งค่าอัตโนมัติล้มเหลว กรุณาลองใหม่อีกครั้ง');
    } finally {
      setIsAutoConfiguring(false);
    }
  };

  const handleGenerate = async () => {
    if (!prompt.trim()) return;
    setIsGenerating(true);
    setError(null);
    try {
      const data = await generateSong({ 
        prompt, references, inspirations, language, genres: selectedGenres, bpm, key: keyName, 
        vocalType, linesPerSection: 4, poemType, autoMelody, autoTitle, duration, 
        model: selectedModel 
      });
      setGeneratedLyrics(data.lyrics);
      setJsonPrompt(data.suno_config);
      if (autoTitle) setSongTitle(data.title);
      showStatus('สร้างบทเพลงสำเร็จแล้ว!');
    } catch (e: any) {
      if (e.message?.includes("Requested entity was not found.")) {
        setIsApiConnected(false);
        setError("เซสชัน API หมดอายุ กรุณาเชื่อมต่อใหม่อีกครั้ง");
        await handleConnectApi();
      } else {
        setError('การสร้างเพลงล้มเหลว กรุณาตรวจสอบ API หรือลองใหม่อีกครั้ง');
      }
    } finally {
      setIsGenerating(false);
    }
  };

  const handleGenerateImage = async () => {
    if (!prompt.trim()) return;
    setIsGeneratingImage(true);
    setError(null);
    try {
      const imgUrl = await generateCoverImage({ prompt: songTitle || prompt.substring(0, 50), aspectRatio: imageAspectRatio, style: imageStyle });
      setCoverImage(imgUrl);
      showStatus('สร้างภาพหน้าปกเรียบร้อย!');
    } catch (e: any) {
      if (e.message?.includes("Requested entity was not found.")) {
        setIsApiConnected(false);
        await handleConnectApi();
      } else {
        setError('การสร้างภาพหน้าปกล้มเหลว');
      }
    } finally {
      setIsGeneratingImage(false);
    }
  };

  const handleCopy = async (text: any) => {
    if (!text) return;
    const content = typeof text === 'object' ? JSON.stringify(text, null, 2) : text;
    try {
      await navigator.clipboard.writeText(content);
      showStatus('คัดลอกลงคลิปบอร์ดแล้ว!');
    } catch (err) {}
  };

  const handleResetAll = useCallback(() => {
    if (window.confirm('ต้องการรีเซ็ตการตั้งค่าและเนื้อหาทั้งหมดใช่หรือไม่?')) {
      setPrompt('');
      setReferences('');
      setInspirations('');
      setSongTitle('');
      setGeneratedLyrics('');
      setJsonPrompt(null);
      setCoverImage(null);
      setBpm(60);
      setKeyName('F#m');
      setDuration(3.5);
      setVocalType('ชาย');
      setSelectedGenres(['Rock', 'Alternative', 'Acoustic']);
      setPoemType('กลอน 4');
      setLanguage('ไทย');
      showStatus('รีเซ็ตข้อมูลทั้งหมดแล้ว');
    }
  }, []);

  const handleNewProject = () => {
    if (window.confirm('คุณแน่ใจหรือไม่ว่าต้องการเริ่มโปรเจกต์ใหม่? ข้อมูลเนื้อร้องปัจจุบันจะสูญหาย')) {
      setPrompt('');
      setReferences('');
      setInspirations('');
      setSongTitle('');
      setGeneratedLyrics('');
      setJsonPrompt(null);
      setCoverImage(null);
      showStatus('เริ่มโปรเจกต์ใหม่แล้ว');
    }
  };

  const handleSave = () => {
    const data = { 
      lyrics: generatedLyrics, 
      json: jsonPrompt, 
      prompt, 
      references, 
      inspirations, 
      songTitle, 
      coverImage, 
      selectedModel,
      config: { bpm, keyName, duration, vocalType, selectedGenres, poemType, language, autoTitle, autoMelody } 
    };
    localStorage.setItem('kn-music-last-session', JSON.stringify(data));
    showStatus('บันทึกโปรเจกต์เรียบร้อยแล้ว');
  };

  const handleExport = (type: 'lyrics' | 'json' | 'image') => {
    if (type === 'image' && coverImage) {
      const link = document.createElement('a');
      link.href = coverImage;
      link.download = `cover-${songTitle || 'song'}.png`;
      link.click();
      return;
    }
    const content = type === 'lyrics' ? generatedLyrics : JSON.stringify(jsonPrompt, null, 2);
    const filename = type === 'lyrics' ? 'lyrics.txt' : 'suno_config.json';
    if (!content) return;
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url; link.download = filename; link.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className={`min-h-screen transition-colors duration-300 ${theme === 'dark' ? 'bg-[#0a0a0a] text-white' : 'bg-gray-50 text-gray-900'}`}>
      <Header theme={theme} setTheme={setTheme} isApiConnected={isApiConnected} onConnectApi={handleConnectApi} successMsg={successMsg} />
      <main className="max-w-7xl mx-auto p-4 md:p-6 grid grid-cols-1 lg:grid-cols-2 gap-6">
        <Sidebar 
          theme={theme} prompt={prompt} setPrompt={setPrompt} references={references} setReferences={setReferences} 
          inspirations={inspirations} setInspirations={setInspirations} songTitle={songTitle} setSongTitle={setSongTitle} 
          bpm={bpm} setBpm={setBpm} keyName={keyName} setKeyName={setKeyName} duration={duration} setDuration={setDuration} 
          vocalType={vocalType} setVocalType={setVocalType} poemType={poemType} setPoemType={setPoemType} 
          language={language} setLanguage={setLanguage} autoTitle={autoTitle} setAutoTitle={setAutoTitle} 
          autoMelody={autoMelody} setAutoMelody={setAutoMelody} selectedGenres={selectedGenres} toggleGenre={toggleGenre} 
          genres={GENRES_LIST} imageAspectRatio={imageAspectRatio} setImageAspectRatio={setImageAspectRatio} 
          imageStyle={imageStyle} setImageStyle={setImageStyle} imageStyles={IMAGE_STYLES} languageOptions={LANGUAGE_OPTIONS} 
          isAutoConfiguring={isAutoConfiguring} isGenerating={isGenerating} isGeneratingImage={isGeneratingImage} 
          isApiConnected={isApiConnected} handleAutoConfigure={handleAutoConfigure} handleGenerate={handleGenerate} 
          handleGenerateImage={handleGenerateImage} handleConnectApi={handleConnectApi} error={error}
          selectedModel={selectedModel} setSelectedModel={setSelectedModel} modelOptions={MODEL_OPTIONS}
          handleResetAll={handleResetAll}
        />
        <Editor 
          theme={theme} generatedLyrics={generatedLyrics} setGeneratedLyrics={setGeneratedLyrics} songTitle={songTitle} duration={duration} 
          selectedGenres={selectedGenres} bpm={bpm} keyName={keyName} inspirations={inspirations} 
          isGenerating={isGenerating} coverImage={coverImage} imageAspectRatio={imageAspectRatio} 
          jsonPrompt={jsonPrompt} handleNewProject={handleNewProject} handleSave={handleSave} 
          handleCopy={handleCopy} handleExport={handleExport}
        />
      </main>
      <Footer theme={theme} />
    </div>
  );
};

