            <option value="กลอน 4">กลอน 4 (มาตรฐาน)</option>
            <option value="กลอน 8">กลอน 8 (สุนทรภู่)</option>
            <option value="ฟรีสไตล์">ฟรีสไตล์ (สมัยใหม่)</option>
            <option value="English Verse">สไตล์สากล (English)</option>
