import { generateSong, analyzeAndConfigure, generateCoverImage } from './services/geminiService';
import { SunoConfig } from './types';

const GENRES_LIST = ['Pop', 'Rock', 'Jazz', 'Hip-hop', 'R&B', 'Country', 'Folk', 'Blues', 'Electronic', 'Dance', 'House', 'Techno', 'Ambient', 'Classical', 'Reggae', 'Ska', 'Punk', 'Metal', 'Alternative', 'Indie', 'Acoustic', 'Soul', 'Funk', 'Disco', 'Trap', 'Lo-fi', 'Chill', 'Ballad'];
const VALID_KEYS = ['C', 'Cm', 'C#', 'C#m', 'D', 'Dm', 'Eb', 'E', 'Em', 'F', 'Fm', 'F#', 'F#m', 'G', 'Gm', 'Ab', 'A', 'Am', 'Bb', 'B', 'Bm'];
const IMAGE_STYLES = ['Cinematic', 'Digital Art', 'Oil Painting', 'Synthwave', 'Anime', 'Photorealistic', 'Neon Punk', 'Minimalist', 'Vintage Photo'];
const LANGUAGE_OPTIONS = [
  { value: 'ไทย', label: '🇹🇭 ภาษาไทย' },
  { value: 'อังกฤษ', label: '🇬🇧 English' },
  { value: 'จีน', label: '🇨🇳 中文' },
  { value: 'ญี่ปุ่น', label: '🇯🇵 日本語' },
  { value: 'เกาหลี', label: '🇰🇷 한국어' },
  { value: 'อีสาน', label: '🎭 ภาษาอีสาน' }
];
const MODEL_OPTIONS = [
  { value: 'gemini-3-pro-preview', label: 'Gemini 3 Pro', description: 'ดีที่สุดสำหรับการแต่งเพลงที่ซับซ้อนและเนื้อหาเชิงลึก' },
  { value: 'gemini-3-flash-preview', label: 'Gemini 3 Flash', description: 'ทำงานรวดเร็ว แม่นยำ เหมาะสำหรับการร่างเพลงด่วน' },
  { value: 'gemini-flash-lite-latest', label: 'Gemini Flash Lite', description: 'โมเดลขนาดเล็ก ประหยัดพลังงาน สำหรับงานทั่วไป' }
];

declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }
  interface Window {
    aistudio?: AIStudio;
  }
}

const App: React.FC = () => {
  const [theme, setTheme] = useState<'dark' | 'light'>('dark');
  const [successMsg, setSuccessMsg] = useState('');
  const [error, setError] = useState<string | null>(null);

  const [prompt, setPrompt] = useState('บทเพลงรักที่ระเบิดอารมณ์ความเจ็บปวด...');
  const [references, setReferences] = useState('แนวพี่เสก Loso, Bodyslam, เพลงร็อคยุค 90');
  const [inspirations, setInspirations] = useState('');
  const [songTitle, setSongTitle] = useState('');
  const [generatedLyrics, setGeneratedLyrics] = useState(``);
  const [jsonPrompt, setJsonPrompt] = useState<SunoConfig | null>(null);
  const [selectedModel, setSelectedModel] = useState('gemini-3-pro-preview');

  const [bpm, setBpm] = useState(60);
  const [keyName, setKeyName] = useState('F#m');
  const [duration, setDuration] = useState(3.5);
  const [vocalType, setVocalType] = useState('ชาย');
  const [selectedGenres, setSelectedGenres] = useState<string[]>(['Rock', 'Alternative', 'Acoustic']);
  const [poemType, setPoemType] = useState('กลอน 4');
  const [language, setLanguage] = useState('ไทย');
  const [autoTitle, setAutoTitle] = useState(true);
  const [autoMelody, setAutoMelody] = useState(true);

  const [coverImage, setCoverImage] = useState<string | null>(null);
  const [imageStyle, setImageStyle] = useState('Cinematic');
  const [imageAspectRatio, setImageAspectRatio] = useState<"1:1" | "16:9" | "9:16">("1:1");

  const [isGenerating, setIsGenerating] = useState(false);
  const [isAutoConfiguring, setIsAutoConfiguring] = useState(false);
  const [isGeneratingImage, setIsGeneratingImage] = useState(false);
  const [isApiConnected, setIsApiConnected] = useState(false);

  useEffect(() => {
    checkApiKey();
    const saved = localStorage.getItem('kn-music-last-session');
    if (saved) {
      try {
        const data = JSON.parse(saved);
        setGeneratedLyrics(data.lyrics || '');
        setJsonPrompt(data.json || null);
        setSongTitle(data.songTitle || '');
        setReferences(data.references || '');
        setInspirations(data.inspirations || '');
        setCoverImage(data.coverImage || null);
        if (data.selectedModel) setSelectedModel(data.selectedModel);
        if (data.config) {
          setBpm(data.config.bpm ?? 60);
          setKeyName(data.config.keyName ?? 'F#m');
          setDuration(data.config.duration ?? 3.5);
          setVocalType(data.config.vocalType ?? 'ชาย');
          setSelectedGenres(data.config.selectedGenres ?? ['Rock', 'Alternative', 'Acoustic']);
          setPoemType(data.config.poemType ?? 'กลอน 4');
          setLanguage(data.config.language ?? 'ไทย');
          setAutoTitle(data.config.autoTitle ?? true);
          setAutoMelody(data.config.autoMelody ?? true);
        }
      } catch (e) {}
    }
  }, []);

  const checkApiKey = async () => {
    try {
      const hasKey = await window.aistudio?.hasSelectedApiKey();
      setIsApiConnected(!!hasKey);
    } catch (e) {}
  };

  const handleConnectApi = async () => {
    try {
      if (window.aistudio?.openSelectKey) {
        await window.aistudio.openSelectKey();
        setIsApiConnected(true);
        showStatus("เชื่อมต่อ API สำเร็จ");
      }
    } catch (e) {
      setError("ไม่สามารถเปิดหน้าต่างเลือก API ได้");
    }
  };

  const showStatus = (msg: string) => {
    setSuccessMsg(msg);
    setTimeout(() => setSuccessMsg(''), 4000);
  };

  const toggleGenre = useCallback((genre: string) => {
    setSelectedGenres((prev) => 
      prev.includes(genre) ? prev.filter((g) => g !== genre) : [...prev, genre]
    );
  }, []);

  const handleAutoConfigure = async () => {
    if (!prompt.trim()) return;
    setIsAutoConfiguring(true);
    setError(null);
    try {
      const data = await analyzeAndConfigure(prompt, GENRES_LIST, selectedModel);

      // Update Language with direct match or label search
      if (data.language) {
        const matchedLang = LANGUAGE_OPTIONS.find(opt => 
          opt.value === data.language || 
          opt.label.toLowerCase().includes(data.language.toLowerCase())
        );
        if (matchedLang) setLanguage(matchedLang.value);
      }

      if (data.bpm) setBpm(data.bpm);
      if (data.vocalType) setVocalType(data.vocalType);
      if (data.poemType) setPoemType(data.poemType);

      // Robust Key Matching
      if (data.key) {
        const cleanKey = data.key.replace(/\s/g, '');
        const foundKey = VALID_KEYS.find(k => k.toLowerCase() === cleanKey.toLowerCase());
        if (foundKey) setKeyName(foundKey);
      }

      setDuration(Math.min(Math.max(data.duration || 3.5, 1), 5));

      // IMPROVED FUZZY GENRE MATCHING
      if (data.genres && Array.isArray(data.genres)) {
        const matched = data.genres.map(g => {
          const target = g.trim().toLowerCase().replace(/-/g, '').replace(/\s/g, '');
          return GENRES_LIST.find(systemGenre => {
            const system = systemGenre.toLowerCase().replace(/-/g, '').replace(/\s/g, '');
            return system === target || system.includes(target) || target.includes(system);
          });
        }).filter((g): g is string => !!g);

        if (matched.length > 0) {
          setSelectedGenres(Array.from(new Set(matched))); // Unique values
        }
      }

      showStatus(`AI ตั้งค่าให้เรียบร้อยแล้ว: ${data.reason}`);
    } catch (e: any) {
      console.error("Auto configuration error:", e);
      setError('การตั้งค่าอัตโนมัติล้มเหลว กรุณาลองใหม่');
    } finally {
      setIsAutoConfiguring(false);
    }
  };

  const handleGenerate = async () => {
    if (!prompt.trim()) return;
    setIsGenerating(true);
    setError(null);
    try {
      const data = await generateSong({ 
        prompt, references, inspirations, language, genres: selectedGenres, bpm, key: keyName, 
        vocalType, linesPerSection: 4, poemType, autoMelody, autoTitle, duration, 
        model: selectedModel 
      });
      setGeneratedLyrics(data.lyrics);
      setJsonPrompt(data.suno_config);
      if (autoTitle) setSongTitle(data.title);
      showStatus('สร้างบทเพลงสำเร็จแล้ว!');
    } catch (e: any) {
      setError('การสร้างเพลงล้มเหลว');
    } finally {
      setIsGenerating(false);
    }
  };

  const handleGenerateImage = async () => {
    if (!prompt.trim()) return;
    setIsGeneratingImage(true);
    setError(null);
    try {
      const imgUrl = await generateCoverImage({ prompt: songTitle || prompt.substring(0, 50), aspectRatio: imageAspectRatio, style: imageStyle });
      setCoverImage(imgUrl);
      showStatus('สร้างภาพหน้าปกเรียบร้อย!');
    } catch (e: any) {
      setError('การสร้างภาพหน้าปกล้มเหลว');
    } finally {
      setIsGeneratingImage(false);
    }
  };

  const handleCopy = async (text: any) => {
    if (!text) return;
    const content = typeof text === 'object' ? JSON.stringify(text, null, 2) : text;
    try {
      await navigator.clipboard.writeText(content);
      showStatus('คัดลอกลงคลิปบอร์ดแล้ว!');
    } catch (err) {}
  };

  const handleResetAll = useCallback(() => {
    if (window.confirm('คุณต้องการรีเซ็ตการตั้งค่าและเนื้อหาทั้งหมดกลับสู่ค่าเริ่มต้นใช่หรือไม่?')) {
      setPrompt('');
      setReferences('');
      setInspirations('');
      setSongTitle('');
      setGeneratedLyrics('');
      setJsonPrompt(null);
      setCoverImage(null);
      setBpm(60);
      setKeyName('F#m');
      setDuration(3.5);
      setVocalType('ชาย');
      setSelectedGenres(['Rock', 'Alternative', 'Acoustic']);
      setPoemType('กลอน 4');
      setLanguage('ไทย');
      showStatus('รีเซ็ตข้อมูลทั้งหมดแล้ว');
    }
  }, []);

  const handleClearPrompt = useCallback(() => {
    if (window.confirm('ต้องการล้างเนื้อหาในช่องเรื่องราวใช่หรือไม่?')) {
      setPrompt('');
      showStatus('ล้างช่องเรื่องราวแล้ว');
    }
  }, []);

  const handleNewProject = () => {
    if (window.confirm('คุณแน่ใจหรือไม่ว่าต้องการเริ่มโปรเจกต์ใหม่? ข้อมูลเนื้อร้องปัจจุบันจะสูญหาย')) {
      setPrompt('');
      setReferences('');
      setInspirations('');
      setSongTitle('');
      setGeneratedLyrics('');
      setJsonPrompt(null);
      setCoverImage(null);
      showStatus('เริ่มโปรเจกต์ใหม่แล้ว');
    }
  };

  const handleSave = () => {
    const data = { 
      lyrics: generatedLyrics, 
      json: jsonPrompt, 
      prompt, 
      references, 
      inspirations, 
      songTitle, 
      coverImage, 
      selectedModel,
      config: { bpm, keyName, duration, vocalType, selectedGenres, poemType, language, autoTitle, autoMelody } 
    };
    localStorage.setItem('kn-music-last-session', JSON.stringify(data));
    showStatus('บันทึกโปรเจกต์เรียบร้อยแล้ว');
  };

  const handleExport = (type: 'lyrics' | 'json' | 'image') => {
    if (type === 'image' && coverImage) {
      const link = document.createElement('a');
      link.href = coverImage;
      link.download = `cover-${songTitle || 'song'}.png`;
      link.click();
      return;
    }
    const content = type === 'lyrics' ? generatedLyrics : JSON.stringify(jsonPrompt, null, 2);
    const filename = type === 'lyrics' ? 'lyrics.txt' : 'suno_config.json';
    if (!content) return;
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url; link.download = filename; link.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className={`min-h-screen transition-colors duration-300 ${theme === 'dark' ? 'bg-[#0a0a0a] text-white' : 'bg-gray-50 text-gray-900'}`}>
      <Header theme={theme} setTheme={setTheme} isApiConnected={isApiConnected} onConnectApi={handleConnectApi} successMsg={successMsg} />
      <main className="max-w-7xl mx-auto p-4 md:p-6 grid grid-cols-1 lg:grid-cols-2 gap-6">
        <Sidebar 
          {...{theme, prompt, setPrompt, references, setReferences, inspirations, setInspirations, songTitle, setSongTitle, bpm, setBpm, keyName, setKeyName, duration, setDuration, vocalType, setVocalType, poemType, setPoemType, language, setLanguage, autoTitle, setAutoTitle, autoMelody, setAutoMelody, selectedGenres, toggleGenre, genres: GENRES_LIST, imageAspectRatio, setImageAspectRatio, imageStyle, setImageStyle, imageStyles: IMAGE_STYLES, languageOptions: LANGUAGE_OPTIONS, isAutoConfiguring, isGenerating, isGeneratingImage, isApiConnected, handleAutoConfigure, handleGenerate, handleGenerateImage, handleConnectApi, error, selectedModel, setSelectedModel, modelOptions: MODEL_OPTIONS, handleResetAll, handleClearPrompt}}
        />
        <Editor 
          {...{theme, generatedLyrics, setGeneratedLyrics, songTitle, duration, selectedGenres, bpm, keyName, inspirations, isGenerating, coverImage, imageAspectRatio, jsonPrompt, handleNewProject, handleSave, handleCopy, handleExport}}
        />
      </main>
      <Footer theme={theme} />
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { SongData, AutoConfigData, ImageGenerationParams } from "../types";

const VALID_KEYS = ['C', 'Cm', 'C#', 'C#m', 'D', 'Dm', 'Eb', 'E', 'Em', 'F', 'Fm', 'F#', 'F#m', 'G', 'Gm', 'Ab', 'A', 'Am', 'Bb', 'B', 'Bm'];

export const generateSong = async (params: {
  prompt: string;
  references?: string;
  inspirations?: string;
  language: string;
  genres: string[];
  bpm: number;
  key: string;
  vocalType: string;
  linesPerSection: number;
  poemType: string;
  autoMelody: boolean;
  autoTitle: boolean;
  duration: number;
  model: string;
}): Promise<SongData> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `You are a Master Songwriter and Music Arranger.
Your task is to write a COMPLETE SONG in ${params.language} for a ${params.duration} minute track.

MANDATORY FORMATTING RULES:
1. Use DOUBLE NEWLINES between every section to ensure readability.
2. Every section MUST follow this EXACT 3-layer structure:
   - Layer 1: [Tag] (e.g., [Intro], [Verse 1], [Chorus])
   - Layer 2: (Musical Description in English) -> Describe mood, instruments, and vocal style in parentheses.
   - Layer 3: The actual lyrics (or music cues for instrumentals).

Example of a section:
[Verse 1]
(Acoustic guitar strumming softly with a warm, intimate male vocal)
Line of lyrics 1...
Line of lyrics 2...

REQUIRED SECTIONS:
- [Intro], [Verse 1], [Verse 2], [Pre-Chorus], [Chorus], [Instrumental Solo], [Bridge], [Final Chorus], [Outro].

Style Guidelines:
- Language: ${params.language}
- Genres: ${params.genres.join(', ')}
- Poem Style: ${params.poemType}
- Description Language: English (Professional standard).`;

  const userPrompt = `
  Topic: ${params.prompt}
  Details: BPM ${params.bpm}, Key ${params.key}, Vocal: ${params.vocalType}.
  Reference: ${params.references || 'None'}.
  Inspiration: ${params.inspirations || 'None'}.
  `;

  const response = await ai.models.generateContent({
    model: params.model,
    contents: userPrompt,
    config: {
      systemInstruction,
      thinkingConfig: { thinkingBudget: 4000 },
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          lyrics: { type: Type.STRING },
          duration_minutes: { type: Type.NUMBER },
          suno_config: {
            type: Type.OBJECT,
            properties: {
              style: { type: Type.STRING },
              tempo: { type: Type.STRING },
              key: { type: Type.STRING },
              vocal_description: { type: Type.STRING },
              mood: { type: Type.STRING },
              instrumentation: { type: Type.STRING }
            }
          }
        },
        required: ["title", "lyrics", "suno_config", "duration_minutes"]
      }
    }
  });

  const data = JSON.parse(response.text || '{}');
  // Clean literal \n if AI mistakenly includes them as text
  if (data.lyrics) {
    data.lyrics = data.lyrics.replace(/\\n/g, '\n');
  }
  return data;
};

export const analyzeAndConfigure = async (prompt: string, allowedGenres: string[], model: string): Promise<AutoConfigData> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await ai.models.generateContent({
    model,
    contents: `วิเคราะห์ไอเดียเพลง: "${prompt}"`,
    config: {
      systemInstruction: `Producer Role. Choose from: ${allowedGenres.join(', ')}. Recommend BPM, Key, Duration (1-5m), Language.`,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          language: { type: Type.STRING },
          genres: { type: Type.ARRAY, items: { type: Type.STRING } },
          bpm: { type: Type.INTEGER },
          key: { type: Type.STRING },
          vocalType: { type: Type.STRING },
          poemType: { type: Type.STRING },
          linesPerSection: { type: Type.INTEGER },
          duration: { type: Type.NUMBER },
          reason: { type: Type.STRING }
        },
        required: ["language", "genres", "bpm", "key", "vocalType", "poemType", "linesPerSection", "duration", "reason"]
      }
    }
  });
  return JSON.parse(response.text || '{}');
};

export const generateCoverImage = async (params: ImageGenerationParams): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: { parts: [{ text: `High-quality album cover for a song titled "${params.prompt}". Style: ${params.style}. Professional art.` }] },
    config: { imageConfig: { aspectRatio: params.aspectRatio } }
  });
  const part = response.candidates[0].content.parts.find(p => p.inlineData);
  if (part?.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
  throw new Error('Image failed');
};

import React, { useRef, useEffect } from 'react';
import { FileText, Music, Clock, Download, Plus, Save, Clipboard, ImageIcon, ChevronRight, Loader2 } from 'lucide-react';
import { ToolButton } from './SharedUI';

interface EditorProps {
  theme: 'dark' | 'light';
  generatedLyrics: string;
  setGeneratedLyrics: (v: string) => void;
  songTitle: string;
  duration: number;
  selectedGenres: string[];
  bpm: number;
  keyName: string;
  inspirations: string;
  isGenerating: boolean;
  coverImage: string | null;
  imageAspectRatio: "1:1" | "16:9" | "9:16";
  jsonPrompt: any;
  handleNewProject: () => void;
  handleSave: () => void;
  handleCopy: (v: any) => void;
  handleExport: (t: 'lyrics' | 'json' | 'image') => void;
}

const Editor: React.FC<EditorProps> = (props) => {
  const { theme, generatedLyrics, setGeneratedLyrics, songTitle, duration, selectedGenres, bpm, keyName, inspirations, isGenerating, coverImage, imageAspectRatio, jsonPrompt, handleNewProject, handleSave, handleCopy, handleExport } = props;

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const backdropRef = useRef<HTMLDivElement>(null);

  const handleScroll = () => {
    if (textareaRef.current && backdropRef.current) {
      backdropRef.current.scrollTop = textareaRef.current.scrollTop;
    }
  };

  const getTagStyle = (line: string) => {
    const text = line.toLowerCase();
    if (text.includes('chorus')) return 'bg-purple-500/20 border-purple-500/40 text-purple-400';
    if (text.includes('solo') || text.includes('instrumental')) return 'bg-amber-500/20 border-amber-500/40 text-amber-400';
    if (text.includes('intro') || text.includes('outro')) return 'bg-blue-500/20 border-blue-500/40 text-blue-400';
    if (text.includes('bridge')) return 'bg-emerald-500/20 border-emerald-500/40 text-emerald-400';
    if (text.includes('verse')) return 'bg-indigo-500/10 border-indigo-500/30 text-indigo-400';
    return 'bg-gray-500/20 border-gray-500/40 text-gray-400';
  };

  const renderHighlightedText = (text: string) => {
    if (!text) return null;

    // Normalize string: solve literal \n issue and extra spaces
    const cleanText = text.replace(/\\n/g, '\n');

    return cleanText.split('\n').map((line, i) => {
      const hasTag = line.trim().startsWith('[') && line.trim().endsWith(']');
      const hasDescription = line.trim().startsWith('(') && line.trim().endsWith(')');

      if (hasTag) {
        const styleClass = getTagStyle(line);
        return (
          <div key={i} className="min-h-[2.4em] flex items-center mb-1 mt-4 first:mt-0">
            <span className={`px-4 py-1.5 rounded-xl border font-black text-[12px] uppercase tracking-wider flex items-center gap-3 shadow-sm ${styleClass}`}>
              <div className="w-1.5 h-1.5 rounded-full bg-current animate-pulse" />
              {line}
            </span>
          </div>
        );
      }

      if (hasDescription) {
        return (
          <div key={i} className={`min-h-[1.6em] py-1 text-[15px] italic font-medium opacity-60 flex items-center gap-2 ${theme === 'dark' ? 'text-indigo-300' : 'text-indigo-600'}`}>
             <Music size={12} className="opacity-40" /> {line}
          </div>
        );
      }

      return (
        <div key={i} className="min-h-[1.6em] py-0.5">
          {line || ' '}
        </div>
      );
    });
  };

  useEffect(() => {
    handleScroll();
  }, [generatedLyrics]);

  return (
    <div className="space-y-6 flex flex-col h-full">
      <div className="flex flex-wrap gap-2">
        <ToolButton onClick={handleNewProject} icon={<Plus size={16} />} label="ใหม่" theme={theme} />
        <ToolButton onClick={handleSave} icon={<Save size={16} />} label="บันทึก" theme={theme} />
        <ToolButton onClick={() => handleCopy(generatedLyrics)} icon={<Clipboard size={16} />} label="คัดลอก" theme={theme} disabled={!generatedLyrics} />
        <ToolButton onClick={() => handleExport('lyrics')} icon={<Download size={16} />} label="ส่งออก TXT" theme={theme} disabled={!generatedLyrics} />
        <ToolButton onClick={() => handleExport('image')} icon={<ImageIcon size={16} />} label="โหลดปก" theme={theme} disabled={!coverImage} />
      </div>

      <section className={`flex-1 rounded-[3rem] border flex flex-col overflow-hidden min-h-[650px] shadow-2xl transition-all duration-500 ${theme === 'dark' ? 'bg-[#050505] border-gray-800/40 shadow-indigo-500/10' : 'bg-white border-gray-100 shadow-xl'}`}>
        <div className={`px-10 py-6 border-b flex justify-between items-center ${theme === 'dark' ? 'border-gray-800/40 bg-[#080808]' : 'border-gray-50 bg-gray-50/30'}`}>
          <h3 className="text-[11px] font-black flex items-center gap-3 uppercase tracking-[0.3em] text-gray-500">
            <div className="w-2 h-2 rounded-full bg-indigo-500 shadow-[0_0_10px_rgba(99,102,241,0.8)]" />
            AI Production Studio v3.0
          </h3>
          <div className="flex items-center gap-4 text-[10px] font-bold text-gray-600">
            <span className="flex items-center gap-1.5"><Clock size={12} /> {duration} MIN TARGET</span>
          </div>
        </div>

        <div className="flex-1 relative overflow-hidden flex flex-col">
          {isGenerating && (
            <div className="absolute inset-0 z-50 bg-black/40 backdrop-blur-sm flex items-center justify-center p-12">
              <div className="w-full max-w-md space-y-6 text-center">
                <div className="relative inline-block">
                  <div className="absolute inset-0 bg-indigo-500 rounded-full blur-2xl opacity-20 animate-pulse" />
                  <Loader2 size={48} className="text-indigo-500 animate-spin relative" />
                </div>
                <div className="space-y-2">
                  <h4 className="text-xl font-bold tracking-tight text-white">กำลังประพันธ์บทเพลง...</h4>
                  <p className="text-sm text-gray-400">AI กำลังจัดโครงสร้างอย่างเป็นระบบตามมาตรฐานสากล</p>
                </div>
                <div className="w-full bg-gray-800 rounded-full h-1.5 overflow-hidden">
                  <div className="bg-indigo-500 h-full w-1/2 animate-[shimmer_2s_infinite]" style={{ backgroundSize: '200% 100%', backgroundImage: 'linear-gradient(90deg, transparent, rgba(255,255,255,0.2), transparent)' }} />
                </div>
              </div>
            </div>
          )}

          <div className="flex-1 flex flex-col overflow-hidden">
            <div className="px-12 pt-12 pb-6 flex-shrink-0">
              {songTitle && (
                <div className="flex flex-col md:flex-row gap-10 mb-8 items-start">
                  {coverImage && (
                    <div className="flex-shrink-0 relative group">
                      <div className="absolute -inset-1 bg-gradient-to-r from-indigo-500 to-purple-600 rounded-[2rem] blur opacity-20 group-hover:opacity-40 transition duration-1000"></div>
                      <img 
                        src={coverImage} 
                        alt="Cover" 
                        className={`relative rounded-3xl shadow-2xl object-cover border border-white/5 ${imageAspectRatio === '9:16' ? 'w-32 aspect-[9/16]' : 'w-48 aspect-square'}`} 
                      />
                    </div>
                  )}
                  <div className="flex-1 pt-3">
                    <h2 className="text-6xl font-black bg-clip-text text-transparent bg-gradient-to-br from-white via-indigo-100 to-indigo-400 mb-5 leading-[1] tracking-tighter">
                      {songTitle}
                    </h2>
                    <div className="flex flex-wrap gap-x-5 gap-y-3">
                      <span className="bg-indigo-500/10 text-indigo-400 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border border-indigo-500/20">{selectedGenres.join(' • ')}</span>
                      <span className="bg-white/5 text-gray-400 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border border-white/5">{bpm} BPM • {keyName}</span>
