              )}
            </div>

            <div className="flex-1 relative px-12 pb-12 overflow-hidden">
              <div 
                ref={backdropRef}
                className={`absolute inset-x-12 inset-y-0 p-0 pointer-events-none whitespace-pre-wrap break-words font-serif text-2xl leading-[1.8] overflow-y-auto overflow-x-hidden ${theme === 'dark' ? 'text-gray-200' : 'text-gray-800'}`}
                style={{ color: 'transparent', WebkitTextFillColor: 'transparent' }}
              >
                {renderHighlightedText(generatedLyrics)}
              </div>

              <textarea
                ref={textareaRef}
                value={generatedLyrics}
                onChange={(e) => setGeneratedLyrics(e.target.value)}
                onScroll={handleScroll}
                spellCheck={false}
                className={`relative w-full h-full bg-transparent border-none outline-none resize-none font-serif text-2xl leading-[1.8] break-words whitespace-pre-wrap z-10 p-0 ${theme === 'dark' ? 'text-gray-400 focus:text-gray-100' : 'text-gray-600 focus:text-gray-900'} transition-colors duration-300`}
                style={{ caretColor: '#6366f1' }}
                placeholder="Compose your lyrics here..."
              />
