          <span className="text-[10px] font-black text-gray-500 uppercase tracking-[0.4em] flex items-center gap-2">
            <div className="w-1.5 h-1.5 rounded-full bg-indigo-500" />
            Meta JSON Data
          </span>
          <button onClick={() => handleCopy(jsonPrompt)} className="text-[10px] font-black text-indigo-500 hover:text-indigo-400 tracking-widest transition-colors">COPY</button>
        </div>
        <div className="flex-1 p-5 overflow-y-auto font-mono text-[11px] text-indigo-400/60 leading-relaxed custom-scrollbar">
